    'گفتگوی جدید':'گپ نو',
    'گفتگوها':'گپ‌ها',
    'گفتگو':'گپ',
    'گروه‌های':'گروپ‌های',
    'گروه‌ها':'گروپ‌ها',
    'گروه':'گروپ',
    'اعلان‌های':'آگاهی‌های',
    'اعلان‌ها':'آگاهی‌ها',
    'اعلان':'آگاهی',
    'حریم خصوصی':'محرمیت',
    'کنترل':'کنترول',
    'شماره تلفن':'شماره تیلفون',
    'تلفن':'تیلفون',
    'عکس‌های':'تصویرهای',
    'عکس‌ها':'تصویرها',
    'عکس':'تصویر',
    'دوربین':'کمره',
    'ویدئو':'ویدیو',
    'ارسال کردن':'فرستادن',
    'ارسال':'فرستادن',
    'حذف کردن':'پاک کردن',
    'حذف':'پاک کردن',
    'بایگانی':'آرشیف',
    'آرشیو':'آرشیف',
    'کانال‌ها':'چنل‌ها',
    'کانال':'چنل',
    'اشتراک‌گذاری':'شریک‌ساختن',
    'به اشتراک گذاری':'شریک‌ساختن',
    'کپی':'کاپی',
    'لغو':'لغو',
    'بازگشت':'برگشت',
    'اطلاعات':'معلومات',
    'توضیحات':'شرح',
    'جست‌وجو':'جستجو',
    'پیوست‌ها':'ضمیمه‌ها',
    'آخرین بازدید':'آخرین دیدار',
    'وضعیت آنلاین':'حالت آنلاین',
    'ذخیره شد':'ذخیره شد',
    'تلاش دوباره':'دوباره کوشش کنید',
  };
  var result = source;
  for (final entry in terms.entries) {
    result = result.replaceAll(entry.key, entry.value);
  }
  return result;
}

