class AppAccessibilityController extends ChangeNotifier {
  double textScale = 1.0;
  bool highContrast = false;
  Timer? _scaleSaveTimer;
  String get _scope => supabase.auth.currentUser?.id ?? 'guest';

  Future<void> load() async {
    try {
      final p = await SharedPreferences.getInstance();
      textScale = ((p.getDouble('accessibility_text_scale_$_scope') ?? 1.0).clamp(.8, 1.5)).toDouble();
      highContrast = p.getBool('accessibility_high_contrast_$_scope') ?? false;
      notifyListeners();
    } catch (_) {}
  }

  Future<void> setTextScale(double value) async {
    textScale = value.clamp(.8, 1.5).toDouble();
    notifyListeners();
    // Avoid writing preferences on every slider frame; save the final value
    // after the user stops dragging for a moment.
    _scaleSaveTimer?.cancel();
    _scaleSaveTimer = Timer(Duration(milliseconds: 250), () async {
      try {
        final p = await SharedPreferences.getInstance();
        await p.setDouble('accessibility_text_scale_$_scope', textScale);
      } catch (_) {}
    });
  }

  Future<void> setHighContrast(bool value) async {
    highContrast = value;
    notifyListeners();
    try {
      final p = await SharedPreferences.getInstance();
      await p.setBool('accessibility_high_contrast_$_scope', value);
    } catch (_) {}
  }
}

