class _NetworkStatusBanner extends StatefulWidget {
  final Widget child;
  const _NetworkStatusBanner({required this.child});
  @override
  State<_NetworkStatusBanner> createState() => _NetworkStatusBannerState();
}

class _NetworkStatusBannerState extends State<_NetworkStatusBanner> {
  final Connectivity _connectivity = Connectivity();
  StreamSubscription<List<ConnectivityResult>>? _subscription;
  bool offline = false;

  @override
  void initState() {
    super.initState();
    _check();
    _subscription = _connectivity.onConnectivityChanged.listen(_update);
  }

  Future<void> _check() async {
    try {
      _update(await _connectivity.checkConnectivity());
    } catch (_) {}
  }

  void _update(List<ConnectivityResult> results) {
    final next = results.isEmpty || results.every((r) => r == ConnectivityResult.none);
    if (mounted && next != offline) setState(() => offline = next);
  }

  @override
  void dispose() {
    _subscription?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return Stack(
      children: [
        widget.child,
        Positioned(
          top: 0,
          left: 0,
          right: 0,
          child: IgnorePointer(
            child: SafeArea(
              bottom: false,
              child: AnimatedSwitcher(
                duration: kFastMotion,
                transitionBuilder: (child, animation) => SizeTransition(
                  sizeFactor: CurvedAnimation(parent: animation, curve: Curves.easeOutCubic),
                  axisAlignment: -1,
                  child: child,
                ),
                child: offline
                    ? Container(
                        key: ValueKey('offline'),
                        margin: const EdgeInsets.fromLTRB(12, 6, 12, 0),
                        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
                        decoration: BoxDecoration(
                          color: scheme.surfaceContainerHighest.withValues(alpha: .96),
                          borderRadius: BorderRadius.circular(kAppRadius),
                          border: Border.all(color: scheme.outline.withValues(alpha: .16)),
                          boxShadow: const [BoxShadow(blurRadius: 12, offset: Offset(0, 3), color: Color(0x22000000))],
                        ),
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(Icons.cloud_off_rounded, size: 17, color: scheme.error),
                            SizedBox(width: 8),
                            Text(trUi('آفلاین • پیام‌های ذخیره‌شده در دسترس‌اند'), style: TextStyle(fontWeight: FontWeight.w700, color: scheme.onSurface)),
                          ],
                        ),
                      )
                    : SizedBox(key: ValueKey('online')),
              ),
            ),
          ),
        ),
      ],
    );
  }
}

class AradMessenger extends StatelessWidget {
  AradMessenger({super.key});

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(animation: Listenable.merge([appTheme, aradLanguageController, appAccessibility]), builder: (context, _) => MaterialApp(
      locale: aradLanguageController.locale,
      supportedLocales: AppStrings.supported.map((x) => Locale(x)),
      // Flutter's built-in Material widgets do not ship prs/ps delegates; use Persian
      // for built-in date/dialog labels while the app keeps Dari/Pashto selection and RTL.
      localeResolutionCallback: (locale, supportedLocales) {
        if (locale?.languageCode == 'prs' || locale?.languageCode == 'haz' || locale?.languageCode == 'ps') return Locale('fa');
        return locale;
      },
      localizationsDelegates: GlobalMaterialLocalizations.delegates,
