  IconData _iconForSetting(String s)=>switch(s){
    'حساب کاربری'=>Icons.manage_accounts_rounded,'حریم خصوصی'=>Icons.lock_outline_rounded,'امنیت'=>Icons.security_rounded,
    'اعلان‌ها'=>Icons.notifications_none_rounded,'مصرف داده'=>Icons.data_saver_on_rounded,'دسترسی‌پذیری'=>Icons.accessibility_new_rounded,'دسترسی‌های برنامه'=>Icons.admin_panel_settings_rounded,
    'تماس‌ها'=>Icons.call_rounded,'ظاهر'=>Icons.palette_outlined,'پس‌زمینه چت'=>Icons.wallpaper_rounded,'زبان'=>Icons.language_rounded,
    'تنظیمات گفتگو'=>Icons.chat_bubble_outline_rounded,'پوشه‌های گفتگو'=>Icons.folder_copy_outlined,'پیام‌های ذخیره‌شده'=>Icons.bookmark_outline_rounded,
    'داده و ذخیره‌سازی'=>Icons.data_usage_rounded,'پشتیبان‌گیری'=>Icons.backup_outlined,'استیکر و ایموجی'=>Icons.emoji_emotions_outlined,
    'پیام‌رسانی پیشرفته'=>Icons.auto_awesome_rounded,'درباره برنامه'=>Icons.info_outline_rounded,_=>Icons.settings_outlined};
  void _open(String title){
    switch(title){
      case 'حساب کاربری': Navigator.push(context,MaterialPageRoute(builder:(_)=>ProfilePage())); break;
      case 'حریم خصوصی': Navigator.push(context,MaterialPageRoute(builder:(_)=>PrivacySettingsPage())); break;
      case 'امنیت': Navigator.push(context,MaterialPageRoute(builder:(_)=>SecurityCenterPage())); break;
      case 'اعلان‌ها': Navigator.push(context,MaterialPageRoute(builder:(_)=>NotificationsCenterPage())); break;
      case 'مصرف داده': Navigator.push(context,MaterialPageRoute(builder:(_)=>DataSettingsPage())); break;
      case 'دسترسی‌پذیری': Navigator.push(context,MaterialPageRoute(builder:(_)=>AccessibilityPage())); break;
      case 'تماس‌ها': Navigator.push(context,MaterialPageRoute(builder:(_)=>CallHistoryPage())); break;
      case 'ظاهر': _showThemeSheet(); break;
      case 'پس‌زمینه چت': Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatBackgroundPage())); break;
      case 'زبان': _showLanguageSheet(); break;
      case 'تنظیمات گفتگو': Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatSettingsPage())); break;
      case 'پوشه‌های گفتگو': Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatFoldersPage())); break;
      case 'پیام‌های ذخیره‌شده': Navigator.push(context,MaterialPageRoute(builder:(_)=>SavedMessagesPage())); break;
      case 'پیام‌رسانی پیشرفته': Navigator.push(context,MaterialPageRoute(builder:(_)=>AdvancedFeaturesPage())); break;
      case 'درباره برنامه': Navigator.push(context,MaterialPageRoute(builder:(_)=>AboutAppPage())); break;
    }
  }
  void _showThemeSheet()=>showModalBottomSheet(context:context,builder:(_)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[
    Padding(padding:EdgeInsets.all(18),child:Text(trUi('ظاهر برنامه'),style:TextStyle(fontSize:19,fontWeight:FontWeight.w900))),
    RadioListTile<String>(value:'تاریک',groupValue:theme,onChanged:(v)async{if(v==null)return;await appTheme.setDark(true);await saveUserSettings({'theme_mode':'dark'});if(mounted){setState(()=>theme=v);Navigator.pop(context);}},title:Text(trUi('تاریک'))),
    RadioListTile<String>(value:'روشن',groupValue:theme,onChanged:(v)async{if(v==null)return;await appTheme.setDark(false);await saveUserSettings({'theme_mode':'light'});if(mounted){setState(()=>theme=v);Navigator.pop(context);}},title:Text(trUi('روشن'))),
  ])));
  void _showLanguageSheet() => showModalBottomSheet(
    context: context,
    isScrollControlled: true,
    builder: (sheetContext) => SafeArea(
      child: SizedBox(
        height: MediaQuery.of(sheetContext).size.height * .72,
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(18, 18, 18, 10),
              child: Row(children: [
                Expanded(child: Text(trUi('زبان رابط کاربری'),
                  style: const TextStyle(fontSize: 19, fontWeight: FontWeight.w900))),
                IconButton(
                  tooltip: trUi('بستن'),
                  onPressed: () => Navigator.pop(sheetContext),
                  icon: const Icon(Icons.close_rounded),
                ),
              ]),
            ),
            const Divider(height: 1),
            Expanded(
              child: ListView.builder(
                itemCount: AppStrings.supported.length,
                itemBuilder: (context, index) {
                  final code = AppStrings.supported[index];
                  return RadioListTile<String>(
                    key: ValueKey('language-$code'),
                    value: code,
                    groupValue: aradLanguageController.locale.languageCode,
                    title: Text(AppStrings.names[code] ?? code),
                    onChanged: (value) async {
                      if (value == null) return;
                      await aradLanguageController.setLocale(value);
                      await saveUserSettings({'language_code': value});
                      if (mounted) {
                        setState(() => language = AppStrings.names[value] ?? value);
                        Navigator.pop(sheetContext);
                      }
                    },
                  );
                },
              ),
            ),
          ],
        ),
      ),
    ),
  );
  Future<void> _signOut()async{
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(
      title:Text(trUi('خروج از حساب؟')),content:Text(trUi('نشست این دستگاه پایان داده می‌شود.')),
      actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:Text(trUi('لغو'))),FilledButton(style:FilledButton.styleFrom(backgroundColor:Theme.of(ctx).colorScheme.error),onPressed:()=>Navigator.pop(ctx,true),child:Text(trUi('خروج')))],
    ))??false;
    if(ok)await supabase.auth.signOut();
  }
}

class PrivacySettingsPage extends StatefulWidget {
  PrivacySettingsPage({super.key});
  @override
  State<PrivacySettingsPage> createState() => _PrivacySettingsPageState();
}

class _PrivacySettingsPageState extends State<PrivacySettingsPage> {
  bool loading = true;
  bool discoverByPhone = true;
  String phoneVisibility = 'contacts';
  String lastSeenVisibility = 'everybody';
  String profilePhotoVisibility = 'everybody';
  String bioVisibility = 'everybody';
  String forwardsVisibility = 'everybody';
  String callsVisibility = 'everybody';
  String groupsVisibility = 'everybody';
  String voiceMessagesVisibility = 'everybody';
  String p2pVisibility = 'contacts';

  static const _visibilityOptions = <String, String>{
    'everybody': 'همه',
    'contacts': 'مخاطبین من',
    'nobody': 'هیچ‌کس',
  };

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final s = await loadUserSettings();
      if (!mounted) return;
      setState(() {
        discoverByPhone = s['discover_by_phone'] ?? true;
        phoneVisibility = _safeVisibility(s['phone_visibility'], 'contacts');
        lastSeenVisibility = _safeVisibility(s['last_seen_visibility'], 'everybody');
        profilePhotoVisibility = _safeVisibility(s['profile_photo_visibility'], 'everybody');
        bioVisibility = _safeVisibility(s['bio_visibility'], 'everybody');
        forwardsVisibility = _safeVisibility(s['forwards_visibility'], 'everybody');
        callsVisibility = _safeVisibility(s['calls_visibility'], 'everybody');
        groupsVisibility = _safeVisibility(s['groups_visibility'], 'everybody');
        voiceMessagesVisibility = _safeVisibility(s['voice_messages_visibility'], 'everybody');
        p2pVisibility = _safeVisibility(s['p2p_visibility'], 'contacts');
        loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() => loading = false);
      showMsg(context, 'تنظیمات حریم خصوصی بارگذاری نشد: ${_friendlyError(e.toString())}');
    }
  }

  String _safeVisibility(dynamic value, String fallback) {
    final v = value?.toString();
    return _visibilityOptions.containsKey(v) ? v! : fallback;
  }

  String _label(String value) => _visibilityOptions[value] ?? 'مخاطبین من';

  Future<void> _save(String key, dynamic value) async {
    try {
      final values = <String, dynamic>{key: value};
      // Keep the original boolean flags in sync so older runtime checks remain compatible.
      if (key == 'last_seen_visibility') {
        values['show_last_seen'] = value != 'nobody';
        values['show_online'] = value != 'nobody';
      } else if (key == 'phone_visibility') {
        values['show_phone'] = value != 'nobody';
      } else if (key == 'profile_photo_visibility') {
        values['show_profile'] = value != 'nobody';
      }
      await saveUserSettings(values);
    } catch (e) {
      if (!mounted) return;
      showMsg(context, 'ذخیره تنظیمات انجام نشد: ${_friendlyError(e.toString())}');
      await _load();
    }
  }

  Future<void> _chooseVisibility({
    required String title,
    required String key,
    required String current,
    required ValueChanged<String> onChanged,
  }) async {
    final selected = await showModalBottomSheet<String>(
      context: context,
      isScrollControlled: true,
      showDragHandle: true,
      builder: (sheetContext) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 8, 20, 12),
                child: Row(
                  children: [
                    Icon(Icons.shield_outlined, color: Theme.of(sheetContext).colorScheme.primary),                    SizedBox(width: 10),                    Expanded(child: Text(title, style: TextStyle(fontSize: 18, fontWeight: FontWeight.w900))),                  ],
                ),
              ),
              ..._visibilityOptions.entries.map(
                (entry) => RadioListTile<String>(
                  value: entry.key,
                  groupValue: current,
                  title: Text(entry.value),
                  subtitle: Text(_visibilityDescription(entry.key)),
                  secondary: Icon(
                    entry.key == 'everybody'
                        ? Icons.public_rounded
                        : entry.key == 'contacts'
                            ? Icons.people_alt_outlined
                            : Icons.visibility_off_outlined,
                  ),
                  onChanged: (value) => Navigator.pop(sheetContext, value),
                ),
              ),
            ],
          ),
        ),
      ),
    );

    if (selected == null || selected == current) return;
    onChanged(selected);
    await _save(key, selected);
  }

  String _visibilityDescription(String value) {
    switch (value) {
      case 'everybody':
        return 'هر کاربر مجاز به دیدن یا تماس با شما است.';
      case 'contacts':
        return 'فقط افرادی که در مخاطبین شما هستند.';
      default:
        return 'برای دیگران مخفی یا مسدود است.';
    }
  }

  Widget _visibilityTile({
    required IconData icon,
    required String title,
    required String subtitle,
    required String value,
    required String key,
    required ValueChanged<String> onChanged,
  }) {
    final scheme = Theme.of(context).colorScheme;
    return Card(
      child: ListTile(
        leading: CircleAvatar(
          backgroundColor: scheme.primary.withValues(alpha: .13),
          foregroundColor: scheme.primary,
          child: Icon(icon, size: 21),
        ),
        title: Text(trUi(title), style: TextStyle(fontWeight: FontWeight.w700)),
        subtitle: Padding(
          padding: const EdgeInsets.only(top: 3),
          child: Text(trUi(subtitle)),
        ),
        trailing: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(_label(value), style: TextStyle(color: scheme.primary, fontWeight: FontWeight.w800)),
            SizedBox(width: 4),
            Icon(Icons.chevron_left_rounded),
          ],
        ),
        onTap: () => _chooseVisibility(
          title: title,
          key: key,
          current: value,
          onChanged: onChanged,
        ),
      ),
    );
  }

  Widget _section(String title, String subtitle) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(4, 18, 4, 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(trUi(title), style: TextStyle(fontSize: 16, fontWeight: FontWeight.w900)),
          SizedBox(height: 3),
          Text(trUi(subtitle), style: TextStyle(fontSize: 12, color: Theme.of(context).colorScheme.onSurfaceVariant)),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(trUi('حریم خصوصی'))),
      body: loading
          ? Center(child: CircularProgressIndicator())
          : ListView(
              padding: const EdgeInsets.fromLTRB(12, 4, 12, 28),
              children: [
                _section(
                  'شماره تلفن و پیدا شدن حساب',
                  'کنترل کنید چه کسانی شماره شما را ببینند و چه کسانی بتوانند با شماره تلفن شما را پیدا کنند.',
                ),
                _visibilityTile(
                  icon: Icons.phone_rounded,
                  title: 'شماره تلفن',
                  subtitle: 'چه کسانی شماره تلفن شما را ببینند',
                  value: phoneVisibility,
                  key: 'phone_visibility',
                  onChanged: (v) => setState(() => phoneVisibility = v),
                ),
                Card(
                  child: SwitchListTile.adaptive(
                    secondary: Icon(Icons.contact_phone_outlined),
                    title: Text(trUi('پیدا کردن من با شماره تلفن')),
                    subtitle: Text(trUi('اجازه می‌دهد کاربران با شماره ذخیره‌شده شما، حسابتان را پیدا کنند.')),
                    value: discoverByPhone,
                    onChanged: (v) {
                      setState(() => discoverByPhone = v);
                      _save('discover_by_phone', v);
                    },
                  ),
                ),

                _section(
                  'حضور و فعالیت',
                  'تنظیمات آنلاین بودن و آخرین بازدید را جداگانه کنترل کنید.',
                ),
                _visibilityTile(
                  icon: Icons.access_time_rounded,
                  title: 'آخرین بازدید و آنلاین بودن',
                  subtitle: 'چه کسانی زمان فعالیت شما را ببینند',
                  value: lastSeenVisibility,
                  key: 'last_seen_visibility',
                  onChanged: (v) => setState(() => lastSeenVisibility = v),
                ),

