const List<String> _profileCharacters = ['🐺','🦊','🐱','🦁','🐼','🐸','🐉','👾','🤖','👻','🦋','🦂','🕷️','⚡','🌙','🔥','🌌','♟️'];

String _avatarImageUrl(Map<String, dynamic> profile) {
  final raw = (profile['avatar_url'] ?? '').toString().trim();
  if (raw.isEmpty || raw.startsWith('emoji:')) return raw;
  final parsed = Uri.tryParse(raw);
  if (parsed != null && (parsed.scheme == 'https' || parsed.scheme == 'http')) {
    return raw;
  }
  // Some older profiles stored a Storage object path instead of a public URL.
  var path = raw.replaceFirst(RegExp(r'^/?avatars/'), '');
  const publicPrefix = 'storage/v1/object/public/avatars/';
  final prefixIndex = path.indexOf(publicPrefix);
  if (prefixIndex >= 0) path = path.substring(prefixIndex + publicPrefix.length);
  return supabase.storage.from('avatars').getPublicUrl(path);
}

String _avatarFallbackUrl(Map<String, dynamic> profile, String currentUrl) {
  final id = (profile['id'] ?? '').toString().trim();
  if (id.isEmpty) return currentUrl;
  // Older profile rows can contain stale/cached URLs. Rebuild the canonical
  // public object URL from the stable user id as a second attempt.
  return supabase.storage.from('avatars').getPublicUrl('$id/avatar.jpg');
}

void _openAvatarPreview(BuildContext context, Map<String, dynamic> profile) {
  final url = _avatarImageUrl(profile);
  final fallbackUrl = _avatarFallbackUrl(profile, url);
  final isCharacter = url.startsWith('emoji:');
  final previewUrl = url.isNotEmpty && !isCharacter ? url : fallbackUrl;
  showDialog<void>(
    context: context,
    barrierColor: Colors.black87,
    builder: (dialogContext) => Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: const EdgeInsets.all(18),
      child: Stack(
        alignment: Alignment.center,
        children: [
          InteractiveViewer(
            minScale: 0.8,
            maxScale: 4,
            child: previewUrl.isNotEmpty && !isCharacter
                ? Image.network(
                    previewUrl,
                    fit: BoxFit.contain,
                    loadingBuilder: (context, child, progress) =>
                        progress == null
                            ? child
                            : SizedBox(
                                width: 72,
                                height: 72,
                                child: CircularProgressIndicator(color: Colors.white),
                              ),
                    errorBuilder: (_, __, ___) =>
                        fallbackUrl.isNotEmpty && previewUrl != fallbackUrl
                            ? Image.network(
                                fallbackUrl,
                                fit: BoxFit.contain,
                                errorBuilder: (_, __, ___) => Icon(
                                  Icons.broken_image_rounded,
                                  size: 84,
                                  color: Colors.white70,
                                ),
                              )
                            : Icon(
                                Icons.broken_image_rounded,
                                size: 84,
                                color: Colors.white70,
                              ),
                  )
                : Container(
                    width: 220,
                    height: 220,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: Color(0xFF292344),
                      border: Border.all(color: Color(0xFF9B83FF), width: 2),
                    ),
                    child: isCharacter
                        ? Text(url.substring(6), style: TextStyle(fontSize: 112))
                        : Icon(Icons.person_rounded, size: 112, color: Colors.white70),
                  ),
          ),
          Positioned(
            top: 0,
            right: 0,
            child: IconButton.filledTonal(
              tooltip: 'بستن عکس',
              onPressed: () => Navigator.of(dialogContext).pop(),
              icon: Icon(Icons.close_rounded),
            ),
          ),
        ],
      ),
    ),
  );
}

Widget avatar(Map<String, dynamic> profile, {double size = 44}) {
  final url = _avatarImageUrl(profile);
  final fallbackUrl = _avatarFallbackUrl(profile, url);
  final isCharacter = url.startsWith('emoji:');
  final fallback = Container(
    width: size,
    height: size,
    alignment: Alignment.center,
    decoration: BoxDecoration(
      shape: BoxShape.circle,
      color: Color(0xFF292344),
      border: Border.all(color: Color(0xFF9B83FF).withValues(alpha: .55)),
    ),
    child: isCharacter
        ? Text(url.substring(6), style: TextStyle(fontSize: size * .58))
        : Icon(Icons.person_rounded, size: size * .52, color: Colors.white70),
  );
  if (url.isEmpty || isCharacter) return fallback;
  return ClipOval(
    child: SizedBox(
      width: size,
      height: size,
      child: Image.network(
        url,
        width: size,
        height: size,
        fit: BoxFit.cover,
        gaplessPlayback: true,
        loadingBuilder: (context, child, progress) =>
            progress == null ? child : fallback,
        errorBuilder: (context, error, stackTrace) {
          if (fallbackUrl.isNotEmpty && fallbackUrl != url) {
            return Image.network(
              fallbackUrl,
              width: size,
              height: size,
              fit: BoxFit.cover,
              gaplessPlayback: true,
              errorBuilder: (context, retryError, retryStack) =>
                  _signedAvatarFallback(profile, size, fallback),
            );
          }
          return _signedAvatarFallback(profile, size, fallback);
        },
      ),
    ),
  );
}

Widget _signedAvatarFallback(
  Map<String, dynamic> profile,
  double size,
  Widget fallback,
) {
  final id = (profile['id'] ?? '').toString().trim();
  if (id.isEmpty) return fallback;
  return FutureBuilder<String>(
    future: supabase.storage.from('avatars').createSignedUrl('$id/avatar.jpg', 3600),
    builder: (context, snapshot) {
      final signedUrl = snapshot.data;
      if (signedUrl == null || signedUrl.isEmpty) return fallback;
      return Image.network(
        signedUrl,
        width: size,
        height: size,
        fit: BoxFit.cover,
        gaplessPlayback: true,
        errorBuilder: (context, error, stackTrace) => fallback,
      );
    },
  );
}

const _accountEmailsKey = 'arad_account_emails';

Future<List<String>> _savedAccountEmails() async {
  final p = await SharedPreferences.getInstance();
  return p.getStringList(_accountEmailsKey) ?? <String>[];
}

Future<void> _rememberAccount(String email) async {
  final normalized = email.trim().toLowerCase();
  if (normalized.isEmpty) return;
  final p = await SharedPreferences.getInstance();
  final accounts = p.getStringList(_accountEmailsKey) ?? <String>[];
  accounts.removeWhere((e) => e.toLowerCase() == normalized);
  accounts.insert(0, normalized);
  await p.setStringList(_accountEmailsKey, accounts.take(3).toList());
}

Future<void> _removeSavedAccount(String email) async {
  final p = await SharedPreferences.getInstance();
  final accounts = p.getStringList(_accountEmailsKey) ?? <String>[];
  accounts.removeWhere((e) => e.toLowerCase() == email.toLowerCase());
  await p.setStringList(_accountEmailsKey, accounts);
}

class AccountSwitcherPage extends StatefulWidget {
  AccountSwitcherPage({super.key});
  @override State<AccountSwitcherPage> createState()=>_AccountSwitcherPageState();
}
class _AccountSwitcherPageState extends State<AccountSwitcherPage>{
  List<String> accounts=[];
  bool loading=true,busy=false;
  @override void initState(){super.initState();_load();}
  Future<void> _load()async{
    final list=await _savedAccountEmails();
    if(mounted)setState(()=>accounts=list..removeWhere((e)=>e==supabase.auth.currentUser?.email?.toLowerCase()));
    if(mounted)setState(()=>loading=false);
  }
  Future<void> _add()async{
    await rememberCurrentSession();
    if(!mounted)return;
    await Navigator.push(context,MaterialPageRoute(builder:(_)=>LoginPage(addAccount:true)));
    if(mounted)await _load();
  }
  Future<void> _switch(String email)async{
    if(busy)return;
    setState(()=>busy=true);
    try{
      final refresh=await _secureAccounts.read(key:'account_refresh_${email.trim().toLowerCase()}');
      if(refresh==null||refresh.isEmpty){
        if(!mounted)return;
        showMsg(context,'نشست ذخیره‌شده برای این حساب در دسترس نیست؛ از «افزودن حساب» دوباره وارد شوید.');
        return;
      }
      await supabase.auth.setSession(refresh)
          .timeout(Duration(seconds: 15));
      await rememberCurrentSession().timeout(Duration(seconds: 5));
      // Restore this account's own theme and accessibility preferences.
      await appTheme.loadForUser().timeout(Duration(seconds: 5));
      await appAccessibility.load().timeout(Duration(seconds: 5));
      if(!mounted)return;
      Navigator.of(context).pushAndRemoveUntil(MaterialPageRoute(builder:(_)=>ProfileGate()),(route)=>false);
    } on TimeoutException {
      if (mounted) showMsg(context, 'تغییر حساب بیش از حد طول کشید. اینترنت را بررسی و دوباره تلاش کنید.');
    } catch(e) {
      if (mounted) showMsg(context, 'تغییر حساب ناموفق بود؛ ممکن است نشست ذخیره‌شده منقضی شده باشد. از «افزودن حساب» دوباره وارد شوید.');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }
  Future<void> _forget(String email)async{
    await _removeSavedAccount(email);
    await _secureAccounts.delete(key:'account_refresh_${email.trim().toLowerCase()}');
    if(mounted)await _load();
  }
  @override Widget build(BuildContext context){
    final current=(supabase.auth.currentUser?.email??'حساب فعلی').toLowerCase();
    return Scaffold(appBar:AppBar(title:Text(trUi('مدیریت حساب‌ها'))),body:loading
      ?Center(child:CircularProgressIndicator())
      :ListView(padding:const EdgeInsets.all(16),children:[
        Card(child:ListTile(leading:CircleAvatar(child:Icon(Icons.verified_user_rounded)),title:Text(trUi('حساب فعلی')),subtitle:Text(current),trailing:Icon(Icons.check_circle_rounded))),
        SizedBox(height:8),
        Card(child: Padding(padding: EdgeInsets.all(14), child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [Icon(Icons.privacy_tip_outlined), SizedBox(width: 10), Expanded(child: Text(trUi('حساب‌ها فقط در فهرست همین دستگاه ذخیره می‌شوند. هیچ حساب دیگری این فهرست را از دستگاه خودش نمی‌بیند؛ پیام‌ها و دستگاه‌های فعال هر حساب جداگانه‌اند.')))]))),
        if(accounts.isEmpty) Padding(padding:EdgeInsets.symmetric(vertical:20),child:Text(trUi('حساب دیگری برای تغییر سریع روی این دستگاه ذخیره نشده است. برای افزودن حساب جدید، دکمه زیر را بزنید.'),textAlign:TextAlign.center)),
        ...accounts.map((email)=>Card(child:ListTile(
          leading:CircleAvatar(child:Icon(Icons.person_outline_rounded)),title:Text(email),subtitle:Text(trUi('حساب ذخیره‌شده')),
          trailing:PopupMenuButton<String>(onSelected:(v){if(v=='switch')_switch(email);if(v=='forget')_forget(email);},itemBuilder:(_)=>[
            PopupMenuItem(value:'switch',child:Text(trUi('تغییر به این حساب'))),
            PopupMenuItem(value:'forget',child:Text(trUi('حذف از فهرست'))),
          ]),
          onTap:busy?null:()=>_switch(email),
        ))),
        SizedBox(height:12),
        FilledButton.icon(onPressed:busy?null:_add,icon:Icon(Icons.person_add_alt_1_rounded),label:Text(busy?'در حال تغییر حساب...':'افزودن حساب جدید')),
      ]));
  }
}

class AuthGate extends StatelessWidget {
  AuthGate({super.key});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<AuthState>(
      stream: supabase.auth.onAuthStateChange,
      builder: (context, snapshot) {
        final session = supabase.auth.currentSession;
        if (session == null) return LoginPage();

        final user = supabase.auth.currentUser;
        final meta = user?.appMetadata ?? const <String, dynamic>{};
        final role = meta['role']?.toString().toLowerCase();
        final privileged = role == 'owner' || role == 'admin' ||
            meta['owner'] == true ||
            meta['owner']?.toString().toLowerCase() == 'true';
        final verified = user?.emailConfirmedAt != null || privileged;
        if (!verified) {
          return EmailVerificationPage(
            email: user?.email ?? '',
            verificationType: OtpType.email,
            allowCreateUser: false,
          );
        }

        return AppBanGate();
      },
    );
  }
}

class AppBanGate extends StatefulWidget {
  AppBanGate({super.key});

  @override
  State<AppBanGate> createState() => _AppBanGateState();
}

class _AppBanGateState extends State<AppBanGate> {
  late Future<bool> _banCheck;

  @override
  void initState() {
    super.initState();
    // Keep one Future for this gate. Creating isBanned() inside build caused
    // the request to restart on every rebuild and could leave the spinner up.
    _banCheck = _isBanned();
  }

  Future<bool> _isBanned() async {
    final user = supabase.auth.currentUser;
    if (user == null) return false;
    // Do not hold the first screen behind a remote moderation RPC. The RPC
    // can be unavailable on slow networks and leave the user staring at a
    // blank/loading screen. Server-side RLS remains the data-access boundary.
    try {
      return await supabase
          .rpc('is_current_user_app_banned')
          .timeout(Duration(seconds: 2)) == true;
    } catch (error) {
      debugPrint('Ban check unavailable; allowing app UI to open: $error');
      return false;
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _banCheck,
      builder: (context, snapshot) {
        // Do not cover the app while the optional moderation request is pending.
        // Show the authenticated home/profile flow immediately; if the server
        // confirms a ban, switch to the ban screen when the result arrives.
        if (snapshot.data == true) return AppBannedPage();
        return ProfileGate();
      },
    );
  }
}

