class ProfileGate extends StatefulWidget {
  ProfileGate({super.key});

  @override
  State<ProfileGate> createState() => _ProfileGateState();
}

class _ProfileGateState extends State<ProfileGate> {
  late Future<bool> _profileFuture;

  @override
  void initState() {
    super.initState();
    _profileFuture = _hasProfile();
  }

  Future<bool> _hasProfile() async {
    // Auth state can finish restoring a persisted session a moment after the
    // login route is replaced, especially for accounts with an older session.
    // Recover the server-validated user once before treating the account as missing.
    var user = supabase.auth.currentUser;
    if (user == null) {
      try {
        user = (await supabase.auth.getUser().timeout(const Duration(seconds: 8))).user;
      } catch (restoreError) {
        debugPrint('ProfileGate auth restore failed: $restoreError');
      }
    }
    if (user == null) {
      // One short yield lets the auth-state listener finish a pending restore.
      await Future<void>.delayed(const Duration(milliseconds: 350));
      user = supabase.auth.currentUser;
    }
    if (user == null) {
      throw StateError('نشست این حساب بازیابی نشد. اینترنت را بررسی کنید و دوباره وارد شوید.');
    }
    final meta = user.appMetadata;
    final role = meta['role']?.toString().toLowerCase();
    final privileged = role == 'owner' || role == 'admin' ||
        meta['owner'] == true ||
        meta['owner']?.toString().toLowerCase() == 'true';
    if (user.emailConfirmedAt == null && !privileged) return false;
    return true;
  }

  void _retry() {
    setState(() => _profileFuture = _hasProfile());
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _profileFuture,
      builder: (context, snapshot) {
        if (snapshot.connectionState != ConnectionState.done) {
          return Scaffold(
            body: Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  CircularProgressIndicator(),
                  SizedBox(height: 14),
                  Text(trUi('در حال بررسی حساب…')),
                ],
              ),
            ),
          );
        }
        if (snapshot.hasError) {
          return Scaffold(
            body: SafeArea(
              child: Center(
                child: Padding(
                  padding: const EdgeInsets.all(24),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(Icons.cloud_off_rounded, size: 46),
                      SizedBox(height: 12),
                      Text(
                        'بررسی حساب انجام نشد',
                        style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
                        textAlign: TextAlign.center,
                      ),
                      SizedBox(height: 8),
                      Text(
                        'اتصال یا دسترسی به اطلاعات پروفایل مشکل دارد. اتصال اینترنت را بررسی کنید و دوباره تلاش کنید.',
                        textAlign: TextAlign.center,
                      ),
                      SizedBox(height: 16),
                      FilledButton.icon(
                        onPressed: _retry,
                        icon: Icon(Icons.refresh_rounded),
                        label: Text(trUi('تلاش دوباره')),
                      ),
                      TextButton(
                        onPressed: () async {
                          await supabase.auth.signOut();
                          if (mounted) Navigator.of(context).popUntil((route) => route.isFirst);
                        },
                        child: Text(trUi('بازگشت به ورود')),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          );
        }
        return snapshot.data == true
            ? DeviceSessionGate(child: AppLockGate(child: HomePage()))
            : ProfileSetupPage();
      },
    );
  }
}


const _secureAccounts = FlutterSecureStorage();
Future<void> rememberCurrentSession() async {
  final user=supabase.auth.currentUser, session=supabase.auth.currentSession;
  if(user==null||session==null||session.refreshToken==null)return;
  final mail=(user.email??'').trim().toLowerCase(); if(mail.isEmpty)return;
  await _secureAccounts.write(key:'account_refresh_${mail}',value:session.refreshToken);
  await _rememberAccount(mail);
}
Future<List<String>> rememberedAccountEmails()=>_savedAccountEmails();

class LoginPage extends StatefulWidget {
  final bool addAccount;
  LoginPage({super.key,this.addAccount=false});
  @override State<LoginPage> createState()=>_LoginPageState();
}
class _LoginPageState extends State<LoginPage>{
  final email=TextEditingController(),password=TextEditingController(),first=TextEditingController(),last=TextEditingController();
  bool signup=false,busy=false,obscure=true; String? emailError,passwordError;
  bool validEmail(String v)=>RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(v.trim());
  String? passwordMessage(String v){if(v.isEmpty)return 'رمز عبور را وارد کنید';if(v.length<8)return 'حداقل ۸ کاراکتر';if(!RegExp(r'[A-Z]').hasMatch(v))return 'حداقل یک حرف بزرگ';if(!RegExp(r'[0-9]').hasMatch(v))return 'حداقل یک عدد';return null;}
  Future<void> submit() async {
    final mail=email.text.trim().toLowerCase();
    if(!validEmail(mail)){setState(()=>emailError='ایمیل معتبر نیست');return;}
    if(signup){
      if(first.text.trim().isEmpty||last.text.trim().isEmpty){showMsg(context,'نام و نام خانوادگی را وارد کنید.');return;}
      setState(()=>busy=true);
      try {
        // Clear only the previous local session, then request a signup OTP.
        await supabase.auth.signOut().timeout(Duration(seconds: 8));
        await supabase.auth.signInWithOtp(
          email: mail,
          shouldCreateUser: true,
          data: {
            'first_name': first.text.trim(),
            'last_name': last.text.trim(),
            'full_name': '${first.text.trim()} ${last.text.trim()}',
          },
        ).timeout(Duration(seconds: 15));
        if (mounted) {
          Navigator.push(context, MaterialPageRoute(
            builder: (_) => EmailVerificationPage(
              email: mail,
              verificationType: OtpType.email,
              allowCreateUser: true,
            ),
          ));
        }
      } on AuthException catch (e) {
        if (mounted) showMsg(context, 'ارسال کد ثبت‌نام ناموفق بود: ${e.message}');
      } catch (e) {
        if (mounted) showMsg(context,
          e is TimeoutException
            ? 'سرور در زمان تعیین‌شده پاسخ نداد. اینترنت را بررسی و دوباره تلاش کنید.'
            : 'ارسال کد ثبت‌نام ناموفق بود. اتصال اینترنت را بررسی کنید.');
      } finally {
        if (mounted) setState(() => busy = false);
      }
    }else{
      setState(()=>busy=true);
      try{
        // Keep a valid existing session; otherwise authenticate with email + password.
        final current = supabase.auth.currentSession;
        final currentEmail = (supabase.auth.currentUser?.email ?? '').trim().toLowerCase();
        if(current != null && currentEmail == mail){
          await rememberCurrentSession();
          if(mounted) Navigator.of(context).pushAndRemoveUntil(
            MaterialPageRoute(builder:(_)=>ProfileGate()), (route)=>false);
          return;
        }
        final secret = password.text;
        if(secret.isEmpty){showMsg(context,'رمز عبور را وارد کنید.');return;}
        await supabase.auth.signInWithPassword(email:mail,password:secret)
            .timeout(Duration(seconds: 15));
        // Session persistence and theme loading must never block navigation
        // after Supabase has authenticated the user successfully.
        try {
          await rememberCurrentSession().timeout(Duration(seconds: 4));
        } catch (_) {}
        if (!mounted) return;
        Navigator.of(context).pushAndRemoveUntil(
          MaterialPageRoute(builder: (_) => ProfileGate()),
          (route) => false,
        );
        // Load user preferences in the background; they are non-critical to login.
        appTheme.loadForUser().timeout(Duration(seconds: 5)).catchError((_) {});
      }on AuthException catch(e){
        if(mounted)showMsg(context,'ورود انجام نشد: ${e.message}');
      }catch(e){
        if(mounted)showMsg(context,'ارتباط با سرور یا ورود مشکل داشت: ${_friendlyError(e.toString())}');
      }finally{if(mounted)setState(()=>busy=false);}
    }
  }
  Future<void> signInWithGoogle() async {
    if (busy) return;
    setState(() => busy = true);
    try {
      if (kIsWeb) {
        // Web OAuth returns to this site's origin after Google verifies the user.
        await supabase.auth.signInWithOAuth(
          OAuthProvider.google,
          redirectTo: authRedirectUrl(),
        );
        return;
      }

      // Native Android/iOS Google sign-in needs the Web OAuth client ID.
      // The APK workflow passes it through GOOGLE_SERVER_CLIENT_ID.
      if (googleServerClientId.isEmpty) {
        throw AuthException(
          'تنظیم ورود گوگل کامل نیست: شناسه Web Client در ساخت APK تنظیم نشده است.',
        );
      }
      await _ensureGoogleSignInInitialized();
      final account = await googleSignIn.authenticate();
      final idToken = account.authentication.idToken;
      if (idToken == null || idToken.isEmpty) {
        throw AuthException(
          'از گوگل ID token دریافت نشد. شناسه Web OAuth و تنظیمات OAuth اندروید را بررسی کنید.',
        );
      }
      // Supabase Google native sign-in requires both ID and access tokens.
      final authorization = await account.authorizationClient.authorizationForScopes(
        const <String>[],
      );
      final accessToken = authorization?.accessToken;
      if (accessToken == null || accessToken.isEmpty) {
        throw AuthException(
          'از گوگل access token دریافت نشد. تنظیمات OAuth و مجوزهای حساب را بررسی کنید.',
        );
      }
      await supabase.auth.signInWithIdToken(
        provider: OAuthProvider.google,
        idToken: idToken,
        accessToken: accessToken,
      );
      await rememberCurrentSession();
      await appTheme.loadForUser();
      if (mounted) {
        Navigator.of(context).pushAndRemoveUntil(
          MaterialPageRoute(builder: (_) => ProfileGate()),
          (route) => false,
        );
      }
    } on AuthException catch (e) {
      if (mounted) showMsg(context, 'ورود با گوگل ناموفق بود: ${e.message}');
    } catch (e) {
      if (mounted) showMsg(context, 'ورود با گوگل ناموفق بود: ${_friendlyError(e.toString())}');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }

  Future<void> forgotPassword() async {
    final mail = email.text.trim().toLowerCase();
    if (!validEmail(mail)) {
      showMsg(context, 'ابتدا ایمیل معتبر را وارد کنید.');
      return;
    }
    if (busy) return;
    setState(() => busy = true);
    try {
      await supabase.auth.resetPasswordForEmail(mail)
          .timeout(Duration(seconds: 15));
      if (mounted) showMsg(context, 'اگر این ایمیل ثبت شده باشد، لینک بازیابی ارسال می‌شود. پوشه هرزنامه را هم بررسی کنید.');
    } on AuthException catch (e) {
      if (mounted) showMsg(context, 'درخواست بازیابی ناموفق بود: ${e.message}');
    } catch (e) {
      if (mounted) showMsg(context,
        e is TimeoutException
          ? 'پاسخی از سرور نرسید. اینترنت را بررسی و دوباره تلاش کنید.'
          : 'درخواست بازیابی انجام نشد. اتصال اینترنت را بررسی کنید.');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }
  @override Widget build(BuildContext context){final t=Theme.of(context);return Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(22),child:ConstrainedBox(constraints:BoxConstraints(maxWidth:520),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
    Container(
      padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 24),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: [t.colorScheme.primary, t.colorScheme.secondary],
          begin: Alignment.topRight,
          end: Alignment.bottomLeft,
        ),
        borderRadius: BorderRadius.circular(24),
      ),
      child: Column(
        children: [
          Text(
            'Arad Messenger',
            textAlign: TextAlign.center,
            style: TextStyle(
              fontSize: 27,
              fontWeight: FontWeight.w900,
              color: t.colorScheme.onPrimary,
              letterSpacing: .2,
            ),
          ),
          SizedBox(height: 10),
          Text(
            'ارتباطی ساده، سریع و امن.',
            textAlign: TextAlign.center,
            style: TextStyle(
              fontSize: 15,
              fontWeight: FontWeight.w600,
              color: t.colorScheme.onPrimary.withValues(alpha: .94),
            ),
          ),
        ],
      ),
    ),
    SizedBox(height:20),
    Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(children:[
      if(signup)...[TextField(controller:first,decoration:InputDecoration(labelText:'نام',prefixIcon:Icon(Icons.person_outline))),SizedBox(height:12),TextField(controller:last,decoration:InputDecoration(labelText:'نام خانوادگی',prefixIcon:Icon(Icons.badge_outlined))),SizedBox(height:12)],
      TextField(controller:email,keyboardType:TextInputType.emailAddress,onChanged:(v)=>setState(()=>emailError=validEmail(v)?null:'ایمیل معتبر نیست'),decoration:InputDecoration(labelText:'ایمیل',errorText:emailError,prefixIcon:Icon(Icons.email_outlined))),
      if(!signup)...[TextField(controller:password,obscureText:obscure,onChanged:(v)=>setState(()=>passwordError=passwordMessage(v)),decoration:InputDecoration(labelText:'رمز عبور',errorText:passwordError,prefixIcon:Icon(Icons.lock_outline_rounded),suffixIcon:IconButton(onPressed:()=>setState(()=>obscure=!obscure),icon:Icon(obscure?Icons.visibility:Icons.visibility_off)))),],
      if(!signup)Align(alignment:Alignment.centerRight,child:TextButton(onPressed:busy?null:forgotPassword,child:Text(trUi('رمز را فراموش کرده‌ام')))),
      SizedBox(height:8),SizedBox(height:52,width:double.infinity,child:FilledButton(onPressed:busy?null:submit,child:busy?CircularProgressIndicator():Text(signup?'ثبت‌نام و دریافت کد':'ورود به حساب'))),
      if (!signup) ...[
        SizedBox(height: 12),
        Row(children: [
          Expanded(child: Divider()),
          Padding(padding: EdgeInsets.symmetric(horizontal: 12), child: Text(trUi('یا'))),
          Expanded(child: Divider()),
        ]),
        SizedBox(height: 12),
        SizedBox(
          height: 50,
          width: double.infinity,
          child: OutlinedButton(
            onPressed: busy ? null : signInWithGoogle,
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(trUi('G'), style: TextStyle(fontSize: 22, fontWeight: FontWeight.w900, color: Color(0xFF4285F4))),
                SizedBox(width: 10),
                Text(trUi('ورود با گوگل')),
              ],
            ),
          ),
        ),
      ],
      SizedBox(height:8),TextButton(onPressed:busy?null:()=>setState(()=>signup=!signup),child:Text(signup?'حساب دارم؛ ورود':'حساب ندارم؛ ثبت‌نام'))
    ])))
  ]))))));}
  @override void dispose(){email.dispose();password.dispose();first.dispose();last.dispose();super.dispose();}
}

class PasswordSetupPage extends StatefulWidget{PasswordSetupPage({super.key});@override State<PasswordSetupPage> createState()=>_PasswordSetupPageState();}
class _PasswordSetupPageState extends State<PasswordSetupPage>{
 final p=TextEditingController(),c=TextEditingController();bool busy=false;
 String? err(String v)=>v.length<8||!RegExp(r'[A-Z]').hasMatch(v)||!RegExp(r'[0-9]').hasMatch(v)?'حداقل ۸ کاراکتر، یک حرف بزرگ و یک عدد لازم است':null;
 Future<void> save()async{if(p.text!=c.text){showMsg(context,'رمزها یکسان نیستند.');return;}final e=err(p.text);if(e!=null){showMsg(context,e);return;}setState(()=>busy=true);try{await supabase.auth.updateUser(UserAttributes(password:p.text));await rememberCurrentSession();if(mounted)Navigator.of(context).pushAndRemoveUntil(MaterialPageRoute(builder:(_)=>ProfileGate()),(_)=>false);}catch(e){if(mounted)showMsg(context,'ذخیره رمز ناموفق بود: $e');}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(trUi('ساخت رمز عبور'))),body:ListView(padding:const EdgeInsets.all(20),children:[Text(trUi('ساخت رمز عبور'),style:TextStyle(fontSize:22,fontWeight:FontWeight.w900)),SizedBox(height:18),TextField(controller:p,obscureText:true,onChanged:(_)=>setState((){}),decoration:InputDecoration(labelText:'رمز عبور',errorText:err(p.text))),SizedBox(height:12),TextField(controller:c,obscureText:true,decoration:InputDecoration(labelText:'تکرار رمز عبور')),SizedBox(height:20),FilledButton(onPressed:busy?null:save,child:Text(busy?'در حال ذخیره...':'ادامه'))]));
 @override void dispose(){p.dispose();c.dispose();super.dispose();}
}
class EmailVerificationPage extends StatefulWidget {
  final String email;
  final OtpType verificationType;
  final bool allowCreateUser;
  final bool ownerOnly;

  EmailVerificationPage({
    super.key,
    required this.email,
    this.verificationType = OtpType.email,
    this.allowCreateUser = false,
    this.ownerOnly = false,
  });

  @override
  State<EmailVerificationPage> createState() => _EmailVerificationPageState();
}

class _EmailVerificationPageState extends State<EmailVerificationPage> {
  final code = TextEditingController();
  bool busy = false;
  bool resending = false;
  bool _verificationStarted = false;
  int resendCount = 0;
  int resendCooldown = 60;
  Timer? resendTimer;
  static const int maxResends = 3;

  Future<void> verify() async {
    final token = normalizeOtpDigits(code.text).replaceAll(RegExp(r'\s+'), '');
    if (token != code.text) {
      code.value = TextEditingValue(
        text: token,
        selection: TextSelection.collapsed(offset: token.length),
      );
    }
    if (token.length != 6 || !RegExp(r'^\d{6}$').hasMatch(token)) {
      showMsg(context, 'کد تأیید باید دقیقاً ۶ رقم باشد.');
      return;
    }
    if (busy || _verificationStarted) return;

    _verificationStarted = true;
    setState(() => busy = true);
    try {
      final response = await supabase.auth.verifyOTP(
        type: OtpType.email,
        email: widget.email.trim().toLowerCase(),
        token: token,
      );

      if (response.session == null || supabase.auth.currentSession == null) {
        throw AuthException('تأیید کد انجام نشد. دوباره تلاش کنید.');
      }

      if (widget.ownerOnly) {
        final user = supabase.auth.currentUser;
        if (user == null) {
          throw AuthException('حساب مالک پیدا نشد.');
        }
        final adminRow = await supabase
            .from('admin_users')
            .select('user_id')
            .eq('user_id', user.id)
            .maybeSingle();
        if (adminRow == null) {
          await supabase.auth.signOut();
          throw AuthException('این ایمیل دسترسی مالک ندارد.');
        }
      }

      if (widget.allowCreateUser) { if (!mounted) return; Navigator.of(context).pushReplacement(MaterialPageRoute(builder: (_) => PasswordSetupPage())); return; }
      await rememberCurrentSession();
      // Theme is private to the signed-in account, not shared between accounts.
      await appTheme.loadForUser();

      if (!mounted) return;
      Navigator.of(context).pushAndRemoveUntil(
        MaterialPageRoute(builder: (_) => ProfileGate()),
        (route) => false,
      );
    } on AuthException catch (e) {
      if (!mounted) return;
      showMsg(context, 'تأیید کد ناموفق بود: ${e.message}');
      code.clear();
    } catch (e) {
      if (!mounted) return;
      showMsg(context, 'تأیید کد ناموفق بود: $e');
      code.clear();
    } finally {
      if (mounted) setState(() => busy = false);
      _verificationStarted = false;
    }
  }

  void startResendCooldown() {
    resendTimer?.cancel();
    setState(() => resendCooldown = 60);
    resendTimer = Timer.periodic(Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      if (resendCooldown <= 1) {
        timer.cancel();
        setState(() => resendCooldown = 0);
      } else {
        setState(() => resendCooldown--);
      }
    });
  }

  Future<void> resend() async {
    if (resendCount >= maxResends || resending || resendCooldown > 0) {
      showMsg(context, resendCooldown > 0
          ? 'برای ارسال مجدد $resendCooldown ثانیه صبر کنید.'
          : 'سقف ارسال مجدد کد تمام شده است.');
      return;
    }
    setState(() => resending = true);
    try {
      await supabase.auth.signInWithOtp(
        email: widget.email.trim().toLowerCase(),
        shouldCreateUser: widget.allowCreateUser,
      );
      if (!mounted) return;
      setState(() => resendCount++);
      startResendCooldown();
      code.clear();
      showMsg(context, 'کد ۶ رقمی جدید ارسال شد.');
    } on AuthException catch (e) {      if (mounted) showMsg(context, 'ارسال کد ناموفق بود: ${e.message}');
    } catch (e) {      if (mounted) showMsg(context, 'ارسال کد ناموفق بود: $e');
    } finally {      if (mounted) setState(() => resending = false);
    }
  }

  @override
  void initState() {
    super.initState();
    startResendCooldown();
  }

  @override
  void dispose() {
    resendTimer?.cancel();
    code.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Scaffold(
      appBar: AppBar(title: Text(trUi('تأیید ایمیل'))),
      body: SafeArea(
        child: Center(
          child: SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(22, 24, 22, 32),
            child: ConstrainedBox(
              constraints: BoxConstraints(maxWidth: 520),
              child: Column(
                children: [
                  Container(
                    width: 86,
                    height: 86,
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                        colors: [
                          theme.colorScheme.primary,
                          theme.colorScheme.secondary,
                        ],
                      ),
                      shape: BoxShape.circle,
                    ),
                    child: Icon(
                      Icons.mark_email_read_rounded,
                      size: 42,
                      color: Colors.white,
                    ),
                  ),
                  SizedBox(height: 20),
                  Text(
                    'کد تأیید ارسال شد',
                    style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold),
                  ),
                  SizedBox(height: 8),
                  Card(
                    child: Padding(
                      padding: const EdgeInsets.all(20),
                      child: Column(
                        children: [
                          Text(
                            'کد ۶ رقمی برای این ایمیل ارسال شده است:',
                            textAlign: TextAlign.center,
                          ),
                          SizedBox(height: 8),
                          Text(
                            widget.email,
                            textAlign: TextAlign.center,
                            style: TextStyle(
                              fontWeight: FontWeight.bold,
                              fontSize: 16,
                            ),
                          ),
                          SizedBox(height: 8),
                          Text(
                            'کد فقط وقتی بررسی می‌شود که روی «تأیید و ورود» بزنید. کدهای قبلی یا منقضی‌شده قابل استفاده نیستند.',
                            textAlign: TextAlign.center,
                          ),
                        ],
                      ),
                    ),
                  ),
                  SizedBox(height: 20),
                  TextField(
                    controller: code,
                    keyboardType: TextInputType.number,
                    textInputAction: TextInputAction.done,
                    textAlign: TextAlign.center,
                    maxLength: 6,
                    autofillHints: const [AutofillHints.oneTimeCode],
                    textDirection: TextDirection.ltr,
                    inputFormatters: [
                      FilteringTextInputFormatter.allow(RegExp(r'[0-9۰-۹٠-٩]')),
                    ],
                    style: TextStyle(
                      fontSize: 26,
                      fontWeight: FontWeight.w800,
                      letterSpacing: 8,
                    ),
                    onChanged: (value) {
                      final normalized = normalizeOtpDigits(value);
                      if (normalized != value) {
                        code.value = TextEditingValue(
                          text: normalized,
                          selection: TextSelection.collapsed(offset: normalized.length),
                        );
                      }
                    },
                    decoration: InputDecoration(
                      counterText: '',
                      labelText: 'کد ۶ رقمی',
                      hintText: '------',
                      prefixIcon: Icon(Icons.password_rounded),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(16),
                      ),
                    ),
                  ),
                  SizedBox(height: 12),
                  SizedBox(
                    width: double.infinity,
                    child: FilledButton(
                      onPressed: busy ? null : verify,
                      child: Text(busy ? 'در حال تأیید...' : 'تأیید و ورود'),
                    ),
                  ),
                  TextButton(
                    onPressed: (resending || resendCount >= maxResends || resendCooldown > 0) ? null : resend,
                    child: Text(
                      resending
                          ? 'در حال ارسال کد...'
                          : resendCount >= maxResends
                              ? 'سقف ارسال مجدد تمام شد'
                              : resendCooldown > 0
                                  ? 'ارسال مجدد تا $resendCooldown ثانیه دیگر'
                                  : 'ارسال مجدد کد (${maxResends - resendCount})',
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class ProfileSetupPage extends StatefulWidget {
  ProfileSetupPage({super.key});
  @override
  State<ProfileSetupPage> createState() => _ProfileSetupPageState();
}

class _ProfileSetupPageState extends State<ProfileSetupPage> {
  final name = TextEditingController();
  final username = TextEditingController();
  final bio = TextEditingController();
  XFile? avatarImage;
  Uint8List? avatarBytes;
  String? existingAvatarUrl;
  String? selectedCharacter;
  String? nameError;
  String? usernameError;
  bool loading = true;
  bool busy = false;

  Future<void> load() async {
    try {
      final user = supabase.auth.currentUser!;
      final row = await supabase.from('profiles').select('id,username,display_name,avatar_url,bio,is_online,last_seen,is_verified,created_at,joined_at').eq('id', user.id).maybeSingle();
      if (row != null) {
        existingAvatarUrl = '${row['avatar_url'] ?? ''}';
        if ((existingAvatarUrl ?? '').startsWith('emoji:')) selectedCharacter = existingAvatarUrl!.substring(6);
        name.text = '${row['display_name'] ?? ''}';
        username.text = '${row['username'] ?? ''}';
        bio.text = '${row['bio'] ?? ''}';
      } else {
        final metadata = user.userMetadata ?? <String, dynamic>{};
        final fullName = (metadata['full_name'] ?? '').toString().trim();
        if (fullName.isNotEmpty) name.text = fullName;
      }
    } catch (_) {}
    if (mounted) setState(() => loading = false);
  }

  Future<void> pickAvatar(ImageSource source) async {
    try {
      final image = await ImagePicker().pickImage(source: source, imageQuality: 88, maxWidth: 900, maxHeight: 900);
      if (image == null) return;
      final bytes = await image.readAsBytes();
      if (mounted) setState(() { avatarImage = image; avatarBytes = bytes; });
    } catch (e) {
      if (mounted) showMsg(context, 'انتخاب عکس ناموفق بود: $e');
    }
  }

  Future<void> chooseAvatar() async {
    await showModalBottomSheet<void>(
      context: context,
      builder: (context) => SafeArea(
        child: Wrap(children: [
          ListTile(leading: Icon(Icons.camera_alt), title: Text(trUi('دوربین')), onTap: () { Navigator.pop(context); pickAvatar(ImageSource.camera); }),
          ListTile(leading: Icon(Icons.photo_library), title: Text(trUi('گالری')), onTap: () { Navigator.pop(context); pickAvatar(ImageSource.gallery); }),
        ]),
      ),
    );
  }

  Future<void> save() async {
    final displayName = name.text.trim();
    final userName = username.text.trim().replaceFirst('@', '');
    if (displayName.isEmpty) {
      setState(() => nameError = 'نام نمایشی را وارد کنید.');
      return;
    }
    if (userName.isNotEmpty && !RegExp(r'^[A-Za-z0-9_]{3,32}$').hasMatch(userName)) {
      setState(() => usernameError = 'نام کاربری باید ۳ تا ۳۲ کاراکتر و فقط شامل حروف انگلیسی، عدد یا _ باشد.');
      return;
    }
    setState(() => busy = true);
    try {
      final uid = supabase.auth.currentUser!.id;
      final data = <String, dynamic>{
        'id': uid,
        'display_name': displayName,
        'username': userName,
        'bio': bio.text.trim(),
        'country': '${supabase.auth.currentUser?.userMetadata?['country'] ?? ''}',
        'is_online': true,
        'last_seen': DateTime.now().toIso8601String(),
      };
      if (avatarImage != null) {
        final bytes = avatarBytes ?? await avatarImage!.readAsBytes();
        final path = '$uid/avatar.jpg';
        await supabase.storage.from('avatars').uploadBinary(path, bytes, fileOptions: FileOptions(upsert: true, contentType: 'image/jpeg'));
        data['avatar_url'] = '${supabase.storage.from('avatars').getPublicUrl(path)}?v=${DateTime.now().millisecondsSinceEpoch}';
      } else if (selectedCharacter != null) {
        data['avatar_url'] = 'emoji:$selectedCharacter';
      }
      await supabase.from('profiles').upsert(data);
      if (mounted) { showMsg(context, 'پروفایل با موفقیت ذخیره شد.'); Navigator.pop(context); }
    } catch (e) {
      if (mounted) showMsg(context, 'ذخیره پروفایل ناموفق بود: $e');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }

  @override
  void initState() { super.initState(); load(); }

  @override
  void dispose() { name.dispose(); username.dispose(); bio.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    if (loading) return Scaffold(body: Center(child: CircularProgressIndicator()));
    return Scaffold(
      appBar: AppBar(title: Text(trUi('پروفایل شما'))),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          Card(child: Padding(padding: const EdgeInsets.all(14), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(trUi('کاراکتر پروفایل'), style: TextStyle(fontWeight: FontWeight.w800, fontSize: 16)),
            SizedBox(height: 5),
            Text(trUi('کاراکتر آماده انتخاب کن یا عکس خودت را از دوربین و گالری بگذار.')),
            SizedBox(height: 10),
            Wrap(spacing: 8, runSpacing: 8, children: _profileCharacters.map((character) => InkWell(
              borderRadius: BorderRadius.circular(30),
              onTap: () => setState(() { selectedCharacter = character; avatarImage = null; avatarBytes = null; existingAvatarUrl = 'emoji:$character'; }),
              child: Container(width: 44, height: 44, alignment: Alignment.center,
                decoration: BoxDecoration(color: selectedCharacter == character ? Theme.of(context).colorScheme.primaryContainer : Theme.of(context).colorScheme.surfaceContainerHighest, borderRadius: BorderRadius.circular(52), border: Border.all(color: selectedCharacter == character ? Theme.of(context).colorScheme.primary : Colors.transparent, width: 2)),
                child: Text(character, style: TextStyle(fontSize: 25))),
            )).toList()),
          ]))),
          SizedBox(height: 12),
          Center(
            child: GestureDetector(
              onTap: chooseAvatar,
              child: Stack(
                clipBehavior: Clip.none,
                children: [
                  CircleAvatar(
                    radius: 58,
                    backgroundColor: selectedCharacter != null ? Color(0xFF292344) : null,
                    backgroundImage: avatarBytes != null
                        ? MemoryImage(avatarBytes!)
                        : (existingAvatarUrl != null && existingAvatarUrl!.isNotEmpty && !existingAvatarUrl!.startsWith('emoji:') ? NetworkImage(existingAvatarUrl!) : null),
                    child: avatarBytes != null ? null : selectedCharacter != null
                        ? Text(selectedCharacter!, style: TextStyle(fontSize: 48))
                        : (existingAvatarUrl == null || existingAvatarUrl!.isEmpty) ? Icon(Icons.person, size: 58) : null,
                  ),
                  Positioned(bottom: -4, right: -4, child: CircleAvatar(radius: 20, child: Icon(Icons.camera_alt, size: 20))),
                ],
              ),
            ),
          ),
          SizedBox(height: 22),
          TextField(
            controller: name,
            onChanged: (v) => setState(() => nameError = v.trim().isEmpty ? 'نام نمایشی را وارد کنید.' : null),
            decoration: InputDecoration(labelText: 'نام نمایشی', errorText: nameError, border: OutlineInputBorder()),
          ),
          SizedBox(height: 12),
          TextField(
            controller: username,
            onChanged: (v) {
              final u = v.trim().replaceFirst('@', '');
              setState(() => usernameError = u.isEmpty || RegExp(r'^[A-Za-z0-9_]{3,32}$').hasMatch(u) ? null : 'نام کاربری نامعتبر است.');
            },
            decoration: InputDecoration(labelText: 'نام کاربری', errorText: usernameError, prefixText: '@', border: OutlineInputBorder()),
          ),
          SizedBox(height: 12),
          TextField(controller: bio, maxLines: 3, decoration: InputDecoration(labelText: 'معرفی کوتاه', border: OutlineInputBorder())),
          SizedBox(height: 16),
          FilledButton(onPressed: busy ? null : save, child: Text(busy ? 'در حال ذخیره...' : 'ادامه')),
        ],
      ),
    );
  }
}


