String _homeTime(dynamic value) {
  final dt = DateTime.tryParse('$value')?.toLocal();
  if (dt == null) return '';
  final now = DateTime.now();
  if (dt.year == now.year && dt.month == now.month && dt.day == now.day) return dt.hour.toString().padLeft(2, '0') + ':' + dt.minute.toString().padLeft(2, '0');
  return dt.day.toString().padLeft(2, '0') + '/' + dt.month.toString().padLeft(2, '0');
}
Future<void> openAradLink(BuildContext context, Uri uri) async {
  if (uri.scheme.toLowerCase() != 'arad') return;
  final host = uri.host.toLowerCase();
  final uid = supabase.auth.currentUser?.id;
  if (uid == null) {
    showMsg(context, 'برای باز کردن لینک ابتدا وارد آراد شوید.');
    return;
  }
  Future<void> openChat(String conversationId, String title, {String? messageId}) async {
    final membership = await supabase.from('conversation_members').select('user_id')
        .eq('conversation_id', conversationId).eq('user_id', uid).maybeSingle();
    if (membership == null) {
      showMsg(context, 'به این گفتگوی خصوصی دسترسی ندارید؛ لینک دعوت معتبر لازم است.');
      return;
    }
    if (!context.mounted) return;
    await Navigator.of(context, rootNavigator: true).push(MaterialPageRoute(
      builder: (_) => ChatPage(id: conversationId, title: title, targetMessageId: messageId),
    ));
  }
  try {
    if (host == 'invite') {
      final code = (uri.queryParameters['code'] ?? '').trim();
      if (code.isEmpty) return;
      final result = await supabase.rpc('join_conversation_by_invite', params: {'p_code': code});
      final id = result.toString();
      final c = Map<String, dynamic>.from(await supabase.from('conversations')
          .select('id,type,title').eq('id', id).single());
      final member = await supabase.from('conversation_members').select('user_id')
          .eq('conversation_id', id).eq('user_id', uid).maybeSingle();
      if (member == null) {
        showMsg(context, 'درخواست عضویت ثبت شد؛ پس از تأیید مدیر می‌توانید وارد شوید.');
        return;
      }
      if (!context.mounted) return;
      await Navigator.of(context, rootNavigator: true).push(MaterialPageRoute(
        builder: (_) => ChatPage(id: id, title: (c['title'] ?? (c['type'] == 'channel' ? 'کانال' : 'گروه')).toString()),
      ));
      return;
    }
    if (host == 'story') {
      if (uri.pathSegments.isEmpty) return;
      final storyId = Uri.decodeComponent(uri.pathSegments.first).trim();
      if (storyId.isEmpty || !context.mounted) return;
      await Navigator.of(context, rootNavigator: true).push(MaterialPageRoute(
        builder: (_) => StoriesPage(initialStoryId: storyId),
      ));
      return;
    }
    if (host == 'group') {
      if (uri.pathSegments.isEmpty) return;
      final key = Uri.decodeComponent(uri.pathSegments.first).trim();
      Map<String, dynamic>? c = await supabase.from('conversations')
          .select('id,type,title,username,is_public').eq('username', key).maybeSingle();
      c ??= await supabase.from('conversations').select('id,type,title,username,is_public')
          .eq('id', key).maybeSingle();
      if (c == null || c['type'] == 'direct') {
        showMsg(context, 'لینک گروه معتبر نیست یا گروه در دسترس نیست.');
        return;
      }
      final id = c['id'].toString();
      var member = await supabase.from('conversation_members').select('user_id')
          .eq('conversation_id', id).eq('user_id', uid).maybeSingle();
      if (member == null && c['is_public'] == true && (c['username'] ?? '').toString().isNotEmpty) {
        await supabase.rpc('join_public_conversation', params: {'p_username': c['username']});
        member = await supabase.from('conversation_members').select('user_id')
            .eq('conversation_id', id).eq('user_id', uid).maybeSingle();
      }
      if (member == null) {
        showMsg(context, c['is_public'] == true
            ? 'درخواست عضویت ثبت شد؛ اگر تأیید مدیر لازم باشد باید منتظر بمانید.'
            : 'این گروه خصوصی است؛ از مدیر گروه لینک دعوت خصوصی بگیرید.');
        return;
      }
      await openChat(id, (c['title'] ?? c['username'] ?? 'گروه').toString());
      return;
    }
    if (host == 'chat' && uri.pathSegments.length >= 3 && uri.pathSegments[1] == 'message') {
      final conversationId = uri.pathSegments[0];
      final messageId = uri.pathSegments[2];
      final c = await supabase.from('conversations').select('id,type,title,username,is_public')
          .eq('id', conversationId).maybeSingle();
      if (c == null) {
        showMsg(context, 'این گفتگو پیدا نشد یا لینک آن دیگر معتبر نیست.');
        return;
      }
      var member = await supabase.from('conversation_members').select('user_id')
          .eq('conversation_id', conversationId).eq('user_id', uid).maybeSingle();
      if (member == null && c['is_public'] == true && (c['username'] ?? '').toString().isNotEmpty) {
        await supabase.rpc('join_public_conversation', params: {'p_username': c['username']});
        member = await supabase.from('conversation_members').select('user_id')
            .eq('conversation_id', conversationId).eq('user_id', uid).maybeSingle();
      }
      if (member == null) {
        showMsg(context, 'برای دیدن این پیام ابتدا باید عضو گفتگو شوید؛ عضویت خصوصی است یا در انتظار تأیید است.');
        return;
      }
      final title = (c['title'] ?? c['username'] ?? (c['type'] == 'direct' ? 'گفتگو' : 'گروه')).toString();
      await openChat(conversationId, title, messageId: messageId);
      return;
    }
  } catch (e) {
    if (context.mounted) showMsg(context, 'باز کردن لینک ناموفق بود: ${_friendlyError(e.toString())}');
  }
}

class HomePage extends StatefulWidget {
  HomePage({super.key});
  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  List<Map<String, dynamic>> chats = [];
  String? homeLoadError;
  bool loading = true;
  int selectedFilter = 0;
  int navIndex = 0;
  bool showContacts = false;
  String? selectedFolderId;
  List<Map<String, dynamic>> chatFolders = [];
  Map<String, Set<String>> folderAssignments = {};
  Set<String> archivedChatIds = <String>{};
  Set<String> manuallyUnreadChatIds = <String>{};
  Set<String> pinnedChatIds = <String>{};
  final TextEditingController chatSearch = TextEditingController();
  String chatQuery = '';
  Future<List<Map<String, dynamic>>>? _contactsFuture;
  RealtimeChannel? _homeChannel;
  Timer? _homeRefreshTimer;
  bool _homeLoadInProgress = false;
  bool _homeLoadQueued = false;
  RealtimeChannel? _callChannel;
  final Set<String> _handledIncomingCalls = <String>{};
  final Set<String> _shownMessageNotificationIds = <String>{};
  OverlayEntry? _messageNotificationEntry;
  Timer? _messageNotificationTimer;
  final AppLinks _appLinks = AppLinks();
  StreamSubscription<Uri>? _inviteLinkSubscription;
  final Map<String, DateTime> _recentInviteCodes = <String, DateTime>{};
  StreamSubscription<AuthState>? _homeAuthSubscription;
  String? _observedAuthUserId;
  DateTime? _lastBackPressedAt;

  List<Map<String, dynamic>> get visibleChats {
    final type = selectedFilter >= 1 && selectedFilter <= 3
        ? ['direct', 'group', 'channel'][selectedFilter - 1]
        : null;
    final unreadOnly = selectedFilter == 4;
    final folderId = selectedFolderId;
    final archivedOnly = selectedFilter == 5;
    final folderSet = folderId == null ? null : (folderAssignments[folderId] ?? <String>{});
    return chats.where((c) {
      final matchesType = type == null || c['type'].toString() == type;
      final matchesFolder = folderSet == null || folderSet.contains(c['id'].toString());
      final unreadCount = int.tryParse('${c['unread_count'] ?? c['unread'] ?? 0}') ?? 0;
      final isUnread = unreadCount > 0 || c['unread'] == true;
      final q = chatQuery.trim().toLowerCase();
      final peer = c['_peer'] as Map<String,dynamic>?;
      final title = (c['title'] ?? peer?['display_name'] ?? peer?['username'] ?? '').toString().toLowerCase();
      final last = (c['_preview'] ?? c['last_message'] ?? '').toString().toLowerCase();
      final username = (peer?['username'] ?? c['username'] ?? '').toString().toLowerCase();
      final isArchived = archivedChatIds.contains(c['id'].toString());
      return matchesType && matchesFolder && (archivedOnly ? isArchived : !isArchived) && (!unreadOnly || isUnread) &&
          (q.isEmpty || title.contains(q) || username.contains(q) || last.contains(q));
    }).toList()..sort((a,b) { final ap=pinnedChatIds.contains(a['id'].toString()); final bp=pinnedChatIds.contains(b['id'].toString()); if(ap!=bp) return ap?-1:1; final at=(a['_last']?['created_at']??'').toString(); final bt=(b['_last']?['created_at']??'').toString(); return bt.compareTo(at); });
  }

  String get _homeCacheKey {
    final uid = supabase.auth.currentUser?.id ?? 'guest';
    return 'arad_home_chats_cache_$uid';
  }

  Future<void> load() async {
    if (_homeLoadInProgress) {
      _homeLoadQueued = true;
      return;
    }
    _homeLoadInProgress = true;
    final uid = supabase.auth.currentUser?.id;
    if (mounted) {
      setState(() {
        if (chats.isEmpty) loading = true;
        homeLoadError = null;
      });
    }

    try {
      if (uid == null) {
        throw StateError('برای دیدن گفتگوها ابتدا وارد حساب شوید.');
      }

      // 1) Membership is the source of truth: never expose conversations
      // simply because the current user created them.
      // Restore the last known list first. A temporary RLS/network failure
      // must never make the user's chat history disappear from the UI.
      try {
        final prefs = await SharedPreferences.getInstance().timeout(const Duration(seconds: 3));
        final cached = prefs.getString('arad_home_chats_cache_$uid');
        if (chats.isEmpty && cached != null && cached.isNotEmpty) {
          final decoded = jsonDecode(cached);
          if (decoded is List) {
            final restored = decoded
                .whereType<Map>()
                .map((row) => Map<String, dynamic>.from(row))
                .toList();
            if (restored.isNotEmpty && mounted) {
              setState(() {
                chats = restored;
                loading = false;
              });
            }
          }
        }
      } catch (cacheError) {
        debugPrint('Cached chat restore failed: $cacheError');
      }

      final membershipResponse = await supabase
          .from('conversation_members')
          .select('conversation_id')
          .eq('user_id', uid)
          .timeout(const Duration(seconds: 10));
      final conversationIds = (membershipResponse as List)
          .map((row) => row['conversation_id']?.toString() ?? '')
          .where((id) => id.isNotEmpty && id != 'null')
          .toSet()
          .toList();

      if (conversationIds.isEmpty) {
        // An empty response can be caused by session/RLS timing. Keep any
        // restored history rather than deleting the user's local cache.
        if (mounted) {
          setState(() {
            loading = false;
            homeLoadError = chats.isEmpty
                ? null
                : 'گفتگوهای ذخیره‌شده نمایش داده می‌شوند؛ برای همگام‌سازی دوباره تلاش کنید.';
          });
        }
        await _loadChatListPreferences(uid);
        return;
      }

      // 2) Fetch only conversations referenced by the signed-in user's
      // memberships. This also makes RLS failures visible instead of masking
      // them with an RPC or creator-based fallback.
      final conversationResponse = await supabase
          .from('conversations')
          .select('id,type,title,username,avatar_url,description,is_public,created_at')
          .inFilter('id', conversationIds)
          .timeout(const Duration(seconds: 10));
      final conversationRows = List<Map<String, dynamic>>.from(conversationResponse);
      final conversationsById = <String, Map<String, dynamic>>{
        for (final row in conversationRows)
          if ((row['id']?.toString() ?? '').isNotEmpty) row['id'].toString(): row,
      };

      // If RLS hides a conversation the membership row must not create a
      // clickable phantom item.
      final visibleIds = conversationsById.keys.toList();
      if (visibleIds.isEmpty) {
        // The membership table may briefly be hidden while the session settles.
        // Do not replace a previously restored list with an empty screen.
        if (mounted) {
          setState(() {
            loading = false;
            homeLoadError = chats.isEmpty
                ? 'گفتگویی از سرور برنگشت. برای بررسی اتصال و دسترسی دوباره تلاش کنید.'
                : 'گفتگوهای ذخیره‌شده نمایش داده می‌شوند؛ همگام‌سازی سرور ناموفق بود.';
          });
        }
        await _loadChatListPreferences(uid);
        return;
      }

      // 3) Get recent messages in one bounded request, then keep the newest
      // non-deleted message per conversation. Missing previews are fetched
      // individually below so older but active conversations still show their
      // true latest message.
      final latestByConversation = <String, Map<String, dynamic>>{};
      // Preview queries are optional: if messages have an RLS/schema/network
      // issue, still show the conversations instead of failing the whole page.
      try {
        final messageResponse = await supabase
            .from('messages')
            .select('id,conversation_id,sender_id,body,message_type,created_at,read_at,deleted_at')
            .inFilter('conversation_id', visibleIds)
            .isFilter('deleted_at', null)
            .order('created_at', ascending: false)
            .limit(1000)
            .timeout(const Duration(seconds: 10));
        for (final row in List<Map<String, dynamic>>.from(messageResponse as List)) {
          final id = row['conversation_id']?.toString() ?? '';
          if (id.isNotEmpty) latestByConversation.putIfAbsent(id, () => row);
        }
      } catch (messageError) {
        debugPrint('Latest-message preview query failed; keeping chat list: $messageError');
      }

      // For chats without a preview, try one lightweight request per chat.
      // Failure to read a preview must not hide that chat from the list.
      final missingLatestIds = visibleIds.where((id) => !latestByConversation.containsKey(id)).toList();
      for (var offset = 0; offset < missingLatestIds.length; offset += 8) {
        final batch = missingLatestIds.skip(offset).take(8);
        final results = await Future.wait(batch.map((id) async {
          try {
            final rows = await supabase.from('messages')
                .select('id,conversation_id,sender_id,body,message_type,created_at,read_at,deleted_at')
                .eq('conversation_id', id)
                .isFilter('deleted_at', null)
                .order('created_at', ascending: false)
                .limit(1)
                .timeout(const Duration(seconds: 4));
            final list = List<Map<String, dynamic>>.from(rows as List);
            return list.isEmpty ? null : list.first;
          } catch (messageError) {
            debugPrint('Latest message lookup failed for $id: $messageError');
            return null;
          }
        }));
        for (final row in results) {
          if (row != null) latestByConversation[row['conversation_id'].toString()] = row;
        }
      }

      // 4) Peer names are optional too. If membership/profile hydration fails,
      // keep each chat visible using the conversation's own title as fallback.
      final peerByConversation = <String, String>{};
      try {
        final memberResponse = await supabase
            .from('conversation_members')
            .select('conversation_id,user_id')
            .inFilter('conversation_id', visibleIds)
            .timeout(const Duration(seconds: 8));
        for (final row in List<Map<String, dynamic>>.from(memberResponse as List)) {
          final conversationId = row['conversation_id']?.toString() ?? '';
          final memberId = row['user_id']?.toString() ?? '';
          if (conversationId.isNotEmpty && memberId.isNotEmpty && memberId != uid) {
            peerByConversation.putIfAbsent(conversationId, () => memberId);
          }
        }
      } catch (memberError) {
        debugPrint('Peer membership lookup failed; keeping chat list: $memberError');
      }
      final peerIds = peerByConversation.values.toSet().toList();
      final profilesById = <String, Map<String, dynamic>>{};
      if (peerIds.isNotEmpty) {
        try {
          final profileResponse = await supabase
              .from('profiles')
              .select('id,username,display_name,avatar_url,is_online')
              .inFilter('id', peerIds)
              .timeout(const Duration(seconds: 8));
          for (final row in List<Map<String, dynamic>>.from(profileResponse as List)) {
            profilesById[row['id'].toString()] = row;
          }
        } catch (profileError) {
          // The chat list itself should remain usable even if profile fields
          // are restricted by RLS.
          debugPrint('Chat list peer profiles unavailable: $profileError');
        }
      }

      final nextChats = <Map<String, dynamic>>[];
      for (final id in visibleIds) {
        final row = conversationsById[id]!;
        final type = (row['type'] ?? 'direct').toString();
        final peerId = peerByConversation[id];
        final peer = peerId == null ? null : profilesById[peerId];
        final last = latestByConversation[id];
        final fallbackTitle = type == 'group'
            ? 'گروه'
            : type == 'channel'
                ? 'کانال'
                : 'گفتگوی شخصی';
        final rawTitle = (type == 'direct'
                ? (peer?['display_name'] ?? peer?['username'] ?? row['title'] ?? fallbackTitle)
                : (row['title'] ?? row['username'] ?? fallbackTitle))
            .toString().trim();
        final preview = last == null
            ? 'هنوز پیامی ارسال نشده'
            : ((last['body'] ?? '').toString().trim().isNotEmpty
                ? last['body'].toString()
                : (last['message_type'] ?? 'پیام').toString());
        nextChats.add(<String, dynamic>{
          ...row,
          'id': id,
          'type': type,
          'title': rawTitle.isEmpty ? fallbackTitle : rawTitle,
          'avatar_url': row['avatar_url'] ?? peer?['avatar_url'],
          '_peer': peer ?? <String, dynamic>{},
          '_last': last,
          '_preview': preview,
          'unread_count': 0,
          'is_online': peer?['is_online'] == true,
        });
      }
      nextChats.sort((a, b) {
        final at = (a['_last']?['created_at'] ?? a['created_at'] ?? '').toString();
        final bt = (b['_last']?['created_at'] ?? b['created_at'] ?? '').toString();
        return bt.compareTo(at);
      });

      if (mounted) {
        setState(() {
          chats = nextChats;
          loading = false;
          homeLoadError = null;
        });
      }
      try {
        final prefs = await SharedPreferences.getInstance().timeout(const Duration(seconds: 2));
        await prefs.setString(_homeCacheKey, jsonEncode(nextChats)).timeout(const Duration(seconds: 2));
      } catch (cacheError) {
        debugPrint('Conversation cache save failed: $cacheError');
      }
      await _loadChatListPreferences(uid);
    } catch (error) {
      debugPrint('Chat list load failed: $error');
      if (mounted) {
        setState(() {
          loading = false;
          homeLoadError = _friendlyError(error.toString());
        });
      }
    } finally {
      _homeLoadInProgress = false;
      if (_homeLoadQueued && mounted) {
        _homeLoadQueued = false;
        unawaited(load());
      }
    }
  }

  Future<void> _loadChatListPreferences(String uid) async {
    try {
      final auxiliaryRows = await Future.wait<dynamic>([
        supabase.from('chat_unread_marks').select('conversation_id').eq('user_id', uid),
        supabase.from('chat_pins').select('conversation_id').eq('user_id', uid),
        supabase.from('chat_archives').select('conversation_id').eq('user_id', uid),
        supabase.from('chat_folders').select('id,name,icon_name,sort_order')
            .eq('user_id', uid).order('sort_order').order('created_at'),
      ]).timeout(const Duration(seconds: 5));
      final manualUnread = (auxiliaryRows[0] as List).map((r) => r['conversation_id'].toString()).toSet();
      final pinned = (auxiliaryRows[1] as List).map((r) => r['conversation_id'].toString()).toSet();
      final archived = (auxiliaryRows[2] as List).map((r) => r['conversation_id'].toString()).toSet();
      final folderRows = List<Map<String, dynamic>>.from(auxiliaryRows[3] as List);
      final assignmentMap = <String, Set<String>>{
        for (final folder in folderRows) folder['id'].toString(): <String>{},
      };
      if (folderRows.isNotEmpty) {
        final itemRows = List<Map<String, dynamic>>.from(
          await supabase.from('chat_folder_items').select('folder_id,conversation_id')
              .inFilter('folder_id', folderRows.map((f) => f['id']).toList())
              .timeout(const Duration(seconds: 4)),
        );
        for (final item in itemRows) {
          (assignmentMap[item['folder_id'].toString()] ??= <String>{})
              .add(item['conversation_id'].toString());
        }
      }
      if (mounted) {
        setState(() {
          chatFolders = folderRows;
          folderAssignments = assignmentMap;
          archivedChatIds = archived;
          manuallyUnreadChatIds = manualUnread;
          pinnedChatIds = pinned;
        });
      }
    } catch (error) {
      debugPrint('Optional chat settings unavailable: $error');
    }
  }

  Future<void> _toggleManualUnread(Map<String,dynamic> chat) async {
    final uid = supabase.auth.currentUser?.id;
    final id = chat['id']?.toString();
    if(uid == null || id == null || id.isEmpty) return;
    final marked = manuallyUnreadChatIds.contains(id);
    try {
      if(marked) {
        await supabase.from('chat_unread_marks').delete().eq('user_id', uid).eq('conversation_id', id);
      } else {
        await supabase.from('chat_unread_marks').insert({'user_id':uid,'conversation_id':id});
      }
      if(!mounted) return;
      setState(() { if(marked) manuallyUnreadChatIds.remove(id); else manuallyUnreadChatIds.add(id); });
      showMsg(context, marked ? 'گفتگو به‌عنوان خوانده‌شده علامت خورد.' : 'گفتگو به‌عنوان خوانده‌نشده علامت خورد.');
    } catch(e) { if(mounted) showMsg(context, 'تغییر وضعیت ناموفق بود: '+_friendlyError(e.toString())); }
  }

  Future<void> _togglePin(Map<String,dynamic> chat) async {
    final uid = supabase.auth.currentUser?.id;
    final id = chat['id']?.toString();
    if (uid == null || id == null || id.isEmpty) return;
    final pinned = pinnedChatIds.contains(id);
    try {
      if (pinned) {
        await supabase.from('chat_pins').delete()
            .eq('user_id', uid).eq('conversation_id', id);
      } else {
        await supabase.from('chat_pins').insert({
          'user_id': uid,
          'conversation_id': id,
        });
      }
      if (!mounted) return;
      setState(() {
        if (pinned) {
          pinnedChatIds.remove(id);
        } else {
          pinnedChatIds.add(id);
        }
      });
      showMsg(context, pinned ? 'سنجاق گفتگو برداشته شد.' : 'گفتگو سنجاق شد.');
    } catch (e) {
      if (mounted) showMsg(context, 'تغییر سنجاق گفتگو ناموفق بود: ${_friendlyError(e.toString())}');
    }
  }

  Future<void> _toggleArchive(Map<String,dynamic> chat) async {
    final uid = supabase.auth.currentUser?.id;
    final id = chat['id']?.toString();
    if(uid == null || id == null || id.isEmpty) return;
    final archived = archivedChatIds.contains(id);
    try {
      if(archived) {
        await supabase.from('chat_archives').delete().eq('user_id', uid).eq('conversation_id', id);
      } else {
        await supabase.from('chat_archives').insert({'user_id':uid,'conversation_id':id});
      }
      if(!mounted) return;
      setState(() {
        if(archived) { archivedChatIds.remove(id); } else { archivedChatIds.add(id); }
      });
      showMsg(context, archived ? 'گفتگو از آرشیو خارج شد.' : 'گفتگو به آرشیو منتقل شد.');
    } catch(e) {
      if(mounted) showMsg(context, 'تغییر وضعیت آرشیو ناموفق بود: '+_friendlyError(e.toString()));
    }
  }

  Future<void> createDirect() async {
    final result = await showSearch<Map<String, dynamic>?>(context: context, delegate: UserSearchDelegate());
    if (result == null) return;
    try {
      final uid = supabase.auth.currentUser!.id;
      if (result['id'].toString() == uid) { showMsg(context, 'نمی‌توانید با خودتان گفتگوی شخصی بسازید.'); return; }
      // Resolve an existing direct chat with bounded queries instead of one
      // network request per conversation. This matters for accounts with many chats.
      final existingRows = await supabase
          .from('conversation_members')
          .select('conversation_id')
          .eq('user_id', uid);
      final existingIds = (existingRows as List)
          .map((r) => '${r['conversation_id']}')
          .where((id) => id.isNotEmpty)
          .toSet()
          .toList();
      if (existingIds.isNotEmpty) {
        final directRows = await supabase
            .from('conversations')
            .select('id')
            .inFilter('id', existingIds)
            .eq('type', 'direct');
        final directIds = (directRows as List)
            .map((r) => '${r['id']}')
            .where((id) => id.isNotEmpty)
            .toSet()
            .toList();
        if (directIds.isNotEmpty) {
          final memberRows = await supabase
              .from('conversation_members')
              .select('conversation_id,user_id')
              .inFilter('conversation_id', directIds);
          final membersByConversation = <String, Set<String>>{};
          for (final member in memberRows as List) {
            final conversationId = '${member['conversation_id'] ?? ''}';
            final memberId = '${member['user_id'] ?? ''}';
            if (conversationId.isNotEmpty && memberId.isNotEmpty) {
              (membersByConversation[conversationId] ??= <String>{}).add(memberId);
            }
          }
          for (final conversationId in directIds) {
            final memberIds = membersByConversation[conversationId] ?? <String>{};
            if (memberIds.length == 2 && memberIds.contains('${result['id']}') && memberIds.contains(uid)) {
              if (mounted) {
                Navigator.push(context, MaterialPageRoute(
                  builder: (_) => ChatPage(
                    id: conversationId,
                    title: (result['display_name'] ?? result['username'] ?? 'گفتگو').toString(),
                  ),
                ));
              }
              return;
            }
          }
        }
      }
      final conversationId = await supabase.rpc(
        'create_direct_conversation',
        params: {'p_peer_id': result['id']},
      );
      if (mounted) Navigator.push(context, MaterialPageRoute(builder: (_) => ChatPage(id: conversationId.toString(), title: (result['display_name'] ?? result['username'] ?? 'گفتگو').toString())));
      load();
    } catch (e) { if (mounted) showMsg(context, 'ساخت گفتگو ناموفق بود: ' + e.toString()); }
  }

  Future<void> _initInviteLinks() async {
    try {
      final initial = await _appLinks.getInitialLink();
      if (initial != null) await _handleInviteUri(initial);
    } catch (_) {}
    _inviteLinkSubscription = _appLinks.uriLinkStream.listen(
      (uri) => _handleInviteUri(uri),
      onError: (_) {},
    );
  }

  Future<void> _handleInviteUri(Uri uri) async {
    if (uri.scheme.toLowerCase() != 'arad' || !mounted) return;
    if (uri.host.toLowerCase() == 'invite') {
      final code = (uri.queryParameters['code'] ?? '').trim();
      if (code.isEmpty) return;
      final key = code.toLowerCase();
      final now = DateTime.now();
      _recentInviteCodes.removeWhere((_, seenAt) => now.difference(seenAt) > Duration(minutes: 2));
      final previous = _recentInviteCodes[key];
      if (previous != null && now.difference(previous) < Duration(seconds: 3)) return;
      _recentInviteCodes[key] = now;
    }
    await openAradLink(context, uri);
  }

  String _extractInviteCode(String raw) {
    final input = raw.trim();
    if (input.isEmpty) return '';
    try {
      final uri = Uri.parse(input);
      final fromQuery = (uri.queryParameters['code'] ?? '').trim();
      if (fromQuery.isNotEmpty) return fromQuery;
    } catch (_) {}
    final match = RegExp(r'ARAD-[A-Za-z0-9]+', caseSensitive: false).firstMatch(input);
    return match?.group(0) ?? input;
  }

  Future<void> _joinGroupByInviteCode() async {
    final controller = TextEditingController();
    final code = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(trUi('پیوستن به گروه با لینک یا کد')),
        content: TextField(
          controller: controller,
          autofocus: true,
          textCapitalization: TextCapitalization.characters,
          decoration: InputDecoration(
            labelText: 'لینک کامل یا کد دعوت',
            hintText: 'لینک دعوت را بچسبانید یا ARAD-…',
            prefixIcon: Icon(Icons.link_rounded),
          ),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(dialogContext), child: Text(trUi('انصراف'))),
          FilledButton(onPressed: () => Navigator.pop(dialogContext, controller.text.trim()), child: Text(trUi('پیوستن'))),
        ],
      ),
    );
    controller.dispose();
    if (code == null || code.trim().isEmpty || !mounted) return;
    await _joinGroupByCode(_extractInviteCode(code));
  }

  Future<void> _joinGroupByCode(String rawCode) async {
    final code = _extractInviteCode(rawCode);
    if (code.isEmpty || !mounted) return;
    try {
      final result = await supabase.rpc('join_conversation_by_invite', params: {'p_code': code});
      final conversationId = result.toString();
      final conversation = Map<String, dynamic>.from(await supabase
          .from('conversations').select('id,type,title').eq('id', conversationId).single());
      final uid = supabase.auth.currentUser?.id;
      final membership = uid == null ? null : await supabase.from('conversation_members')
          .select('user_id').eq('conversation_id', conversationId).eq('user_id', uid).maybeSingle();
      if (membership == null) {
        if (mounted) showMsg(context, 'درخواست عضویت ثبت شد؛ پس از تأیید مدیر می‌توانید وارد شوید.');
        await load();
        return;
      }
      if (!mounted) return;
      await load();
      await Navigator.push(context, MaterialPageRoute(builder: (_) => ChatPage(
        id: conversationId,
        title: (conversation['title'] ?? (conversation['type'] == 'channel' ? 'کانال' : 'گروه')).toString(),
      )));
    } catch (e) {
      if (mounted) showMsg(context, 'پیوستن به گروه ناموفق بود: ${_friendlyError(e.toString())}');
    }
  }

  Future<void> createGroup() async {
    await Navigator.push(context, MaterialPageRoute(builder: (_) => GroupCreatePage()));
    load();
  }

  Future<void> _openFolderManager() async {
    await Navigator.push(context, MaterialPageRoute(builder: (_) => ChatFolderManagerPage()));
    if (mounted) {
      setState(() {
        selectedFolderId = null;
      });
    }
    await load();
  }

  void _scheduleHomeRefresh() {
    _homeRefreshTimer?.cancel();
    _homeRefreshTimer = Timer(Duration(milliseconds: 260), () {
      if (mounted) load();
    });
  }

  @override
  void initState() {
    super.initState();
    _observedAuthUserId = supabase.auth.currentUser?.id;
    load();
    // Auth restoration/refresh can finish after this page first builds. Reload
    // the private conversation list when Supabase supplies a valid session.
    _homeAuthSubscription = supabase.auth.onAuthStateChange.listen((state) {
      final nextUserId = state.session?.user.id;
      if (nextUserId == null) return;
      final sessionReady = state.event == AuthChangeEvent.initialSession ||
          state.event == AuthChangeEvent.signedIn ||
          state.event == AuthChangeEvent.tokenRefreshed ||
          nextUserId != _observedAuthUserId;
      if (sessionReady) {
        _observedAuthUserId = nextUserId;
        unawaited(load());
      }
    });
    unawaited(_initInviteLinks());
    _homeChannel = supabase.channel('home-' + (supabase.auth.currentUser?.id ?? 'guest'))
      .onPostgresChanges(
        event: PostgresChangeEvent.insert,
        schema: 'public',
        table: 'messages',
        callback: (payload) {
          _scheduleHomeRefresh();
          unawaited(_handleIncomingMessage(payload.newRecord));
        },
      )
      .onPostgresChanges(event: PostgresChangeEvent.update, schema: 'public', table: 'messages', callback: (_) => _scheduleHomeRefresh())
      .onPostgresChanges(event: PostgresChangeEvent.insert, schema: 'public', table: 'conversation_members', callback: (_) => _scheduleHomeRefresh())
      .onPostgresChanges(event: PostgresChangeEvent.delete, schema: 'public', table: 'conversation_members', callback: (_) => _scheduleHomeRefresh())
      .onPostgresChanges(event: PostgresChangeEvent.update, schema: 'public', table: 'conversations', callback: (_) => _scheduleHomeRefresh())
      .subscribe();
    _callChannel = supabase.channel('incoming-calls-' + (supabase.auth.currentUser?.id ?? 'guest'))
      .onPostgresChanges(
        event: PostgresChangeEvent.update,
        schema: 'public',
        table: 'profiles',
        callback: (_) => _scheduleHomeRefresh(),
      )
      .onPostgresChanges(
        event: PostgresChangeEvent.insert,
        schema: 'public',
        table: 'call_sessions',
        callback: (payload) => _handleIncomingCall(payload.newRecord),
      )
      .subscribe();
  }

  void _dismissFloatingMessageNotification() {
    _messageNotificationTimer?.cancel();
    _messageNotificationTimer = null;
    _messageNotificationEntry?.remove();
    _messageNotificationEntry = null;
  }

  void _showFloatingMessageNotification({
    required String title,
    required String preview,
    required VoidCallback onOpen,
  }) {
    if (!mounted) return;
    _dismissFloatingMessageNotification();
    final overlay = Overlay.of(context, rootOverlay: true);
    late final OverlayEntry entry;
    entry = OverlayEntry(builder: (overlayContext) {
      final scheme = Theme.of(overlayContext).colorScheme;
      return Positioned(
        top: 8,
        left: 12,
        right: 12,
        child: SafeArea(
          bottom: false,
          child: TweenAnimationBuilder<double>(
            tween: Tween(begin: 0, end: 1),
            duration: Duration(milliseconds: 420),
            curve: Curves.easeOutCubic,
            child: Material(
              color: Colors.transparent,
              child: Container(
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: [
                      scheme.surface.withValues(alpha: .90),
                      Color.alphaBlend(scheme.primary.withValues(alpha: .13), scheme.surface.withValues(alpha: .94)),
                    ],
                  ),
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: scheme.primary.withValues(alpha: .30)),
                  boxShadow: [
                    BoxShadow(color: Colors.black.withValues(alpha: .12), blurRadius: 28, offset: Offset(0, 10)),
                    BoxShadow(color: scheme.primary.withValues(alpha: .14), blurRadius: 24, spreadRadius: -3),
                  ],
                ),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(20),
                  child: BackdropFilter(
                    filter: ImageFilter.blur(sigmaX: 12, sigmaY: 12),
                    child: InkWell(
                      onTap: () {
                        _dismissFloatingMessageNotification();
                        onOpen();
                      },
                      child: Padding(
                        padding: const EdgeInsets.fromLTRB(12, 10, 8, 10),
                        child: Row(children: [
                          Container(
                            width: 42, height: 42,
                            decoration: BoxDecoration(
                              gradient: LinearGradient(colors: [scheme.primary, Color.lerp(scheme.primary, Color(0xFF45B8FF), .45)!]),
                              borderRadius: BorderRadius.circular(14),
                            ),
                            child: Icon(Icons.notifications_active_rounded, color: scheme.onPrimary, size: 22),
                          ),
                          SizedBox(width: 11),
                          Expanded(child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text(title, maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(fontWeight: FontWeight.w900, fontSize: 13)),
                              SizedBox(height: 3),
                              Text(preview, maxLines: 2, overflow: TextOverflow.ellipsis, style: TextStyle(fontSize: 12, color: scheme.onSurfaceVariant)),
                            ],
                          )),
                          IconButton(
                            tooltip: 'بستن اعلان',
                            visualDensity: VisualDensity.compact,
                            onPressed: _dismissFloatingMessageNotification,
                            icon: Icon(Icons.close_rounded, size: 19, color: scheme.onSurfaceVariant),
                          ),
                        ]),
                      ),
                    ),
                  ),
                ),
              ),
            ),
            builder: (context, progress, child) => Opacity(
              opacity: Curves.easeOut.transform(progress),
              child: Transform.translate(
                offset: Offset(0, (1 - Curves.easeOutCubic.transform(progress)) * -76),
                child: child,
              ),
            ),
          ),
        ),
      );
    });
    _messageNotificationEntry = entry;
    overlay.insert(entry);
    _messageNotificationTimer = Timer(Duration(seconds: 5), _dismissFloatingMessageNotification);
  }

  Future<void> _handleIncomingMessage(Map<String, dynamic> row) async {
    final uid = supabase.auth.currentUser?.id;
    final senderId = row['sender_id']?.toString() ?? '';
    final conversationId = row['conversation_id']?.toString() ?? '';
    final messageId = row['id']?.toString() ?? '';
    if (!mounted || uid == null || senderId.isEmpty || senderId == uid ||
        conversationId.isEmpty || messageId.isEmpty) return;
    // A route-level check hid all notifications while any chat was open.
    if ((_openChatConversationCounts[conversationId] ?? 0) > 0) return;
    if (!_shownMessageNotificationIds.add(messageId)) return;
    if (_shownMessageNotificationIds.length > 100) {
      _shownMessageNotificationIds.remove(_shownMessageNotificationIds.first);
    }

    try {
      final prefs = await SharedPreferences.getInstance();
      if (prefs.getBool('chat_notifications_muted_${uid}_${conversationId}') == true) return;
    } catch (_) {}

    String title = 'پیام جدید';
    for (final chat in chats) {
      if (chat['id']?.toString() != conversationId) continue;
      final peer = chat['_peer'] is Map ? Map<String, dynamic>.from(chat['_peer'] as Map) : <String, dynamic>{};
      title = (chat['title'] ?? peer['display_name'] ?? peer['username'] ?? 'گفتگوی جدید').toString();
      break;
    }
    if (title == 'پیام جدید' || title.trim().isEmpty) {
      try {
        final details = await Future.wait<dynamic>([
          supabase.from('conversations').select('type,title').eq('id', conversationId).maybeSingle(),
          supabase.from('profiles').select('display_name,username').eq('id', senderId).maybeSingle(),
        ]);
        final conversation = details[0] is Map ? Map<String, dynamic>.from(details[0] as Map) : <String, dynamic>{};
        final sender = details[1] is Map ? Map<String, dynamic>.from(details[1] as Map) : <String, dynamic>{};
        title = (conversation['title'] ?? sender['display_name'] ?? sender['username'] ?? 'پیام جدید').toString();
      } catch (_) {}
    }

    final type = (row['message_type'] ?? 'text').toString().toLowerCase();
    final body = (row['body'] ?? '').toString().trim();
    final preview = switch (type) {
      'image' => '📷 عکس جدید',
      'video' => '🎬 ویدئوی جدید',
      'audio' || 'voice' => '🎙 پیام صوتی جدید',
      'file' => '📎 فایل جدید',
      _ => body.isEmpty ? 'پیام جدید دریافت شد' : body,
    };
    if (!mounted || (_openChatConversationCounts[conversationId] ?? 0) > 0) return;
    _showFloatingMessageNotification(
      title: title,
      preview: preview,
      onOpen: () {
        if (!mounted) return;
        Navigator.push(context, MaterialPageRoute(builder: (_) => ChatPage(id: conversationId, title: title)));
      },
    );
  }

  Future<void> _handleIncomingCall(Map<String, dynamic> row) async {
    final uid = supabase.auth.currentUser?.id;
    final callId = row['id']?.toString();
    if (uid == null || callId == null || callId.isEmpty) return;
    if (row['callee_id']?.toString() != uid || row['status']?.toString() != 'ringing') return;
    if (_handledIncomingCalls.contains(callId)) return;
    _handledIncomingCalls.add(callId);

    String title = 'تماس ورودی';
    try {
      final c = await supabase.from('conversations').select('type,title').eq('id', row['conversation_id']).maybeSingle();
      if (c != null && (c['title'] ?? '').toString().trim().isNotEmpty) {
        title = c['title'].toString();
      } else {
        final callerId = row['caller_id']?.toString();
        if (callerId != null) {
          final p = await supabase.from('profiles').select('display_name,username').eq('id', callerId).maybeSingle();
          title = (p?['display_name'] ?? p?['username'] ?? title).toString();
        }
      }
    } catch (_) {}

    if (!mounted) return;
    await showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => AlertDialog(
        title: Text(row['call_type']?.toString() == 'video' ? 'تماس تصویری ورودی' : 'تماس صوتی ورودی'),
        content: Text(trUi('$title با شما تماس می‌گیرد.')),
        actions: [
          TextButton(
            onPressed: () async {
              try {
                await supabase.from('call_sessions').update({
                  'status': 'rejected',
                  'ended_at': DateTime.now().toUtc().toIso8601String(),
                }).eq('id', callId);
              } catch (_) {}
              if (dialogContext.mounted) Navigator.pop(dialogContext);
            },
            child: Text(trUi('رد')),
          ),
          FilledButton.icon(
            onPressed: () {
              Navigator.pop(dialogContext);
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => CallSessionPage(
                    conversationId: row['conversation_id'].toString(),
                    title: title,
                    video: row['call_type']?.toString() == 'video',
                    existingCallId: callId,
                    incoming: true,
                  ),
                ),
              );
            },
            icon: Icon(Icons.call_rounded),
            label: Text(trUi('پاسخ')),
          ),
        ],
      ),
    );
  }

  @override
  void dispose() {
    _homeAuthSubscription?.cancel();
    _homeRefreshTimer?.cancel();
    _messageNotificationTimer?.cancel();
    _messageNotificationEntry?.remove();
    _messageNotificationEntry = null;
    _inviteLinkSubscription?.cancel();
    if (_homeChannel != null) supabase.removeChannel(_homeChannel!);
    if (_callChannel != null) supabase.removeChannel(_callChannel!);
    chatSearch.dispose();
    super.dispose();
  }

  Widget chatsView() {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final dark = theme.brightness == Brightness.dark;
    final glass = scheme.surface.withValues(alpha: dark ? .96 : .98);
    final filteredChats = visibleChats;
    final unreadTotal = chats.fold<int>(
      0,
      (total, chat) => total + (int.tryParse('${chat['unread_count'] ?? 0}') ?? 0),
    );

    Widget actionButton({required IconData icon, required VoidCallback onTap, String? tooltip}) => Tooltip(
      message: tooltip ?? '',
      child: Material(
        color: scheme.surfaceContainerHighest.withValues(alpha: dark ? .72 : .92),
        shape: CircleBorder(),
        child: InkWell(
          onTap: onTap,
          customBorder: CircleBorder(),
          child: SizedBox(width: 42, height: 42, child: Icon(icon, size: 21, color: scheme.onSurface)),
        ),
      ),
    );

    Widget filterChip({required String label, required IconData icon, required bool selected, required VoidCallback onTap}) => Padding(
      padding: const EdgeInsets.only(left: 7),
      child: Material(
        color: selected ? scheme.primary : scheme.surfaceContainerHighest.withValues(alpha: dark ? .62 : .86),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(14),
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Icon(icon, size: 16, color: selected ? scheme.onPrimary : scheme.onSurfaceVariant),
              SizedBox(width: 6),
