                      Text(chatQuery.trim().isNotEmpty ? trUi('نام یا عبارت دیگری را جستجو کنید.') : trUi('یک گفتگوی جدید شروع کنید یا از مخاطبین انتخاب کنید.'), textAlign: TextAlign.center, style: TextStyle(color: scheme.onSurfaceVariant, height: 1.45)),
                      if (chatQuery.trim().isEmpty) ...[
                        SizedBox(height: 17),
                        FilledButton.icon(onPressed: createDirect, icon: Icon(Icons.add_comment_rounded), label: Text(trUi('گفتگوی جدید'))),
                      ],
                    ]),
                  ))
                : ListView.separated(
                    padding: const EdgeInsets.fromLTRB(11, 5, 11, 96),
                    itemCount: filteredChats.length,
                    separatorBuilder: (_, __) => SizedBox(height: 7),
                    itemBuilder: (context, i) {
                      final c = filteredChats[i];
                      final id = c['id'].toString();
                      final type = c['type'].toString();
                      final peer = c['_peer'] as Map<String,dynamic>?;
                      final title = (type == 'direct' ? (peer?['display_name'] ?? peer?['username'] ?? c['title'] ?? 'گفتگوی شخصی') : (c['title'] ?? (type == 'group' ? 'گروه' : 'کانال'))).toString();
                      final avatarUrl = (type == 'direct' ? (peer?['avatar_url'] ?? '') : (c['avatar_url'] ?? '')).toString();
                      final icon = type == 'group' ? Icons.groups_rounded : type == 'channel' ? Icons.campaign_rounded : Icons.person_rounded;
                      final last = c['_last'] as Map<String,dynamic>?;
                      final preview = (c['_preview'] ?? 'شروع گفتگو').toString();
                      final lastAt = last?['created_at'];
                      final unreadCount = int.tryParse(c['unread_count']?.toString() ?? '0') ?? 0;
                      final unread = unreadCount > 0 || manuallyUnreadChatIds.contains(id);
                      final isPinned = pinnedChatIds.contains(id);
                      final archived = archivedChatIds.contains(id);

                      return Material(
                        color: unread
                            ? Color.alphaBlend(scheme.primary.withValues(alpha: dark ? .13 : .07), scheme.surface)
                            : (isPinned
                                ? Color.alphaBlend(scheme.primary.withValues(alpha: dark ? .09 : .045), scheme.surface)
                                : scheme.surface),
                        elevation: 0,
                        shadowColor: Colors.transparent,
                        surfaceTintColor: Colors.transparent,
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(18),
                          side: BorderSide(
                            color: unread || isPinned
                                ? scheme.primary.withValues(alpha: dark ? .65 : .42)
                                : scheme.outlineVariant.withValues(alpha: dark ? .42 : .58),
                            width: unread ? 1.35 : (isPinned ? 1.1 : .8),
                          ),
                        ),
                        clipBehavior: Clip.antiAlias,
                        child: InkWell(
                          onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ChatPage(id: id, title: title))).then((_) => load()),
                          child: Padding(
                            padding: const EdgeInsets.fromLTRB(10, 7, 5, 7),
                            child: Row(children: [
                              Stack(clipBehavior: Clip.none, children: [
                                Container(
                                  padding: const EdgeInsets.all(2),
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    border: Border.all(
                                      color: unread || isPinned ? scheme.primary : scheme.outlineVariant,
                                      width: unread || isPinned ? 2 : 1,
                                    ),
                                  ),
                                  child: type == 'direct'
                                      ? avatar(peer ?? <String, dynamic>{}, size: 50)
                                      : ClipOval(
                                          child: SizedBox(
                                            width: 50,
                                            height: 50,
                                            child: avatarUrl.isEmpty
                                                ? CircleAvatar(
                                                    radius: 25,
                                                    backgroundColor: scheme.primaryContainer,
                                                    child: Icon(icon, color: scheme.primary, size: 25),
                                                  )
                                                : Image.network(
                                                    avatarUrl,
                                                    fit: BoxFit.cover,
                                                    gaplessPlayback: true,
                                                    errorBuilder: (context, error, stackTrace) => Container(
                                                      color: scheme.primaryContainer,
                                                      alignment: Alignment.center,
                                                      child: Icon(icon, color: scheme.primary, size: 25),
                                                    ),
                                                    loadingBuilder: (context, child, progress) => progress == null
                                                        ? child
                                                        : Container(
                                                            color: scheme.primaryContainer,
                                                            alignment: Alignment.center,
                                                            child: SizedBox(
                                                              width: 16,
                                                              height: 16,
                                                              child: CircularProgressIndicator(strokeWidth: 1.6, color: scheme.primary),
                                                            ),
                                                          ),
                                                  ),
                                          ),
                                        ),
                                ),
                                if (c['is_online'] == true)
                                  Positioned(right: -1, bottom: -1, child: Container(width: 13, height: 13, decoration: BoxDecoration(color: Color(0xFF22C55E), shape: BoxShape.circle, border: Border.all(color: scheme.surface, width: 2.3)))),
                              ]),
                              SizedBox(width: 10),
                              Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                Row(children: [
                                  Expanded(child: Row(children: [
                                    Flexible(child: Text(title, maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(fontWeight: unread ? FontWeight.w900 : FontWeight.w800, fontSize: 15.5, color: unread ? scheme.primary : scheme.onSurface))),
                                    if (type == 'direct' && peer?['is_verified'] == true) Padding(padding: EdgeInsets.only(right: 4), child: AnimatedVerifiedBadge(size: 16)),
                                  ])),
                                  if (lastAt != null) Text(_homeTime(lastAt), style: TextStyle(fontSize: 10.5, color: unread ? scheme.primary : scheme.onSurfaceVariant, fontWeight: unread ? FontWeight.w800 : FontWeight.w500)),
                                ]),
                                SizedBox(height: 4),
                                Row(children: [
                                  if (isPinned) ...[Icon(Icons.push_pin_rounded, size: 14, color: scheme.primary), SizedBox(width: 4)],
                                  if (archived) ...[Icon(Icons.archive_rounded, size: 13, color: scheme.onSurfaceVariant), SizedBox(width: 4)],
                                  Expanded(child: Text(preview, maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(color: unread ? scheme.onSurface : scheme.onSurfaceVariant, fontWeight: unread ? FontWeight.w700 : FontWeight.w400, fontSize: 12))),
                                  if (unread) Container(constraints: BoxConstraints(minWidth: 21), padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3), decoration: BoxDecoration(color: scheme.primary, borderRadius: BorderRadius.circular(10)), child: Text(unreadCount > 0 ? unreadCount.toString() : '•', textAlign: TextAlign.center, style: TextStyle(color: scheme.onPrimary, fontSize: 10, fontWeight: FontWeight.w900))),
                                ]),
                              ])),
                              SizedBox(width: 4),
                              PopupMenuButton<String>(
                                tooltip: 'گزینه‌های گفتگو',
                                icon: Icon(Icons.more_horiz_rounded, size: 21),
                                onSelected: (action) {
                                  if (action == 'open') Navigator.push(context, MaterialPageRoute(builder: (_) => ChatPage(id: id, title: title))).then((_) => load());
                                  if (action == 'info') Navigator.push(context, MaterialPageRoute(builder: (_) => ConversationInfoPage(conversationId: id, fallbackTitle: title)));
                                  if (action == 'archive') _toggleArchive(c);
                                  if (action == 'unread') _toggleManualUnread(c);
                                  if (action == 'pin') _togglePin(c);
                                },
                                itemBuilder: (_) => [
                                  PopupMenuItem(value: 'open', child: Text(trUi('باز کردن گفتگو'))),
                                  PopupMenuItem(value: 'info', child: Text(trUi('پروفایل و اطلاعات'))),
                                  PopupMenuItem(value: 'unread', child: Text(manuallyUnreadChatIds.contains(id) ? 'علامت خوانده‌شده' : 'علامت خوانده‌نشده')),
                                  PopupMenuItem(value: 'pin', child: Text(isPinned ? 'برداشتن سنجاق' : 'سنجاق کردن گفتگو')),
                                  PopupMenuItem(value: 'archive', child: Text(archived ? 'خارج کردن از آرشیو' : 'آرشیو گفتگو')),
                                ],
                              ),
                            ]),
                          ),
                        ),
                      );
                    },
                  ),
      ),
    ]);
  }

  Future<void> _retryContacts() async {
    if (!mounted) return;
    setState(() => _contactsFuture = null);
    await Future<void>.delayed(Duration.zero);
    if (mounted) setState(() {});
  }

  Future<void> _openContactSearch() async {
    await showSearch(context: context, delegate: ContactSearchDelegate());
    if (mounted) setState(() => _contactsFuture = null);
  }

