  Future<List<Map<String,dynamic>>> _loadContacts() async {
    final uid = supabase.auth.currentUser?.id;
    if (uid == null) return [];
    SharedPreferences prefs;
    try {
      prefs = await SharedPreferences.getInstance().timeout(Duration(seconds: 2));
    } catch (error) {
      debugPrint('Contacts local cache unavailable: $error');
      try {
        return await _refreshContactsWithoutCache(uid).timeout(
          Duration(seconds: 8),
          onTimeout: () => <Map<String, dynamic>>[],
        );
      } catch (_) {
        return <Map<String, dynamic>>[];
      }
    }
    final cacheKey = 'arad_contacts_cache_$uid';

    // Show previously loaded contacts immediately, even with no connection.
    // Refresh is deliberately non-blocking; cached cards stay visible on error.
    List<Map<String, dynamic>> cachedContacts = <Map<String, dynamic>>[];
    try {
      final raw = prefs.getString(cacheKey);
      if (raw != null && raw.isNotEmpty) {
        cachedContacts = (jsonDecode(raw) as List)
            .map((item) => Map<String, dynamic>.from(item as Map))
            .toList();
      }
    } catch (error) {
      debugPrint('Cached contacts could not be decoded: $error');
    }
    if (cachedContacts.isNotEmpty) {
      unawaited(_refreshContactsCache(uid, cacheKey, prefs));
      return cachedContacts;
    }
    return _refreshContactsCache(uid, cacheKey, prefs);
  }

  Future<List<Map<String, dynamic>>> _refreshContactsWithoutCache(String uid) async {
    final rows = await supabase.from('contacts').select('contact_id')
        .eq('user_id', uid).timeout(Duration(seconds: 4));
    final ids = (rows as List).map((x) => x['contact_id']).where((x) => x != null).toList();
    if (ids.isEmpty) return <Map<String, dynamic>>[];
    final profiles = List<Map<String, dynamic>>.from(
      await supabase.from('profiles').select('id,display_name,username,avatar_url')
          .inFilter('id', ids).timeout(Duration(seconds: 4)),
    );
    for (final p in profiles) {
      p['_local_name'] = '';
      p['_conversation_id'] = '';
    }
    return profiles;
  }

  Future<List<Map<String, dynamic>>> _refreshContactsCache(
    String uid, String cacheKey, SharedPreferences prefs,
  ) async {
    try {
      final rows = await supabase.from('contacts').select('contact_id')
          .eq('user_id', uid).timeout(Duration(seconds: 5));
      final ids = (rows as List).map((x) => x['contact_id']).toList();
      if (ids.isEmpty) {
        await prefs.setString(cacheKey, '[]');
        return <Map<String, dynamic>>[];
      }
      final profiles = List<Map<String, dynamic>>.from(
        await supabase.from('profiles')
          .select('id,display_name,username,avatar_url')
          .inFilter('id', ids).timeout(Duration(seconds: 5)),
      );
      for (final p in profiles) {
        p['_local_name'] = prefs.getString('contact_alias_${uid}_${p['id']}') ?? '';
      }
      // Contact cards must not depend on the conversation-members table.
      // If that optional lookup fails due to schema/RLS, contacts still appear.
      try {
        final memberRows = await supabase.from('conversation_members')
            .select('conversation_id,user_id')
            .inFilter('user_id', [uid, ...ids])
            .timeout(Duration(seconds: 3));
        final grouped = <String, List<String>>{};
        for (final row in List<Map<String, dynamic>>.from(memberRows)) {
          grouped.putIfAbsent('${row['conversation_id']}', () => <String>[])
              .add('${row['user_id']}');
        }
        final peerIds = ids.map((id) => id.toString()).toSet();
        for (final entry in grouped.entries) {
          if (entry.value.length != 2 || !entry.value.contains(uid)) continue;
          final peer = entry.value.firstWhere((id) => id != uid, orElse: () => '');
          if (peerIds.contains(peer)) {
            final profile = profiles.where((p) => '${p['id']}' == peer);
            if (profile.isNotEmpty) profile.first['_conversation_id'] = entry.key;
          }
        }
      } catch (error) {
        debugPrint('Contact conversation enrichment skipped: $error');
      }
      final result = profiles.map((p) => <String, dynamic>{
        ...p,
        '_conversation_id': p['_conversation_id'] ?? '',
      }).toList();
      await prefs.setString(cacheKey, jsonEncode(result));
      return result;
    } catch (error) {
      debugPrint('Contacts refresh failed; using cached contacts: $error');
      final raw = prefs.getString(cacheKey);
      if (raw != null && raw.isNotEmpty) {
        return (jsonDecode(raw) as List)
            .map((item) => Map<String, dynamic>.from(item as Map))
            .toList();
      }
      return <Map<String, dynamic>>[];
    }
  }

  Widget _glassAction(IconData icon, String label, VoidCallback onTap) {
    final s = Theme.of(context).colorScheme;
    return ClipRRect(borderRadius: BorderRadius.circular(kAppRadius), child: BackdropFilter(
      filter: ImageFilter.blur(sigmaX: 7, sigmaY: 7),
      child: Material(color: s.surface.withValues(alpha: .70), child: InkWell(
        onTap: onTap, borderRadius: BorderRadius.circular(kAppRadius),
        child: Padding(padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 10),
          child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
            Icon(icon, color: s.primary), SizedBox(width: 7),
            Flexible(child: Text(trUi(label), overflow: TextOverflow.ellipsis, style: TextStyle(fontWeight: FontWeight.w800))),
          ]),
        ),
      )),
    ));
  }


  @override
  Widget build(BuildContext context) {
    return PopScope(
      // Keep the app open on the first system-back press, like common messengers.
      canPop: false,
      onPopInvokedWithResult: (didPop, result) {
        if (didPop || !mounted) return;
        final now = DateTime.now();
        final previous = _lastBackPressedAt;
        if (previous != null && now.difference(previous) <= const Duration(seconds: 2)) {
          SystemNavigator.pop();
          return;
        }
        _lastBackPressedAt = now;
        ScaffoldMessenger.of(context)
          ..hideCurrentSnackBar()
          ..showSnackBar(
            const SnackBar(
              content: Text('برای خروج، دوباره دکمهٔ برگشت را بزنید'),
              duration: Duration(seconds: 2),
              behavior: SnackBarBehavior.floating,
            ),
          );
      },
      child: Scaffold(
      body: SafeArea(child: AnimatedSwitcher(duration: Duration(milliseconds: 180), child: KeyedSubtree(
        key: ValueKey('$navIndex-$showContacts'),
        child: showContacts
            ? Column(children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(8, 4, 12, 4),
                  child: Row(children: [
                    IconButton(onPressed: () => setState(() => showContacts = false), icon: Icon(Icons.arrow_back_rounded)),
                    Expanded(child: Text(trUi('مخاطبین'), style: TextStyle(fontSize: 22, fontWeight: FontWeight.w900))),
                  ]),
                ),
                Expanded(child: contactsView()),
              ])
            : navIndex == 0
                ? chatsView()
                : ProfilePage(onOpenContacts: () => setState(() { showContacts = true; _contactsFuture = null; })),
      ))),
      floatingActionButton: navIndex == 0 ? FloatingActionButton(onPressed: createDirect, child: Icon(Icons.chat_rounded)) : null,
      bottomNavigationBar: ClipRRect(
        borderRadius: const BorderRadius.vertical(top: Radius.circular(16)),
        child: BackdropFilter(
          filter: ImageFilter.blur(sigmaX: 5, sigmaY: 5),
          child: NavigationBar(
            backgroundColor: Colors.transparent,
            elevation: 0,
            selectedIndex: navIndex,
            onDestinationSelected: (i) {
              HapticFeedback.selectionClick();
              if (i == navIndex) {
                if (i == 1) {
                  setState(() => showContacts = false);
                }
                if (i == 0) {
                  setState(() { selectedFolderId = null; selectedFilter = 0; chatQuery = ''; chatSearch.clear(); });
                  unawaited(load());
                }
                return;
              }
              setState(() { navIndex = i; showContacts = false; });
            },
            destinations: [
              NavigationDestination(icon: Icon(Icons.forum_outlined), selectedIcon: Icon(Icons.forum_rounded), label: trUi('گفتگوها')),
              NavigationDestination(icon: Icon(Icons.person_outline_rounded), selectedIcon: Icon(Icons.person_rounded), label: trUi('پروفایل')), 
            ],
          ),
        ),
      ),
      ),
    );
  }
}



Future<String?> _ensureDirectConversationForUser(Map<String, dynamic> profile) async {
  final uid = supabase.auth.currentUser?.id;
  final targetId = profile['id']?.toString();
  if (uid == null || targetId == null || targetId.isEmpty || targetId == uid) return null;
  final existing = await supabase.from('conversation_members').select('conversation_id').eq('user_id', uid);
  for (final row in (existing as List)) {
    final conversationId = row['conversation_id']?.toString();
    if (conversationId == null) continue;
    final members = await supabase.from('conversation_members').select('user_id').eq('conversation_id', conversationId);
    if ((members as List).length == 2 && members.any((m) => m['user_id']?.toString() == targetId)) return conversationId;
  }
  final conversationId = await supabase.rpc(
    'create_direct_conversation',
    params: {'p_peer_id': targetId},
  );
  return conversationId?.toString();
}

class PublicUserProfilePage extends StatefulWidget {
  final Map<String, dynamic> profile;
  PublicUserProfilePage({super.key, required this.profile});
  @override State<PublicUserProfilePage> createState() => _PublicUserProfilePageState();
}

class _PublicUserProfilePageState extends State<PublicUserProfilePage> {
  double _profilePullOffset = 0;
  bool busy = false;
  bool isContact = false;
  bool isFriend = false;
  bool friendRequestPending = false;
  String localName = '';
  Map<String, dynamic> get profile => widget.profile;
  String get displayName => localName.trim().isNotEmpty
      ? localName.trim()
      : '${profile['display_name'] ?? profile['username'] ?? 'کاربر'}'.trim();
  String get username => '${profile['username'] ?? ''}'.trim();

  @override
  void initState() {
    super.initState();
    _loadLocalContactSettings();
  }

  Future<void> _loadLocalContactSettings() async {
    final uid = supabase.auth.currentUser?.id;
    final targetId = profile['id']?.toString();
    if (uid == null || targetId == null || targetId == uid) return;
    try {
      final prefs = await SharedPreferences.getInstance();
      final alias = prefs.getString('contact_alias_${uid}_${targetId}') ?? '';
      final row = await supabase.from('contacts').select('id')
          .eq('user_id', uid).eq('contact_id', targetId).maybeSingle();
      dynamic sentRequest;
      dynamic receivedRequest;
      try {
        sentRequest = await supabase.from('friend_requests').select('id,status')
            .eq('requester_id', uid).eq('recipient_id', targetId).maybeSingle();
        receivedRequest = await supabase.from('friend_requests').select('id,status')
            .eq('requester_id', targetId).eq('recipient_id', uid).maybeSingle();
      } catch (_) {}
      final accepted = sentRequest?['status'] == 'accepted' || receivedRequest?['status'] == 'accepted';
      final pending = sentRequest?['status'] == 'pending' || receivedRequest?['status'] == 'pending';
      if (mounted) setState(() {
        localName = alias;
        isContact = row != null;
        isFriend = accepted;
        friendRequestPending = !accepted && pending;
      });
    } catch (_) {}
  }

  Future<void> _editLocalName() async {
    final controller = TextEditingController(text: localName);
    final value = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(trUi('نام اختصاصی مخاطب')),
        content: TextField(
          controller: controller,
          autofocus: true,
          maxLength: 48,
          decoration: InputDecoration(hintText: 'فقط برای شما نمایش داده می‌شود'),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: Text(trUi('انصراف'))),
          FilledButton(onPressed: () => Navigator.pop(ctx, controller.text.trim()), child: Text(trUi('ذخیره'))),
        ],
      ),
    );
    controller.dispose();
    if (value == null) return;
    final uid = supabase.auth.currentUser?.id;
    final targetId = profile['id']?.toString();
    if (uid == null || targetId == null) return;
    final prefs = await SharedPreferences.getInstance();
    final key = 'contact_alias_${uid}_${targetId}';
    if (value.isEmpty) {
      await prefs.remove(key);
    } else {
      await prefs.setString(key, value);
    }
    if (mounted) setState(() => localName = value);
    if (mounted) showMsg(context, value.isEmpty ? 'نام اختصاصی پاک شد.' : 'نام اختصاصی ذخیره شد.');
  }

  Future<void> _toggleContact() async {
    final uid = supabase.auth.currentUser?.id;
    final targetId = profile['id']?.toString();
    if (uid == null || targetId == null || uid == targetId) return;
    try {
      if (isContact) {
        await supabase.from('contacts').delete().eq('user_id', uid).eq('contact_id', targetId);
        if (mounted) setState(() => isContact = false);
        if (mounted) showMsg(context, 'مخاطب از فهرست شما حذف شد.');
      } else {
        await supabase.from('contacts').upsert(
          {'user_id': uid, 'contact_id': targetId},
          onConflict: 'user_id,contact_id',
        );
        if (mounted) setState(() => isContact = true);
        if (mounted) showMsg(context, 'به مخاطبین شما اضافه شد.');
      }
    } catch (e) {
      if (mounted) showMsg(context, 'تغییر مخاطب ناموفق بود: ${_friendlyError(e.toString())}');
    }
  }

  Future<void> _sendFriendRequest() async {
    final uid = supabase.auth.currentUser?.id;
    final targetId = profile['id']?.toString();
    if (uid == null || targetId == null || uid == targetId) return;
    try {
      final sent = await supabase.from('friend_requests').select('id,status')
          .eq('requester_id', uid).eq('recipient_id', targetId).maybeSingle();
      final received = await supabase.from('friend_requests').select('id,status')
          .eq('requester_id', targetId).eq('recipient_id', uid).maybeSingle();
      final existing = sent ?? received;
      if (existing != null) {
        final status = existing['status']?.toString();
        showMsg(context, status == 'accepted' ? 'شما از قبل مخاطب یکدیگر هستید.' :
            status == 'pending' ? 'درخواست دوستی قبلاً ثبت شده است.' :
            'درخواست قبلی وجود دارد؛ از صندوق درخواست‌ها آن را بررسی کنید.');
        return;
      }
      await supabase.from('friend_requests').insert({
        'requester_id': uid, 'recipient_id': targetId, 'status': 'pending',
      });
      if (mounted) {
        setState(() => friendRequestPending = true);
        showMsg(context, 'درخواست دوستی ارسال شد؛ پس از پذیرش، گفتگو و تماس فعال می‌شود.');
      }
    } catch (e) {
      if (mounted) showMsg(context, 'ارسال درخواست دوستی ناموفق بود: ${_friendlyError(e.toString())}');
    }
  }

  Future<void> _openChat() async {
    if (!isFriend) {
      showMsg(context, friendRequestPending
          ? 'درخواست دوستی هنوز پذیرفته نشده است.'
          : 'برای پیام دادن، ابتدا درخواست دوستی ارسال کنید.');
      return;
    }
    if (busy) return;
    setState(() => busy = true);
    try {
      final conversationId = await _ensureDirectConversationForUser(profile);
      if (conversationId == null) throw Exception('گفتگوی شخصی ایجاد نشد.');
      if (!mounted) return;
      await Navigator.push(context, MaterialPageRoute(builder: (_) => ChatPage(id: conversationId, title: displayName)));
    } catch (e) {
      if (mounted) showMsg(context, 'باز کردن گفتگو ناموفق بود: ${_friendlyError(e.toString())}');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }

  Future<void> _startCall({required bool video}) async {
    if (!isFriend) {
      showMsg(context, friendRequestPending
          ? 'درخواست دوستی هنوز پذیرفته نشده است.'
          : 'برای تماس، ابتدا درخواست دوستی ارسال کنید.');
      return;
    }
    if (busy) return;
    setState(() => busy = true);
    try {
      final conversationId = await _ensureDirectConversationForUser(profile);
      if (conversationId == null) throw Exception('گفتگوی شخصی برای تماس پیدا نشد.');
      if (!mounted) return;
      await Navigator.push(context, MaterialPageRoute(builder: (_) => CallSessionPage(
        conversationId: conversationId, title: displayName, video: video,
      )));
    } catch (e) {
      if (mounted) showMsg(context, 'شروع تماس ناموفق بود: ${_friendlyError(e.toString())}');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final s = Theme.of(context).colorScheme;
    final verified = profile['is_verified'] == true;
    final bio = '${profile['bio'] ?? ''}'.trim();
    final isSelf = supabase.auth.currentUser?.id == profile['id']?.toString();
    return Scaffold(
      appBar: AppBar(
        title: Text(trUi('حساب کاربری')),
        actions: [
          if (!isSelf) PopupMenuButton<String>(
            tooltip: 'گزینه‌های مخاطب',
            iconSize: 21,
            padding: const EdgeInsets.all(7),
            constraints: BoxConstraints(minWidth: 38, minHeight: 38),
            icon: Icon(Icons.more_vert_rounded),
            onSelected: (value) async {
              if (value == 'rename') await _editLocalName();
              if (value == 'friend') await _sendFriendRequest();
              if (value == 'contact') await _toggleContact();
            },
            itemBuilder: (_) => [
              PopupMenuItem(value: 'rename', child: ListTile(dense: true, leading: Icon(Icons.edit_rounded), title: Text(trUi('نام‌گذاری مخاطب')))),
              PopupMenuItem(value: 'friend', child: ListTile(dense: true, leading: Icon(Icons.person_add_alt_rounded), title: Text(trUi('درخواست دوستی')))),
              PopupMenuItem(value: 'contact', child: ListTile(dense: true, leading: Icon(isContact ? Icons.person_remove_alt_1_rounded : Icons.person_add_alt_1_rounded), title: Text(isContact ? 'حذف از مخاطبین' : 'افزودن به مخاطبین'))),
            ],
          ),
        ],
      ),
      body: NotificationListener<ScrollNotification>(
        onNotification: (notification) {
          final next = notification.metrics.pixels;
          // A downward pull at the top expands the portrait; scrolling up
          // smoothly returns it to its compact size.
          final clamped = next < 0 ? next.clamp(-110.0, 0.0).toDouble() : 0.0;
          if ((clamped - _profilePullOffset).abs() > 1.5 && mounted) {
            setState(() => _profilePullOffset = clamped);
          }
          return false;
        },
        child: ListView(
        physics: const BouncingScrollPhysics(parent: AlwaysScrollableScrollPhysics()),
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
        children: [
          Container(
            padding: const EdgeInsets.fromLTRB(18, 22, 18, 18),
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topRight,
                end: Alignment.bottomLeft,
                colors: [
                  s.primary.withValues(alpha: .13),
                  s.tertiary.withValues(alpha: .07),
                  s.surface.withValues(alpha: .82),
                ],
              ),
              borderRadius: BorderRadius.circular(26),
              border: Border.all(color: s.primary.withValues(alpha: .14)),
              boxShadow: [BoxShadow(color: s.primary.withValues(alpha: .06), blurRadius: 22, offset: Offset(0, 8))],
            ),
            child: Column(children: [
              GestureDetector(
                onTap: () => _openAvatarPreview(context, profile),
                child: Container(
                  padding: const EdgeInsets.all(4),
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    gradient: LinearGradient(colors: [s.primary, s.tertiary, s.primary.withValues(alpha: .45)]),
                    boxShadow: [BoxShadow(color: s.primary.withValues(alpha: .20), blurRadius: 20, spreadRadius: 1)],
                  ),
                  child: Container(
                    padding: const EdgeInsets.all(3),
                    decoration: BoxDecoration(shape: BoxShape.circle, color: s.surface),
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 180),
                      curve: Curves.easeOutCubic,
                      width: (104 + (-_profilePullOffset * 0.42)).clamp(104.0, 150.0),
                      height: (104 + (-_profilePullOffset * 0.42)).clamp(104.0, 150.0),
                      child: avatar(profile, size: (104 + (-_profilePullOffset * 0.42)).clamp(104.0, 150.0)),
                    ),
                  ),
                ),
              ),
              SizedBox(height: 14),
              Tooltip(
                message: trUi('برای کپی نام لمس کنید'),
                child: InkWell(
                  borderRadius: BorderRadius.circular(10),
                  onTap: () async {
                    final value = displayName.trim();
                    if (value.isEmpty) return;
                    try {
                      await Clipboard.setData(ClipboardData(text: value));
                      if (context.mounted) showMsg(context, 'نام کاربر کپی شد: $value');
                    } catch (_) {
                      if (context.mounted) showMsg(context, 'کپی نام ناموفق بود.');
                    }
                  },
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    child: Row(mainAxisAlignment: MainAxisAlignment.center, mainAxisSize: MainAxisSize.min, children: [
                      Flexible(child: Text(displayName, textAlign: TextAlign.center, style: TextStyle(fontSize: 24, fontWeight: FontWeight.w900))),
                      SizedBox(width: 6),
                      Icon(Icons.copy_rounded, size: 15, color: s.onSurfaceVariant),
                      if (verified) ...[SizedBox(width: 7), AnimatedVerifiedBadge(size: 19)],
                    ]),
                  ),
                ),
              ),
              if (username.isNotEmpty) Padding(
                padding: const EdgeInsets.only(top: 5),
                child: InkWell(
                  borderRadius: BorderRadius.circular(8),
                  onTap: () async {
                    final value = '@$username';
                    try {
                      await Clipboard.setData(ClipboardData(text: value));
                      if (context.mounted) showMsg(context, 'نام کاربری کپی شد: $value');
                    } catch (_) {
                      if (context.mounted) showMsg(context, 'کپی نام کاربری ناموفق بود.');
                    }
                  },
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                    child: Text(trUi('@$username'), style: TextStyle(color: s.primary, fontSize: 14, fontWeight: FontWeight.w800)),
                  ),
                ),
              ),
              SizedBox(height: 4),
              Text(isSelf ? 'پروفایل شما' : (isFriend ? 'دوست شما' : (isContact ? 'در فهرست مخاطبین شما' : 'پروفایل کاربر')), style: TextStyle(color: s.onSurfaceVariant, fontSize: 12)),
            ]),
          ),
          SizedBox(height: 14),
          if (!isSelf) Row(children: [
            if (isFriend) ...[
              Expanded(child: _profileAction(context, Icons.chat_bubble_rounded, 'پیام', busy ? null : _openChat)),
              SizedBox(width: 8),
              Expanded(child: _profileAction(context, Icons.call_rounded, 'تماس صوتی', busy ? null : () => _startCall(video: false))),
              SizedBox(width: 8),
              Expanded(child: _profileAction(context, Icons.videocam_rounded, 'تماس تصویری', busy ? null : () => _startCall(video: true))),
            ] else
              Expanded(child: _profileAction(
                context,
                Icons.person_add_alt_1_rounded,
                friendRequestPending ? 'در انتظار پاسخ' : 'درخواست دوستی',
                busy || friendRequestPending ? null : () => _sendFriendRequest(),
              )),
          ]),
          SizedBox(height: 18),
          Card(child: Column(children: [
            if (bio.isNotEmpty) ListTile(
              leading: Icon(Icons.format_quote_rounded, color: s.primary),
              title: Text(bio, textAlign: TextAlign.start, style: TextStyle(height: 1.5)),
              subtitle: Text(trUi('بیوگرافی')),
            ) else ListTile(leading: Icon(Icons.format_quote_rounded), title: Text(trUi('بیوگرافی ثبت نشده است'))),
            if (username.isNotEmpty) Divider(height: 1),
            if (username.isNotEmpty) ListTile(leading: Icon(Icons.alternate_email_rounded), title: Text(trUi('@$username')), subtitle: Text(trUi('نام کاربری'))),
          ])),
          SizedBox(height: 12),
          FutureBuilder<List<Map<String, dynamic>>>(
            future: _loadMutualGroups(profile['id']?.toString() ?? ''),
            builder: (context, snap) {
              if (snap.connectionState == ConnectionState.waiting) return Card(child: ListTile(leading: Icon(Icons.groups_rounded), title: Text(trUi('گروه‌های مشترک')), subtitle: Text(trUi('در حال بررسی…'))));
              final groups = snap.data ?? [];
              return Card(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                ListTile(leading: Icon(Icons.groups_rounded), title: Text(trUi('گروه‌های مشترک'))),
                if (groups.isEmpty) Padding(padding: EdgeInsets.fromLTRB(16, 0, 16, 16), child: Text(trUi('هیچ گروه مشترکی ندارید.'))),
                ...groups.map((g) => ListTile(
                  leading: CircleAvatar(child: Icon((g['type'] ?? 'group') == 'channel' ? Icons.campaign_rounded : Icons.groups_rounded)),
                  title: Text('${g['title'] ?? 'گروه'}'),
                  subtitle: Text('${g['type'] == 'channel' ? 'کانال' : 'گروه'} مشترک'),
                  trailing: Icon(Icons.chevron_left_rounded),
                  onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ChatPage(id: '${g['id']}', title: '${g['title'] ?? 'گروه'}'))),
                )),
              ]));
            },
          ),
          SizedBox(height: 12),
          Card(child: Column(children: [
            ListTile(leading: Icon(Icons.perm_media_outlined), title: Text(trUi('رسانه‌های مشترک')), subtitle: Text(trUi('عکس‌ها، ویدیوها، فایل‌ها و صداها')), trailing: Icon(Icons.chevron_left_rounded), onTap: busy ? null : _openChatMedia),
          ])),
        ],
      ),
      ),
    );
  }

  Widget _profileAction(BuildContext context, IconData icon, String label, VoidCallback? onTap) {
    final s = Theme.of(context).colorScheme;
    return Material(
      color: s.surfaceContainerHighest.withValues(alpha: .55),
      borderRadius: BorderRadius.circular(16),
      child: InkWell(
        borderRadius: BorderRadius.circular(16),
        onTap: onTap,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 3),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Icon(icon, color: s.primary, size: 24),
            SizedBox(height: 8),
            Text(label, textAlign: TextAlign.center, style: TextStyle(fontSize: 11, fontWeight: FontWeight.w700)),
          ]),
        ),
      ),
    );
  }

  Future<List<Map<String, dynamic>>> _loadMutualGroups(String targetId) async {
    final uid = supabase.auth.currentUser?.id;
    if (uid == null || targetId.isEmpty || uid == targetId) return [];
    final mine = await supabase.from('conversation_members').select('conversation_id').eq('user_id', uid);
    final theirs = await supabase.from('conversation_members').select('conversation_id').eq('user_id', targetId);
    final mineIds = (mine as List).map((e) => '${e['conversation_id']}').toSet();
    final shared = (theirs as List).map((e) => '${e['conversation_id']}').where(mineIds.contains).toSet().toList();
    if (shared.isEmpty) return [];
    final rows = await supabase.from('conversations').select('id,type,title').inFilter('id', shared).inFilter('type', ['group', 'channel']);
    return List<Map<String, dynamic>>.from(rows);
  }

  Future<void> _openChatMedia() async {
    if (busy) return;
    setState(() => busy = true);
    try {
      final id = await _ensureDirectConversationForUser(profile);
      if (id == null) throw Exception('گفتگوی خصوصی پیدا نشد.');
      if (!mounted) return;
      await Navigator.push(context, MaterialPageRoute(builder: (_) => SharedMediaPage(conversationId: id)));
    } catch (e) {
      if (mounted) showMsg(context, 'رسانه‌ها باز نشد: ${_friendlyError(e.toString())}');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }
}

class FriendRequestsPage extends StatefulWidget {
  FriendRequestsPage({super.key});
  @override
  State<FriendRequestsPage> createState() => _FriendRequestsPageState();
}

class _FriendRequestsPageState extends State<FriendRequestsPage> {
  bool loading = true;
  List<Map<String, dynamic>> requests = [];

  @override
  void initState() {
    super.initState();
    loadRequests();
  }

  Future<void> loadRequests() async {
    setState(() => loading = true);
    try {
      final uid = supabase.auth.currentUser?.id;
      if (uid == null) return;
      final raw = await supabase.from('friend_requests').select('id,requester_id,created_at,status')
          .eq('recipient_id', uid).eq('status', 'pending').order('created_at', ascending: false);
      final rows = List<Map<String, dynamic>>.from(raw);
      final ids = rows.map((r) => r['requester_id'].toString()).toSet().toList();
      final people = ids.isEmpty ? <Map<String, dynamic>>[] :
          List<Map<String, dynamic>>.from(await supabase.from('profiles')
              .select('id,display_name,username,avatar_url,bio,is_verified').inFilter('id', ids));
      final byId = {for (final p in people) p['id'].toString(): p};
      for (final r in rows) { r['_profile'] = byId[r['requester_id'].toString()] ?? <String,dynamic>{}; }
      if (mounted) setState(() => requests = rows);
    } catch (e) {
      if (mounted) showMsg(context, 'درخواست‌ها بارگذاری نشد: ${_friendlyError(e.toString())}');
    } finally {
      if (mounted) setState(() => loading = false);
    }
  }

  Future<void> respond(Map<String, dynamic> request, bool accept) async {
    try {
      await supabase.rpc('respond_to_friend_request', params: {
        'p_request_id': request['id'], 'p_accept': accept,
      });
      if (!mounted) return;
      showMsg(context, accept ? 'درخواست پذیرفته شد و مخاطب اضافه شد.' : 'درخواست رد شد.');
      await loadRequests();
    } catch (e) {
      if (mounted) showMsg(context, 'عملیات ناموفق بود: ${_friendlyError(e.toString())}');
    }
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return Scaffold(
      appBar: AppBar(title: Text(trUi('درخواست‌های دوستی')), actions: [
        IconButton(onPressed: loadRequests, icon: Icon(Icons.refresh_rounded)),
      ]),
      body: loading
          ? Center(child: CircularProgressIndicator())
          : requests.isEmpty
              ? Center(child: Text(trUi('درخواست دوستی جدیدی ندارید.')))
              : ListView.separated(
                  padding: const EdgeInsets.all(12),
                  itemCount: requests.length,
                  separatorBuilder: (_, __) => SizedBox(height: 8),
                  itemBuilder: (context, i) {
                    final r = requests[i];
                    final p = Map<String, dynamic>.from(r['_profile'] as Map);
                    final name = (p['display_name'] ?? p['username'] ?? 'کاربر').toString();
                    return Card(
                      child: Padding(
                        padding: const EdgeInsets.all(10),
                        child: Column(children: [
                          ListTile(
                            contentPadding: EdgeInsets.zero,
                            leading: avatar(p, size: 48),
                            title: Text(name, style: TextStyle(fontWeight: FontWeight.w800)),
                            subtitle: Text(p['username'] == null ? 'درخواست دوستی' : '@${p['username']}'),
                            onTap: () => Navigator.push(context, MaterialPageRoute(
                              builder: (_) => PublicUserProfilePage(profile: p),
                            )),
                          ),
                          Row(children: [
                            Expanded(child: FilledButton.icon(
                              onPressed: () => respond(r, true),
                              icon: Icon(Icons.check_rounded), label: Text(trUi('پذیرفتن')),
                            )),
                            SizedBox(width: 8),
                            Expanded(child: OutlinedButton.icon(
                              onPressed: () => respond(r, false),
                              icon: Icon(Icons.close_rounded, color: scheme.error),
                              label: Text(trUi('رد کردن')),
                            )),
                          ]),
                        ]),
                      ),
                    );
                  },
                ),
    );
  }
}

class UserSearchDelegate extends SearchDelegate<Map<String, dynamic>?> {
  @override
  List<Widget>? buildActions(BuildContext context) => [IconButton(onPressed: () => query = '', icon: Icon(Icons.clear))];

  @override
  Widget? buildLeading(BuildContext context) => IconButton(onPressed: () => close(context, null), icon: Icon(Icons.arrow_back));

  @override
  Widget buildResults(BuildContext context) => resultsWidget();

  @override
  Widget buildSuggestions(BuildContext context) => resultsWidget();

  Widget resultsWidget() {
    final q = query.trim();
    if (q.isEmpty) return Center(child: Text(trUi('نام یا نام کاربری را جستجو کنید')));
    return FutureBuilder<List<Map<String, dynamic>>>(
      future: supabase.rpc('search_profiles', params: {'search_text': q}).then((v) => List<Map<String, dynamic>>.from(v)),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting) return AppSkeletonList(count: 5);
        if (snapshot.hasError) return AppEmptyState(icon: Icons.search_off_rounded, title: 'جستجو ناموفق بود', subtitle: _friendlyError('${snapshot.error}'));
        final rows = snapshot.data ?? [];
        if (rows.isEmpty) return AppEmptyState(icon: Icons.person_search_rounded, title: 'کاربری پیدا نشد', subtitle: 'نام یا نام کاربری دیگری را امتحان کنید.');
        return ListView(
          children: rows.map((p) {
            return ListTile(
              leading: avatar(p),
              title: Text('${p['display_name'] ?? ''}'),
              subtitle: Text('@${p['username'] ?? ''}'),
              onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => PublicUserProfilePage(profile: p))),
            );
          }).toList(),
        );
      },
    );
  }
}

class GroupCreatePage extends StatefulWidget {
  GroupCreatePage({super.key});

  @override
  State<GroupCreatePage> createState() => _GroupCreatePageState();
}

class _GroupCreatePageState extends State<GroupCreatePage> {
  final title = TextEditingController();
  final search = TextEditingController();
  List<Map<String, dynamic>> found = [];
  List<Map<String, dynamic>> selected = [];
  List<Map<String, dynamic>> availableContacts = [];
  bool loadingContacts = true;
  bool busy = false;
  int _searchRevision = 0;
  String? titleError;

  @override
  void initState() {
    super.initState();
    loadContacts();
  }

  Future<void> loadContacts() async {
    try {
      final uid = supabase.auth.currentUser?.id;
      if (uid == null) throw Exception('ابتدا وارد حساب شوید.');
      final rows = await supabase.from('contacts').select('contact_id')
          .eq('user_id', uid).timeout(Duration(seconds: 8));
      final ids = (rows as List).map((r) => r['contact_id']?.toString() ?? '')
          .where((id) => id.isNotEmpty && id != uid).toSet().toList();
      final profiles = ids.isEmpty ? <Map<String,dynamic>>[] :
        List<Map<String,dynamic>>.from(await supabase.from('profiles')
          .select('id,display_name,username,avatar_url').inFilter('id', ids)
          .timeout(Duration(seconds: 8)));
      profiles.sort((a,b) => (a['display_name'] ?? a['username'] ?? '').toString().toLowerCase()
          .compareTo((b['display_name'] ?? b['username'] ?? '').toString().toLowerCase()));
      if (mounted) setState(() { availableContacts = profiles; found = profiles; loadingContacts = false; });
    } catch (e) {
      if (mounted) {
        setState(() => loadingContacts = false);
        showMsg(context, 'مخاطبین بارگذاری نشدند؛ می‌توانید دوباره تلاش کنید. ${_friendlyError(e.toString())}');
      }
    }
  }

  Future<void> findUsers(String q) async {
    final term = q.trim();
    final revision = ++_searchRevision;
    if (term.isEmpty) {
      if (mounted) setState(() => found = List<Map<String, dynamic>>.from(availableContacts));
      return;
    }
    try {
      final raw = await supabase.rpc('search_profiles', params: {'search_text': term});
      final uid = supabase.auth.currentUser?.id;
      final matches = List<Map<String, dynamic>>.from(raw as List)
          .where((p) => p['id'] != null && p['id'].toString() != uid)
          .toList();
      if (mounted && revision == _searchRevision) setState(() => found = matches);
    } catch (_) {
      final lower = term.toLowerCase();
      final matches = availableContacts.where((p) =>
        (p['display_name'] ?? '').toString().toLowerCase().contains(lower) ||
        (p['username'] ?? '').toString().toLowerCase().contains(lower)).toList();
      if (mounted && revision == _searchRevision) setState(() => found = matches);
    }
  }

  Future<void> createGroup() async {
    if (title.text.trim().isEmpty) { setState(() => titleError = 'نام گروه را وارد کنید.'); return; }
    if (selected.isEmpty) { showMsg(context, 'حداقل یک مخاطب را انتخاب کنید.'); return; }
    setState(() => busy = true);
    try {
      final uid = supabase.auth.currentUser!.id;
      final c = await supabase.from('conversations').insert({'type': 'group', 'title': title.text.trim(), 'created_by': uid}).select().single();
      final uniqueIds = <String>{uid, ...selected.map((p) => '${p['id']}')};
      final members = uniqueIds.map((memberId) => {'conversation_id': c['id'], 'user_id': memberId}).toList();
      await supabase.from('conversation_members').insert(members);
      await supabase.from('conversation_admins').insert({'conversation_id':c['id'],'user_id':uid,'role':'owner'});
      if (mounted) {
        Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => ChatPage(id: '${c['id']}', title: title.text.trim())));
      }
    } catch (e) {
      if (mounted) showMsg(context, 'ساخت گروه ناموفق بود: $e');
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }

  @override
  void dispose() {
    title.dispose();
    search.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(trUi('ساخت گروه'))),
      body: Column(
        children: [
          Padding(padding: const EdgeInsets.all(12), child: TextField(controller: title, onChanged: (v) => setState(() => titleError = v.trim().isEmpty ? 'نام گروه را وارد کنید.' : null), decoration: InputDecoration(labelText: 'نام گروه', errorText: titleError, border: OutlineInputBorder()))),
          Padding(padding: const EdgeInsets.fromLTRB(12, 0, 12, 8), child: TextField(controller: search, onChanged: findUsers, decoration: InputDecoration(hintText: 'جستجو و انتخاب از مخاطبین...', prefixIcon: Icon(Icons.search), border: OutlineInputBorder()))),
          if (selected.isNotEmpty)
            SizedBox(
              height: 60,
              child: ListView(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.all(8),
                children: selected.map((p) {
                  return Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: Chip(
                      label: Text('${p['display_name'] ?? ''}'),
                      onDeleted: () => setState(() => selected.remove(p)),
                    ),
                  );
                }).toList(),
              ),
            ),
          Expanded(
            child: loadingContacts
                ? Center(child: CircularProgressIndicator())
                : found.isEmpty
                  ? Center(child: Padding(
                      padding: const EdgeInsets.all(24),
                      child: Column(mainAxisSize: MainAxisSize.min, children: [
                        Text(search.text.trim().isNotEmpty
                          ? 'کاربری با این نام یا شناسه پیدا نشد.'
                          : (availableContacts.isEmpty
                            ? 'هنوز مخاطبی ندارید. نام کاربری فرد را جستجو کنید یا از بخش «مخاطبین» او را اضافه کنید.'
                            : 'مخاطبی ندارید؛ برای افزودن افراد از جستجو استفاده کنید.'), textAlign: TextAlign.center),
                        if (search.text.trim().isEmpty && availableContacts.isEmpty) ...[
                          SizedBox(height: 12),
                          OutlinedButton.icon(
                            onPressed: loadingContacts ? null : () {
                              setState(() { loadingContacts = true; });
                              loadContacts();
                            },
                            icon: Icon(Icons.refresh_rounded),
                            label: Text(trUi('بارگذاری دوباره مخاطبین')),
                          ),
                        ],
                      ]),
                    ))
                  : ListView(
              children: found.map((p) {
                final isSelected = selected.any((x) => x['id'] == p['id']);
                return ListTile(
                  leading: avatar(p),
                  title: Text('${p['display_name'] ?? ''}'),
                  subtitle: Text('@${p['username'] ?? ''}'),
                  trailing: Icon(isSelected ? Icons.check_circle : Icons.add),
                  onTap: () => setState(() {
                    if (isSelected) {
                      selected.removeWhere((x) => x['id'] == p['id']);
                    } else {
                      selected.add(p);
                    }
                  }),
                );
              }).toList(),
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(12),
            child: SizedBox(width: double.infinity, child: FilledButton(onPressed: busy ? null : createGroup, child: Text(busy ? 'در حال ساخت...' : 'ساخت گروه'))),
          ),
        ],
      ),
    );
  }
}

class ContactSearchDelegate extends SearchDelegate<Map<String,dynamic>?> {
  @override List<Widget>? buildActions(BuildContext context) => [IconButton(onPressed: () => query = '', icon: Icon(Icons.clear))];
  @override Widget buildLeading(BuildContext context) => IconButton(onPressed: () => close(context, null), icon: Icon(Icons.arrow_back));
  @override Widget buildResults(BuildContext context) => _build(context);
  @override Widget buildSuggestions(BuildContext context) => _build(context);
  Widget _build(BuildContext context) => FutureBuilder(
    future: query.trim().isEmpty ? Future.value([]) : supabase.rpc('search_profiles', params: {'search_text': query.trim()}),
    builder: (context, snap) {
      if (query.trim().isEmpty) return Center(child: Text(trUi('نام یا آیدی کاربر را جستجو کنید.')));
      if (!snap.hasData) return Center(child: CircularProgressIndicator());
      final users = List<Map<String,dynamic>>.from(snap.data as List);
      return ListView(children: users.map((p) => ListTile(
        leading: avatar(p),
        title: Text((p['display_name'] ?? p['username'] ?? 'کاربر').toString()),
        subtitle: Text('@' + (p['username'] ?? '').toString()),
        trailing: Icon(Icons.person_add_alt_1_rounded),
        onTap: () async {
          final uid = supabase.auth.currentUser!.id;
          if (p['id'].toString() == uid) { showMsg(context, 'نمی‌توانید خودتان را اضافه کنید.'); return; }
          await supabase.from('contacts').upsert({'user_id': uid, 'contact_id': p['id']}, onConflict: 'user_id,contact_id');
          if (context.mounted) { showMsg(context, 'مخاطب اضافه شد.'); close(context, p); }
        },
      )).toList());
    },
  );
}

