}


class ConversationToolsPage extends StatefulWidget {
  final String conversationId;
  ConversationToolsPage({super.key, required this.conversationId});
  @override State<ConversationToolsPage> createState()=>_ConversationToolsPageState();
}

class _ConversationToolsPageState extends State<ConversationToolsPage>{
  bool loading=true, archived=false;

  @override void initState(){super.initState();_load();}

  Future<void> _load() async {
    final uid=supabase.auth.currentUser?.id;
    if(uid==null){if(mounted)setState(()=>loading=false);return;}
    try{
      final row=await supabase.from('chat_archives')
        .select('id')
        .eq('user_id',uid)
        .eq('conversation_id',widget.conversationId)
        .maybeSingle();
      if(mounted)setState((){archived=row!=null;loading=false;});
    }catch(e){
      if(mounted){setState(()=>loading=false);showMsg(context,'وضعیت گفتگو بارگذاری نشد: '+_friendlyError(e.toString()));}
    }
  }

  Future<void> _toggleArchive() async {
    final uid=supabase.auth.currentUser?.id;
    if(uid==null)return;
    setState(()=>loading=true);
    try{
      if(archived){
        await supabase.from('chat_archives').delete()
          .eq('user_id',uid).eq('conversation_id',widget.conversationId);
      }else{
        await supabase.from('chat_archives').insert({
          'user_id':uid,
          'conversation_id':widget.conversationId,
        });
      }
      if(mounted){
        setState((){archived=!archived;loading=false;});
        showMsg(context,archived?'گفتگو به آرشیو منتقل شد.':'گفتگو از آرشیو خارج شد.');
      }
    }catch(e){
      if(mounted){setState(()=>loading=false);showMsg(context,'تغییر آرشیو ناموفق بود: '+_friendlyError(e.toString()));}
    }
  }

  @override Widget build(BuildContext context)=>Scaffold(
    appBar:AppBar(title:Text(trUi('مدیریت گفتگو'))),
    body:loading
      ? Center(child:CircularProgressIndicator())
      : ListView(padding:const EdgeInsets.all(16),children:[
        Card(child:SwitchListTile(
          value:archived,
          onChanged:(_)=>_toggleArchive(),
          title:Text(trUi('آرشیو گفتگو')),
          subtitle:Text(archived?'این گفتگو در آرشیو است':'این گفتگو در فهرست اصلی است'),
          secondary:Icon(Icons.archive_rounded),
        )),
        Card(child:ListTile(
          title:Text(trUi('پوشه گفتگو')),
          subtitle:Text(trUi('ساخت و مدیریت پوشه‌های واقعی گفتگو')),
          leading:Icon(Icons.folder_rounded),
          onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatFoldersPage())),
        )),
        Card(child:ListTile(
          title:Text(trUi('پس‌زمینه گفتگو')),
          subtitle:Text(trUi('تغییر پس‌زمینه همین گفتگو')),
          leading:Icon(Icons.wallpaper_rounded),
          onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatBackgroundPage())),
        )),
        SizedBox(height:8),
        AppEmptyState(
          icon:Icons.tune_rounded,
          title:'گزینه‌های پین و بی‌صدا فعلاً نمایش داده نمی‌شوند',
          subtitle:'تا زمانی که ذخیره‌سازی واقعی این وضعیت‌ها به حساب کاربر متصل نشود، گزینه نمایشی در برنامه وجود ندارد.',
        ),
      ]),
  );
}

class ContactsToolsPage extends StatefulWidget {
  ContactsToolsPage({super.key});
  @override State<ContactsToolsPage> createState() => _ContactsToolsPageState();
}

class _ContactsToolsPageState extends State<ContactsToolsPage> {
  late Future<List<Map<String, dynamic>>> _future = _load();

  Future<List<Map<String, dynamic>>> _load() async {
    final uid = supabase.auth.currentUser?.id;
    if (uid == null) throw Exception('برای دیدن مخاطبین ابتدا وارد حساب شوید.');
    final rows = await supabase.from('contacts').select('contact_id').eq('user_id', uid);
    final ids = (rows as List)
        .map((row) => row['contact_id']?.toString() ?? '')
        .where((id) => id.isNotEmpty && id != uid)
        .toSet()
        .toList();
    if (ids.isEmpty) return <Map<String, dynamic>>[];
    final result = await supabase
        .from('profiles')
        .select('id,display_name,username,avatar_url,bio')
        .inFilter('id', ids);
    final profiles = List<Map<String, dynamic>>.from(result);
    profiles.sort((a, b) => (a['display_name'] ?? a['username'] ?? '')
        .toString().toLowerCase().compareTo(
          (b['display_name'] ?? b['username'] ?? '').toString().toLowerCase(),
        ));
    return profiles;
  }

  void _reload() => setState(() => _future = _load());

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(
      title: Text(trUi('مخاطبین')),
      actions: [
        IconButton(
          tooltip: 'تازه‌سازی',
          onPressed: _reload,
          icon: Icon(Icons.refresh_rounded),
        ),
        IconButton(
          tooltip: 'افزودن مخاطب',
          onPressed: () async {
            final selected = await showSearch<Map<String, dynamic>?>(
              context: context,
              delegate: ContactSearchDelegate(),
            );
            if (selected != null && mounted) _reload();
          },
          icon: Icon(Icons.person_add_alt_1_rounded),
        ),
      ],
    ),
    body: FutureBuilder<List<Map<String, dynamic>>>(
      future: _future,
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting) {
          return AppSkeletonList(count: 6);
        }
        if (snapshot.hasError) {
          return Center(
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  AppEmptyState(
                    icon: Icons.cloud_off_rounded,
                    title: 'مخاطبین بارگذاری نشدند',
                    subtitle: _friendlyError('${snapshot.error}'),
                  ),
                  SizedBox(height: 12),
                  FilledButton.icon(
                    onPressed: _reload,
                    icon: Icon(Icons.refresh_rounded),
                    label: Text(trUi('تلاش دوباره')),
                  ),
                ],
              ),
            ),
          );
        }
        final contacts = snapshot.data ?? <Map<String, dynamic>>[];
        if (contacts.isEmpty) {
          return Center(
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  AppEmptyState(
                    icon: Icons.people_alt_outlined,
                    title: 'هنوز مخاطبی نداری',
                    subtitle: 'با جستجوی نام کاربری، افراد را به فهرست مخاطبین اضافه کن.',
                  ),
                  SizedBox(height: 12),
                  FilledButton.icon(
                    onPressed: () async {
                      final selected = await showSearch<Map<String, dynamic>?>(
                        context: context,
                        delegate: ContactSearchDelegate(),
                      );
                      if (selected != null && mounted) _reload();
                    },
                    icon: Icon(Icons.person_add_alt_1_rounded),
                    label: Text(trUi('افزودن مخاطب')),
                  ),
                ],
              ),
            ),
          );
        }
        return RefreshIndicator(
          onRefresh: () async => _reload(),
          child: ListView.separated(
            padding: const EdgeInsets.fromLTRB(12, 12, 12, 28),
            itemCount: contacts.length,
            separatorBuilder: (_, __) => SizedBox(height: 5),
            itemBuilder: (context, index) {
              final profile = contacts[index];
              final name = (profile['display_name'] ?? profile['username'] ?? 'کاربر')
                  .toString().trim();
              return Card(
                child: ListTile(
                  leading: GestureDetector(
                    onTap: () => _openAvatarPreview(context, profile),
                    child: avatar(profile, size: 50),
                  ),
                  title: Text(name, maxLines: 1, overflow: TextOverflow.ellipsis),
                  subtitle: Text(
                    (profile['username'] ?? '').toString().isEmpty
                        ? 'نمایش پروفایل'
                        : '@${profile['username']}',
                  ),
                  onTap: () => Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => PublicUserProfilePage(profile: profile),
                    ),
                  ),
                  trailing: Icon(Icons.chevron_left_rounded),
                ),
              );
            },
          ),
        );
      },
    ),
  );
}

class DataSettingsPage extends StatefulWidget {
  DataSettingsPage({super.key});
  @override State<DataSettingsPage> createState() => _DataSettingsPageState();
}
class _DataSettingsPageState extends State<DataSettingsPage> {
  bool low = false, wifi = true, loading = true;
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async {
    try {
      final values = await loadUserSettings();
      if (!mounted) return;
      setState(() {
        low = values['low_data_mode'] ?? false;
        wifi = values['wifi_only_downloads'] ?? true;
        loading = false;
      });
    } catch (_) {
      if (mounted) setState(() => loading = false);
    }
  }
  Future<void> _change(String key, bool value, bool previous, ValueChanged<bool> update) async {
    if (mounted) setState(() => update(value));
    try {
      await saveUserSettings({key: value});
      if (mounted) showMsg(context, 'تنظیم ذخیره شد.');
    } catch (e) {
      if (!mounted) return;
      setState(() => update(previous));
      showMsg(context, 'ذخیره تنظیم انجام نشد: '+_friendlyError(e.toString()));
    }
  }
  @override Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: Text(trUi('مصرف داده'))),
    body: loading ? Center(child: CircularProgressIndicator()) : ListView(
      padding: const EdgeInsets.all(16),
      children: [
        Card(child: SwitchListTile(
          value: low,
          onChanged: (v) => _change('low_data_mode', v, low, (next) => low = next),
          title: Text(trUi('حالت کم‌مصرف')),
          subtitle: Text(trUi('ترجیح برای کاهش مصرف اینترنت و داده')),
          secondary: Icon(Icons.data_saver_on_rounded),
        )),
        Card(child: SwitchListTile(
          value: wifi,
          onChanged: (v) => _change('wifi_only_downloads', v, wifi, (next) => wifi = next),
          title: Text(trUi('دانلود خودکار فقط با وای‌فای')),
          subtitle: Text(trUi('برای جلوگیری از مصرف ناخواسته اینترنت همراه')),
          secondary: Icon(Icons.wifi_rounded),
        )),
        Padding(
          padding: EdgeInsets.all(8),
          child: Text(trUi('این تنظیمات در حساب شما ذخیره می‌شوند؛ اعمال محدودیت روی همه انواع رسانه به پشتیبانی هر بخش از برنامه بستگی دارد.')),
        ),
      ],
    ),
  );
}

class AccessibilityPage extends StatefulWidget {
  AccessibilityPage({super.key});
  @override State<AccessibilityPage> createState() => _AccessibilityPageState();
}
class _AccessibilityPageState extends State<AccessibilityPage> {
  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final scale = appAccessibility.textScale;
    return Scaffold(
      appBar: AppBar(
        title: Text(trUi('دسترسی‌پذیری')),
        actions: [
          TextButton(
            onPressed: () async {
              await appAccessibility.setTextScale(1);
              await appAccessibility.setHighContrast(false);
              if (mounted) showMsg(context, 'تنظیمات خوانایی به حالت پیش‌فرض برگشت.');
            },
            child: Text(trUi('بازنشانی')),
          ),
        ],
      ),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          Card(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16, 14, 16, 16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(children: [
                    Icon(Icons.text_fields_rounded, color: scheme.primary),
                    SizedBox(width: 10),
                    Expanded(child: Text(trUi('اندازه متن در کل برنامه'), style: TextStyle(fontWeight: FontWeight.w800))),
                    Text(trUi('${(scale * 100).round()}%'), style: TextStyle(color: scheme.primary, fontWeight: FontWeight.w900)),
                  ]),
                  Slider(
                    value: scale,
                    min: .8,
                    max: 1.5,
                    divisions: 7,
