class SavedMessagesPage extends StatefulWidget {
  SavedMessagesPage({super.key});
  @override
  State<SavedMessagesPage> createState() => _SavedMessagesPageState();
}

class _SavedMessagesPageState extends State<SavedMessagesPage> {
  List<Map<String, dynamic>> items = [];
  bool loading = true;
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async {
    try {
      final rows = await supabase.from('saved_messages').select('id, body, message_type, created_at').eq('user_id', supabase.auth.currentUser!.id).order('created_at', ascending: false);
      if (!mounted) return;
      setState(() { items = List<Map<String, dynamic>>.from(rows); loading = false; });
    } catch (e) {
      if (!mounted) return;
      setState(() => loading = false);
      showMsg(context, 'پیام‌های ذخیره‌شده بارگذاری نشد');
    }
  }
  Future<void> _remove(String id) async {
    final previous = List<Map<String,dynamic>>.from(items);
    if (mounted) setState(() => items = items.where((m) => '${m['id']}' != id).toList());
    try {
      await supabase.from('saved_messages').delete().eq('id', id);
    } catch (e) {
      if (!mounted) return;
      setState(() => items = previous);
      showMsg(context, 'حذف پیام ناموفق بود؛ پیام برگردانده شد.');
    }
  }
  @override Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: Text(trUi('پیام‌های ذخیره‌شده'))),
    body: loading ? Center(child: CircularProgressIndicator()) : items.isEmpty
      ? Center(child: Text(trUi('هنوز پیامی ذخیره نکرده‌اید.')))
      : ListView.separated(padding: const EdgeInsets.all(12), itemCount: items.length, separatorBuilder: (_, __) => SizedBox(height: 8), itemBuilder: (context, i) {
          final m = items[i];
          final type = '${m['message_type'] ?? 'text'}';
          final body = '${m['body'] ?? ''}';
          final title = body.isEmpty ? (type == 'image' ? 'تصویر' : type == 'audio' ? 'پیام صوتی' : 'پیام') : body;
          return Card(child: ListTile(leading: Icon(Icons.bookmark_rounded), title: Text(title, maxLines: 3, overflow: TextOverflow.ellipsis), subtitle: Text(trUi('ذخیره‌شده در Arad Messenger')), trailing: IconButton(icon: Icon(Icons.delete_outline_rounded), onPressed: () => _remove('${m['id']}'))));
        }),
  );
}
class GroupProfilePage extends StatefulWidget {
  final String conversationId;
  final String title;
  GroupProfilePage({super.key, required this.conversationId, required this.title});
  @override State<GroupProfilePage> createState() => _GroupProfilePageState();
}

class _GroupProfilePageState extends State<GroupProfilePage> {
  bool loading = true, saving = false;
  String? loadError;
  Map<String,dynamic> group = {};
  List<Map<String,dynamic>> members = [];
  String myRole = 'member';
  bool canEditRules = false, canManageMembers = false, canAddMembers = false, canRemoveMembers = false;
  bool get isCreator => group['created_by']?.toString() == supabase.auth.currentUser?.id;

  @override void initState() { super.initState(); _load(); }

  Future<void> _load() async {
    if (mounted) setState(() { loading = true; loadError = null; });
    try {
      final uid = supabase.auth.currentUser!.id;
      final groupRows = await Future.wait<dynamic>([
        supabase.from('conversations').select().eq('id', widget.conversationId).single(),
        supabase.from('conversation_members').select('user_id,role,joined_at').eq('conversation_id', widget.conversationId),
      ]);
      final c = Map<String,dynamic>.from(groupRows[0] as Map);
      final rows = List<Map<String,dynamic>>.from(groupRows[1] as List);
      final ids = rows.map((e) => e['user_id'].toString()).toList();
      List<Map<String,dynamic>> profiles = [];
      if (ids.isNotEmpty) {
        // Presence/bio fields are optional in older schemas; do not let them hide the group.
        try {
          profiles = List<Map<String,dynamic>>.from(await supabase.from('profiles').select('id,display_name,username,avatar_url,bio,is_online').inFilter('id', ids));
        } catch (_) {
          try {
            profiles = List<Map<String,dynamic>>.from(await supabase.from('profiles').select('id,display_name,username,avatar_url').inFilter('id', ids));
          } catch (_) { profiles = []; }
        }
      }
      final byId = {for(final p in profiles) p['id'].toString():p};
      final enriched = rows.map((m)=>{...m,'_profile':byId[m['user_id'].toString()] ?? <String,dynamic>{}}).toList()
        ..sort((a,b) => (a['role']=='owner' ? 0 : a['role']=='admin' ? 1 : 2).compareTo(b['role']=='owner' ? 0 : b['role']=='admin' ? 1 : 2));
      final mine = rows.where((m)=>m['user_id'].toString()==uid).toList();
      final resolvedRole = mine.isEmpty ? 'member' : (mine.first['role'] ?? 'member').toString();
      final creatorNow = c['created_by']?.toString() == uid;
      Map<String, dynamic> adminPermissions = {};
      if (!creatorNow && resolvedRole == 'admin') {
        try {
          final permissionRow = await supabase.from('group_admin_permissions')
              .select('can_add_members,can_remove_members,can_edit_group')
              .eq('conversation_id', widget.conversationId).eq('user_id', uid).maybeSingle();
          if (permissionRow != null) adminPermissions = Map<String, dynamic>.from(permissionRow);
        } catch (_) {}
      }
      if(!mounted)return;
      setState(() {
        group=Map<String,dynamic>.from(c); members=enriched; myRole=resolvedRole; loadError=null;
        canAddMembers=creatorNow || resolvedRole=='owner' || adminPermissions['can_add_members']==true;
        canRemoveMembers=creatorNow || resolvedRole=='owner' || adminPermissions['can_remove_members']==true;
        canManageMembers=canAddMembers || canRemoveMembers;
        canEditRules=creatorNow || resolvedRole=='owner' || adminPermissions['can_edit_group']==true;
        loading=false;
      });
    } catch(e) {
      if(!mounted)return;
      setState(() { loading=false; loadError=e.toString(); });
      showMsg(context,'بارگذاری پروفایل گروه ناموفق بود: '+_friendlyError(e.toString()));
    }
  }

  Future<void> _changeGroupPhoto() async {
    if (!canEditRules || saving) return;
    final source = await showModalBottomSheet<ImageSource>(context: context, showDragHandle: true,
      builder: (sheet) => SafeArea(child: Wrap(children: [
        ListTile(leading: Icon(Icons.photo_library_rounded), title: Text(trUi('انتخاب عکس از گالری')), onTap: () => Navigator.pop(sheet, ImageSource.gallery)),
        ListTile(leading: Icon(Icons.camera_alt_rounded), title: Text(trUi('گرفتن عکس با دوربین')), onTap: () => Navigator.pop(sheet, ImageSource.camera)),
      ])));
    if (source == null) return;
    final picked = await ImagePicker().pickImage(source: source, imageQuality: 85, maxWidth: 1200);
    if (picked == null) return;
    setState(() => saving = true);
    try {
      final bytes = await picked.readAsBytes();
      final path = 'groups/${widget.conversationId}/avatar-${DateTime.now().millisecondsSinceEpoch}.jpg';
      await supabase.storage.from('avatars').uploadBinary(path, bytes,
        fileOptions: FileOptions(upsert: true, contentType: 'image/jpeg'));
      final url = supabase.storage.from('avatars').getPublicUrl(path);
      await supabase.rpc('update_group_settings', params: {
        'p_conversation_id': widget.conversationId,
        'p_title': group['title'],
        'p_description': group['description'],
        'p_avatar_url': url,
        'p_is_public': group['is_public'] ?? false,
        'p_username': group['username'],
        'p_join_approval': group['join_approval'] ?? false,
        'p_only_admins_can_post': group['only_admins_can_post'] ?? false,
        'p_only_admins_can_add': group['only_admins_can_add'] ?? false,
        'p_auto_delete_seconds': group['auto_delete_seconds'] ?? 0,
        'p_allow_reactions': group['allow_reactions'] ?? true,
      });
      await _load();
      if (mounted) showMsg(context, 'عکس گروه تغییر کرد.');
    } catch (e) {
      if (mounted) showMsg(context, 'تغییر عکس گروه ناموفق بود: ${_friendlyError(e.toString())}');
    } finally { if (mounted) setState(() => saving = false); }
  }

  Future<void> _openGroupSettings() async {
    if (!canEditRules || saving) return;
    var publicGroup = group['is_public'] == true;
    var approval = group['join_approval'] == true;
    var adminsPost = group['only_admins_can_post'] == true;
    var adminsAdd = group['only_admins_can_add'] == true;
    var reactions = group['allow_reactions'] != false;
    var ttl = (group['auto_delete_seconds'] as num?)?.toInt() ?? 0;
    final result = await showDialog<Map<String, dynamic>>(context: context, builder: (dialog) =>
      StatefulBuilder(builder: (dialog, setDialog) => AlertDialog(
        title: Text(trUi('تنظیمات کامل گروه')),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          SwitchListTile(contentPadding: EdgeInsets.zero, title: Text(trUi('گروه عمومی')), subtitle: Text(trUi('امکان پیدا کردن گروه با نام کاربری')), value: publicGroup, onChanged: (v) => setDialog(() => publicGroup = v)),
          SwitchListTile(contentPadding: EdgeInsets.zero, title: Text(trUi('تأیید درخواست عضویت')), value: approval, onChanged: (v) => setDialog(() => approval = v)),
          SwitchListTile(contentPadding: EdgeInsets.zero, title: Text(trUi('فقط مدیران پیام بفرستند')), value: adminsPost, onChanged: (v) => setDialog(() => adminsPost = v)),
          SwitchListTile(contentPadding: EdgeInsets.zero, title: Text(trUi('فقط مدیران عضو اضافه کنند')), value: adminsAdd, onChanged: (v) => setDialog(() => adminsAdd = v)),
          SwitchListTile(contentPadding: EdgeInsets.zero, title: Text(trUi('واکنش‌های ایموجی')), value: reactions, onChanged: (v) => setDialog(() => reactions = v)),
          SizedBox(height: 8),
          DropdownButtonFormField<int>(value: ttl, decoration: InputDecoration(labelText: 'حذف خودکار پیام‌ها', border: OutlineInputBorder()),
            items: [DropdownMenuItem(value: 0, child: Text(trUi('خاموش'))), DropdownMenuItem(value: 86400, child: Text(trUi('پس از ۱ روز'))), DropdownMenuItem(value: 604800, child: Text(trUi('پس از ۱ هفته'))), DropdownMenuItem(value: 2592000, child: Text(trUi('پس از ۱ ماه')))],
            onChanged: (v) => setDialog(() => ttl = v ?? 0)),
        ])),
        actions: [TextButton(onPressed: () => Navigator.pop(dialog), child: Text(trUi('لغو'))), FilledButton(onPressed: () => Navigator.pop(dialog, {'public':publicGroup,'approval':approval,'post':adminsPost,'add':adminsAdd,'reactions':reactions,'ttl':ttl}), child: Text(trUi('ذخیره همه تنظیمات')))],
      )));
    if (result == null) return;
    setState(() => saving = true);
    try {
      await supabase.rpc('update_group_settings', params: {
        'p_conversation_id': widget.conversationId,
        'p_title': group['title'],
        'p_description': group['description'],
        'p_avatar_url': group['avatar_url'],
        'p_is_public': result['public'],
        'p_username': group['username'],
        'p_join_approval': result['approval'],
        'p_only_admins_can_post': result['post'],
        'p_only_admins_can_add': result['add'],
        'p_auto_delete_seconds': result['ttl'],
        'p_allow_reactions': result['reactions'],
      });
      await _load();
      if (mounted) showMsg(context, 'تنظیمات گروه ذخیره شد.');
    } catch (e) {
      if (mounted) showMsg(context, 'ذخیره تنظیمات ناموفق بود: ${_friendlyError(e.toString())}');
    } finally { if (mounted) setState(() => saving = false); }
  }

  Future<void> _editRules() async {
    if (!canEditRules || saving) return;
    final titleController = TextEditingController(text: (group['title'] ?? widget.title).toString());
    final descriptionController = TextEditingController(text: (group['description'] ?? '').toString());
    final value = await showDialog<Map<String, String>>(context: context, builder: (ctx) => AlertDialog(
      title: Text(trUi('ویرایش نام و بیو گروه')),
      content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
        TextField(controller: titleController, maxLength: 80, decoration: InputDecoration(labelText: 'نام گروه', border: OutlineInputBorder())),
        SizedBox(height: 12),
        TextField(controller: descriptionController, maxLines: 5, maxLength: 1500, decoration: InputDecoration(labelText: 'بیو، معرفی و قوانین گروه', hintText: 'موضوع و قوانین گروه', border: OutlineInputBorder())),
      ])),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx), child: Text(trUi('انصراف'))),
        FilledButton(onPressed: () {
          final title = titleController.text.trim();
          if (title.isEmpty) { showMsg(ctx, 'نام گروه نمی‌تواند خالی باشد.'); return; }
          Navigator.pop(ctx, {'title': title, 'description': descriptionController.text.trim()});
        }, child: Text(trUi('ذخیره'))),
      ],
    ));
    final newTitle = titleController.text.trim();
    titleController.dispose();
    descriptionController.dispose();
    if (value == null) return;
    setState(() => saving = true);
    try {
      await supabase.rpc('update_group_settings', params: {
        'p_conversation_id': widget.conversationId,
        'p_title': value['title'] ?? newTitle,
        'p_description': value['description'] ?? '',
        'p_avatar_url': group['avatar_url'],
        'p_is_public': group['is_public'] ?? false,
        'p_username': group['username'],
        'p_join_approval': group['join_approval'] ?? false,
        'p_only_admins_can_post': group['only_admins_can_post'] ?? false,
        'p_only_admins_can_add': group['only_admins_can_add'] ?? false,
        'p_auto_delete_seconds': group['auto_delete_seconds'] ?? 0,
        'p_allow_reactions': group['allow_reactions'] ?? true,
      });
      await _load();
      if (mounted) showMsg(context, 'نام و بیو گروه ذخیره شد.');
    } catch (e) {
      if (mounted) showMsg(context, 'ذخیره نام یا بیو ناموفق بود: ${_friendlyError(e.toString())}');
    } finally { if (mounted) setState(() => saving = false); }
  }

  Future<void> _manageMember(Map<String, dynamic> member) async {
    if ((!canRemoveMembers && !isCreator) || saving) return;
    final targetId = (member['user_id'] ?? '').toString();
    final targetRole = (member['role'] ?? 'member').toString();
    final uid = supabase.auth.currentUser?.id;
    if (targetId.isEmpty || targetId == uid || targetId == group['created_by']?.toString() || targetRole == 'owner') {
      showMsg(context, 'حساب خودت یا مالک اصلی گروه قابل اخراج نیست.');
      return;
    }
    final profile = (member['_profile'] as Map?)?.cast<String, dynamic>() ?? <String, dynamic>{};
    final name = (profile['display_name'] ?? profile['username'] ?? 'این عضو').toString();
    final action = await showModalBottomSheet<String>(
      context: context, showDragHandle: true,
      builder: (sheet) => SafeArea(child: Column(mainAxisSize: MainAxisSize.min, children: [
        ListTile(leading: avatar(profile), title: Text(name, style: TextStyle(fontWeight: FontWeight.w800)), subtitle: Text('@${profile['username'] ?? ''}')),
        ListTile(leading: Icon(Icons.person_outline_rounded), title: Text(trUi('مشاهده پروفایل')), onTap: () => Navigator.pop(sheet, 'profile')),
        if (isCreator) ListTile(leading: Icon(targetRole == 'admin' ? Icons.person_rounded : Icons.admin_panel_settings_rounded), title: Text(targetRole == 'admin' ? 'عزل از مدیریت' : 'تعیین به‌عنوان مدیر'), onTap: () => Navigator.pop(sheet, 'role')),
        if (canRemoveMembers) ...[
          ListTile(leading: Icon(Icons.person_remove_alt_1_rounded), title: Text(trUi('اخراج از گروه')), onTap: () => Navigator.pop(sheet, 'remove')),
          ListTile(leading: Icon(Icons.block_rounded, color: Theme.of(sheet).colorScheme.error), title: Text(trUi('محروم کردن از گروه'), style: TextStyle(color: Theme.of(sheet).colorScheme.error)), onTap: () => Navigator.pop(sheet, 'ban')),
        ],
      ])),
    );
    if (!mounted || action == null) return;
    if (action == 'profile') {
      await Navigator.push(context, MaterialPageRoute(builder: (_) => PublicUserProfilePage(profile: {...profile, 'id': targetId})));
      return;
    }
    if (action == 'role') {
      final nextRole = targetRole == 'admin' ? 'member' : 'admin';
      final promote = nextRole == 'admin';
      final confirmed = await showDialog<bool>(context: context, builder: (d) => AlertDialog(
        title: Text(promote ? 'مدیر کردن $name' : 'عزل $name از مدیریت'),
        content: Text(promote ? 'این عضو مدیر گروه می‌شود. اختیاراتش را می‌توانی از مدیریت پیشرفته تنظیم کنی.' : 'نقش این کاربر به عضو عادی تغییر می‌کند.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(d, false), child: Text(trUi('انصراف'))),
          FilledButton(onPressed: () => Navigator.pop(d, true), child: Text(promote ? 'مدیر کردن' : 'عزل از مدیریت')),
        ],
      )) ?? false;
      if (!confirmed) return;
      setState(() => saving = true);
      try {
        await supabase.rpc('set_group_member_role', params: {'p_conversation_id': widget.conversationId, 'p_user_id': targetId, 'p_role': nextRole});
        await _load();
        if (mounted) showMsg(context, promote ? '$name مدیر گروه شد.' : 'مدیریت $name لغو شد.');
      } catch (e) {
        if (mounted) showMsg(context, 'تغییر نقش ناموفق بود: ${_friendlyError(e.toString())}');
      } finally {
        if (mounted) setState(() => saving = false);
      }
      return;
    }
    if (!canRemoveMembers) return;
    final reasonController = TextEditingController();
    final confirmed = await showDialog<bool>(context: context, builder: (d) => AlertDialog(
      title: Text(action == 'ban' ? 'محروم کردن $name' : 'اخراج $name'),
      content: action == 'ban'
        ? TextField(controller: reasonController, maxLines: 3, maxLength: 300, decoration: InputDecoration(labelText: 'دلیل محرومیت (اختیاری)', border: OutlineInputBorder()))
        : Text(trUi('$name از گروه حذف شود؟ در حالت اخراج می‌تواند دوباره درخواست عضویت بدهد.')),
      actions: [
        TextButton(onPressed: () => Navigator.pop(d, false), child: Text(trUi('انصراف'))),
        FilledButton(style: action == 'ban' ? FilledButton.styleFrom(backgroundColor: Theme.of(d).colorScheme.error, foregroundColor: Theme.of(d).colorScheme.onError) : null, onPressed: () => Navigator.pop(d, true), child: Text(action == 'ban' ? 'محروم و اخراج' : 'اخراج')),
      ],
    )) ?? false;
    final reason = reasonController.text.trim();
    reasonController.dispose();
    if (!confirmed) return;
    setState(() => saving = true);
    try {
      if (action == 'ban') {
        await supabase.rpc('ban_group_member', params: {'p_conversation_id': widget.conversationId, 'p_user_id': targetId, 'p_reason': reason.isEmpty ? null : reason});
      } else {
        await supabase.rpc('remove_group_member', params: {'p_conversation_id': widget.conversationId, 'p_user_id': targetId});
      }
      await _load();
      if (mounted) showMsg(context, action == 'ban' ? '$name محروم شد و دیگر نمی‌تواند به گروه بپیوندد.' : '$name از گروه اخراج شد.');
    } catch (e) {
      if (mounted) showMsg(context, 'عملیات انجام نشد: ${_friendlyError(e.toString())}');
    } finally { if (mounted) setState(() => saving = false); }
  }

  Future<void> _addMembers() async {
    final uid=supabase.auth.currentUser!.id;
    final existing=members.map((m)=>m['user_id'].toString()).toSet();
    if (!canAddMembers) { showMsg(context, 'اختیار افزودن عضو برای حساب شما فعال نیست.'); return; }
    final query=TextEditingController();
    final selected=<String>{};
    // Keep one request for the lifetime of the dialog; typing/selecting must not
    // trigger a new profiles query on every StatefulBuilder rebuild.
    final peopleFuture = supabase.from('contacts').select('contact_id')
        .eq('user_id', uid)
        .then<List<String>>((rows) => (rows as List)
            .map((row) => row['contact_id']?.toString() ?? '')
            .where((id) => id.isNotEmpty && !existing.contains(id) && id != uid)
            .toList())
        .then<List<Map<String,dynamic>>>((ids) async {
          if (ids.isEmpty) return <Map<String,dynamic>>[];
          final rows = await supabase.from('profiles')
              .select('id,display_name,username,avatar_url')
              .inFilter('id', ids).limit(150);
          return List<Map<String,dynamic>>.from(rows as List);
        });
    final ids=await showDialog<List<String>>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setDialog)=>AlertDialog(
      title:Text(trUi('دعوت اعضا')),
      content:SizedBox(width:420,height:420,child:Column(children:[
        TextField(controller:query,decoration:InputDecoration(prefixIcon:Icon(Icons.search),hintText:'نام کاربری یا نام'),onChanged:(_)=>setDialog((){})),
        SizedBox(height:8),
        Expanded(child:FutureBuilder<List<Map<String,dynamic>>>(future:peopleFuture,builder:(ctx,snap){
          if(snap.connectionState==ConnectionState.waiting)return Center(child:CircularProgressIndicator());
          if(snap.hasError)return Center(child:Text(trUi('فهرست کاربران بارگذاری نشد')));
          final q=query.text.trim().toLowerCase();
          final people=(snap.data??[]).where((p)=>!existing.contains(p['id'].toString()) && ('${p['display_name']??''} ${p['username']??''}').toLowerCase().contains(q)).toList();
          if(people.isEmpty)return Center(child:Text(q.isEmpty ? 'مخاطب جدیدی در فهرست مخاطبان شما نیست.' : 'مخاطبی با این نام پیدا نشد.'));
          return ListView.builder(itemCount:people.length,itemBuilder:(ctx,i){final p=people[i];final id=p['id'].toString();return CheckboxListTile(value:selected.contains(id),onChanged:(v)=>setDialog(()=>v==true?selected.add(id):selected.remove(id)),secondary:avatar(p),title:Text('${p['display_name']??p['username']??'کاربر'}'),subtitle:Text(p['username']==null?'':'@${p['username']}'));});
        })),
      ])),
      actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:Text(trUi('لغو'))),FilledButton(onPressed:selected.isEmpty?null:()=>Navigator.pop(ctx,selected.toList()),child:Text(trUi('دعوت (${selected.length})')))],
    )));
    query.dispose();
    if(ids==null || ids.isEmpty)return;
    try {
      final selectedIds = ids.where((id) => !existing.contains(id)).toList();
      if (selectedIds.isEmpty) {
        if (mounted) showMsg(context, 'این کاربران از قبل عضو گروه هستند.');
        return;
      }
      final added = await supabase.rpc('add_group_members', params: {'p_conversation_id': widget.conversationId, 'p_user_ids': selectedIds});
      await _load();
      if (mounted) {
        final count = added is num ? added.toInt() : selectedIds.length;
        showMsg(context, count > 0 ? '$count عضو به گروه اضافه شد.' : 'عضو جدیدی اضافه نشد.');
      }
    } catch(e){if(mounted)showMsg(context,'افزودن عضو ناموفق بود: '+_friendlyError(e.toString()));}
  }

  @override Widget build(BuildContext context) {
    final scheme=Theme.of(context).colorScheme;
    if (loading) return Scaffold(appBar: AppBar(title: Text(trUi('پروفایل گروه'))), body: Center(child: CircularProgressIndicator()));
    if (group.isEmpty) return Scaffold(
      appBar: AppBar(title: Text(trUi('پروفایل گروه'))),
      body: Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [
        Icon(Icons.cloud_off_rounded, size: 48, color: scheme.onSurfaceVariant),
        SizedBox(height: 12),
        Text(trUi('اطلاعات گروه بارگذاری نشد. اتصال اینترنت و دسترسی عضویت را بررسی کنید.'), textAlign: TextAlign.center),
        if ((loadError ?? '').isNotEmpty) ...[SizedBox(height: 8), Text(loadError!, maxLines: 3, overflow: TextOverflow.ellipsis, textAlign: TextAlign.center, style: TextStyle(fontSize: 11, color: scheme.onSurfaceVariant))],
        SizedBox(height: 16), FilledButton.icon(onPressed: _load, icon: Icon(Icons.refresh_rounded), label: Text(trUi('تلاش دوباره'))),
      ]))),
    );
    final title='${group['title']??widget.title}';
    final image='${group['avatar_url']??''}';
    final description='${group['description']??''}'.trim();
    return Scaffold(appBar:AppBar(title:Text(trUi('پروفایل گروه'))),body:loading?Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.fromLTRB(16,12,16,28),children:[
      Center(child:Column(children:[
        GestureDetector(onTap: canEditRules ? _changeGroupPhoto : null, child: Stack(alignment: Alignment.bottomRight, children:[CircleAvatar(radius:52,backgroundColor:scheme.primaryContainer,backgroundImage:image.isNotEmpty?NetworkImage(image):null,child:image.isEmpty?Icon(Icons.groups_rounded,size:42,color:scheme.primary):null),if(canEditRules)Container(padding:const EdgeInsets.all(8),decoration:BoxDecoration(color:Colors.black54,shape:BoxShape.circle),child:Icon(Icons.camera_alt_rounded,color:Colors.white,size:17))])),
        SizedBox(height:12),Text(title,textAlign:TextAlign.center,style:TextStyle(fontSize:23,fontWeight:FontWeight.w800)),
        SizedBox(height:4),Text(trUi('${members.length} عضو'),style:TextStyle(color:scheme.onSurfaceVariant)),
        SizedBox(height:12),
        Wrap(alignment:WrapAlignment.center,spacing:8,runSpacing:8,children:[
          if(canAddMembers) FilledButton.icon(
            onPressed:saving?null:_addMembers,
            icon:Icon(Icons.person_add_alt_1_rounded,size:18),
            label:Text(trUi('افزودن عضو')),
          ),
          PopupMenuButton<String>(
            enabled:!saving && (canEditRules || canManageMembers || isCreator),
            tooltip:'گزینه‌های گروه',
            onSelected:(action) async {
              switch(action) {
                case 'edit':
                  await _editRules();
                  break;
                case 'settings':
                  await _openGroupSettings();
                  break;
                case 'members':
                  await Navigator.push(context,MaterialPageRoute(builder:(_)=>GroupManagementPage(conversationId:widget.conversationId,title:title)));
                  if(mounted) await _load();
                  break;
                case 'advanced':
                  await Navigator.push(context,MaterialPageRoute(builder:(_)=>GroupAdvancedAdminPage(conversationId:widget.conversationId,title:title)));
                  if(mounted) await _load();
                  break;
              }
            },
            itemBuilder:(_)=>[
              if(canEditRules) PopupMenuItem(value:'edit',child:Row(children:[Icon(Icons.edit_note_rounded),SizedBox(width:10),Text(trUi('ویرایش نام و توضیحات'))])),
              if(canEditRules) PopupMenuItem(value:'settings',child:Row(children:[Icon(Icons.tune_rounded),SizedBox(width:10),Text(trUi('تنظیمات و اختیارات'))])),
              if(canManageMembers) PopupMenuItem(value:'members',child:Row(children:[Icon(Icons.people_alt_rounded),SizedBox(width:10),Text(trUi('مدیریت اعضا'))])),
              if(isCreator) PopupMenuItem(value:'advanced',child:Row(children:[Icon(Icons.shield_rounded),SizedBox(width:10),Text(trUi('مدیریت پیشرفته'))])),
            ],
            child:Container(
              padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),
              decoration:BoxDecoration(
                border:Border.all(color:scheme.outlineVariant),
                borderRadius:BorderRadius.circular(14),
              ),
              child:Row(mainAxisSize:MainAxisSize.min,children:[
                Icon(Icons.more_horiz_rounded,size:20),SizedBox(width:7),Text(trUi('مدیریت گروه')),
              ]),
            ),
          ),
        ]),
      ])),
      SizedBox(height:20),
      Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
        Row(children:[Icon(Icons.info_outline_rounded),SizedBox(width:8),Text(trUi('درباره و قوانین'),style:TextStyle(fontWeight:FontWeight.w800)),Spacer(),if(canEditRules)Chip(label:Text(trUi('مدیر قابل ویرایش')))]),
        SizedBox(height:8),Text(description.isEmpty?'هنوز توضیح یا قانونی برای این گروه ثبت نشده است.':description,style:TextStyle(height:1.5,color:scheme.onSurfaceVariant)),
      ]))),
      SizedBox(height:14),
      Row(children:[Icon(Icons.people_alt_rounded),SizedBox(width:8),Text(trUi('اعضا  •  ${members.length}'),style:TextStyle(fontSize:17,fontWeight:FontWeight.w800)),Spacer(),Text(trUi('مالک و مدیران در بالا'),style:TextStyle(fontSize:12,color:scheme.onSurfaceVariant))]),
      SizedBox(height:8),
      Card(
        clipBehavior: Clip.antiAlias,
        child: Column(
          children: members.map((m) {
            final p = (m['_profile'] as Map?)?.cast<String, dynamic>() ?? {};
            final role = '${m['role'] ?? 'member'}';
            final roleLabel = role == 'owner' ? 'مالک' : role == 'admin' ? 'مدیر' : 'عضو';
            final memberId = m['user_id']?.toString();
            final currentId = supabase.auth.currentUser?.id;
            final canModerate = canRemoveMembers &&
                memberId != currentId &&
                memberId != group['created_by']?.toString() &&
                role != 'owner';
            return ListTile(
              dense: true,
              visualDensity: VisualDensity.compact,
              minVerticalPadding: 4,
              leading: avatar(p),
              title: Text('${p['display_name'] ?? p['username'] ?? 'کاربر'}', maxLines: 1, overflow: TextOverflow.ellipsis),
              subtitle: Text(p['username'] == null ? '' : '@${p['username']}'),
              trailing: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Chip(
                    visualDensity: VisualDensity.compact,
                    materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                    avatar: Icon(
                      role == 'owner'
                          ? Icons.workspace_premium_rounded
                          : role == 'admin'
                              ? Icons.admin_panel_settings_rounded
                              : Icons.person_rounded,
                      size: 15,
                    ),
                    label: Text(roleLabel),
                  ),
                  if (canModerate)
                    PopupMenuButton<String>(
                      tooltip: 'اقدامات عضو',
                      onSelected: (_) => _manageMember(m),
                      itemBuilder: (context) => [
                        PopupMenuItem(
                          value: 'manage',
                          child: Row(
                            children: [
                              Icon(Icons.shield_outlined),
                              SizedBox(width: 8),
                              Text(trUi('مدیریت / اخراج / محرومیت')),
                            ],
                          ),
                        ),
                      ],
                      icon: Icon(Icons.more_vert_rounded),
                    )
                  else
                    Icon(Icons.chevron_left_rounded),
                ],
              ),
              onTap: p['id'] == null
                  ? null
                  : () => Navigator.push(
                        context,
                        MaterialPageRoute(
                          builder: (_) => PublicUserProfilePage(
                            profile: {...p, 'id': memberId},
                          ),
                        ),
                      ),
            );
          }).toList(),
        ),
      ),
      if(!canEditRules) Padding(padding:const EdgeInsets.only(top:10),child:Text(trUi('ویرایش قوانین فقط در اختیار مالک یا مدیر گروه است.'),style:TextStyle(color:scheme.onSurfaceVariant))),
    ]));
  }
}

class ConversationInfoPage extends StatefulWidget {
  final String conversationId;
  final String fallbackTitle;
  ConversationInfoPage({super.key, required this.conversationId, required this.fallbackTitle});
  @override State<ConversationInfoPage> createState() => _ConversationInfoPageState();
}

class _ConversationInfoPageState extends State<ConversationInfoPage> {
  bool loading = true;
  Map<String,dynamic> conversation = {};
  Map<String,dynamic> peer = {};
  List<Map<String,dynamic>> members = [];

  @override void initState() { super.initState(); _load(); }

  Future<void> _load() async {
    try {
      final uid = supabase.auth.currentUser!.id;
      final c = await supabase.from('conversations').select().eq('id', widget.conversationId).single();
      final type = '${c['type'] ?? 'direct'}';
      final memberRows = List<Map<String,dynamic>>.from(await supabase.from('conversation_members').select('user_id,role,joined_at').eq('conversation_id', widget.conversationId));
      final ids = memberRows.map((m) => m['user_id']).toList();
      Map<String,dynamic> p = {};
      var ms = <Map<String,dynamic>>[];
      if (ids.isNotEmpty) {
        final people = List<Map<String,dynamic>>.from(await supabase.from('profiles').select('id,display_name,username,avatar_url,bio,is_online,last_seen,is_verified').inFilter('id', ids));
        final map = {for(final x in people) x['id'].toString(): x};
        ms = memberRows.map((m) => {...m, '_profile': map[m['user_id'].toString()] ?? {}}).toList();
        if (type == 'direct') {
          final other = ms.firstWhere((m) => '${m['user_id']}' != uid, orElse: () => {'_profile': {}});
          p = Map<String,dynamic>.from(other['_profile'] as Map);
        }
      }
      if (!mounted) return;
      setState(() { conversation = Map<String,dynamic>.from(c); peer = p; members = ms; loading = false; });
    } catch (e) {
      if (!mounted) return;
      setState(() => loading = false);
      showMsg(context, 'اطلاعات گفتگو بارگذاری نشد: ' + _friendlyError(e.toString()));
    }
  }

  @override Widget build(BuildContext context) {
    final type = '${conversation['type'] ?? 'direct'}';
    final title = type == 'direct' ? '${peer['display_name'] ?? peer['username'] ?? widget.fallbackTitle}' : '${conversation['title'] ?? widget.fallbackTitle}';
    final bio = type == 'direct' ? '${peer['bio'] ?? ''}' : '${conversation['description'] ?? ''}';
    final avatarUrl = type == 'direct' ? '${peer['avatar_url'] ?? ''}' : '${conversation['avatar_url'] ?? ''}';
    final scheme = Theme.of(context).colorScheme;
    return Scaffold(
      appBar: AppBar(title: Text(trUi('پروفایل گفتگو'))),
      body: loading ? Center(child: CircularProgressIndicator()) : ListView(
        padding: const EdgeInsets.fromLTRB(16,12,16,32),
        children: [
          Center(child: Column(children: [
            CircleAvatar(radius:54,backgroundColor:scheme.primaryContainer,backgroundImage:avatarUrl.isNotEmpty?NetworkImage(avatarUrl):null,child:avatarUrl.isEmpty?Icon(type=='group'?Icons.groups_rounded:type=='channel'?Icons.campaign_rounded:Icons.person_rounded,size:46,color:scheme.primary):null),
            SizedBox(height:12),
            Row(mainAxisAlignment:MainAxisAlignment.center,children:[Flexible(child:Text(title,textAlign:TextAlign.center,style:TextStyle(fontSize:23,fontWeight:FontWeight.w900))),if(type=='direct'&&peer['is_verified']==true) Padding(padding:EdgeInsets.only(right:5),child:Icon(Icons.verified_rounded,color:Color(0xFF2F9BFF)))]),
            if(type=='direct'&&'${peer['username'] ?? ''}'.isNotEmpty) Text('@'+'${peer['username']}',style:TextStyle(color:scheme.primary,fontWeight:FontWeight.w700)),
            if(type=='direct') Text(peer['is_online']==true?'آنلاین':'آخرین بازدید: '+_homeTime(peer['last_seen']),style:TextStyle(color:scheme.onSurfaceVariant)),
            if(bio.trim().isNotEmpty) Padding(padding:const EdgeInsets.only(top:10),child:Text(bio,textAlign:TextAlign.center,style:TextStyle(height:1.45,color:scheme.onSurfaceVariant))),
            if(type=='direct') ...[
              SizedBox(height:18),
              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  FilledButton.icon(
                    onPressed: () => Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (_) => CallSessionPage(
                          conversationId: widget.conversationId,
                          title: title,
                          video: false,
                        ),
                      ),
                    ),
                    icon: Icon(Icons.call_rounded),
                    label: Text(trUi('تماس صوتی')),
                  ),
                  SizedBox(width:10),
                  OutlinedButton.icon(
                    onPressed: () => Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (_) => CallSessionPage(
                          conversationId: widget.conversationId,
                          title: title,
                          video: true,
                        ),
                      ),
                    ),
                    icon: Icon(Icons.videocam_rounded),
                    label: Text(trUi('تماس تصویری')),
                  ),
                ],
              ),
            ],
          ])),
          SizedBox(height:22),
          if(type=='group'||type=='channel') Card(child:ListTile(leading:Icon(type=='group'?Icons.groups_rounded:Icons.campaign_rounded),title:Text(type=='group'?'اعضای گروه':'اعضای کانال'),subtitle:Text(members.length.toString()+' نفر'),trailing:Icon(Icons.chevron_left_rounded),onTap:type=='group'?()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>GroupProfilePage(conversationId:widget.conversationId,title:title))):null)),
          Card(child:Column(children:[
            ListTile(leading:Icon(Icons.search_rounded),title:Text(trUi('جستجوی داخل گفتگو')),onTap:()=>showSearch(context:context,delegate:MessageSearchDelegate(widget.conversationId))),
            ListTile(leading:Icon(Icons.photo_library_outlined),title:Text(trUi('رسانه‌ها و فایل‌های مشترک')),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>SharedMediaPage(conversationId:widget.conversationId)))),
            
          ])),
          if (type == 'group')
            Card(
              child: ExpansionTile(
                leading: Icon(Icons.people_alt_outlined),
                title: Text(trUi('اعضای گروه')),
                subtitle: Text(trUi('برای دیدن پروفایل هر عضو روی نام او بزنید')),
                children: members.take(50).map((m) {
                  final p = (m['_profile'] as Map?)?.cast<String, dynamic>() ?? <String, dynamic>{};
                  final id = (m['user_id'] ?? p['id'] ?? '').toString();
                  return ListTile(
                    leading: avatar(p),
                    title: Text('${p['display_name'] ?? p['username'] ?? 'کاربر'}'),
                    subtitle: Text('${m['role'] ?? 'member'}'),
                    trailing: Icon(Icons.chevron_left_rounded),
                    onTap: id.isEmpty
                        ? null
                        : () => Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder: (_) => PublicUserProfilePage(profile: {...p, 'id': id}),
                              ),
                            ),
                  );
                }).toList(),
              ),
            ),
        ],
      ),
    );
  }
}

class GlobalSearchDelegate extends SearchDelegate<Map<String,dynamic>?> {
  @override
  List<Widget>? buildActions(BuildContext context) => [
    if (query.isNotEmpty) IconButton(onPressed: () => query = '', icon: Icon(Icons.clear_rounded)),
  ];
  @override
  Widget buildLeading(BuildContext context) => IconButton(onPressed: () => close(context, null), icon: Icon(Icons.arrow_back_rounded));
  @override
  Widget buildResults(BuildContext context) => _results(context);
  @override
  Widget buildSuggestions(BuildContext context) => _results(context);

  Future<Map<String,dynamic>> _search(String value) async {
    final q = value.trim();
    if (q.isEmpty) return {'messages': <Map<String,dynamic>>[], 'users': <Map<String,dynamic>>[], 'chats': <Map<String,dynamic>>[], 'public_chats': <Map<String,dynamic>>[]};
    final uid = supabase.auth.currentUser?.id;
    if (uid == null) return {'messages': <Map<String,dynamic>>[], 'users': <Map<String,dynamic>>[], 'chats': <Map<String,dynamic>>[], 'public_chats': <Map<String,dynamic>>[]};
    final memberRows = await supabase.from('conversation_members').select('conversation_id').eq('user_id', uid).limit(150);
    final ids = (memberRows as List).map((e) => e['conversation_id'].toString()).where((e) => e.isNotEmpty).toSet();
    final usersFuture = supabase.from('profiles').select('id,display_name,username,avatar_url,bio,is_online,is_verified').or('display_name.ilike.%$q%,username.ilike.%$q%').limit(30).then((value) => value);
    final publicFuture = supabase.rpc('search_public_conversations', params: {'p_query': q}).then((value) => value);
    if (ids.isEmpty) {
      final results = await Future.wait<dynamic>([usersFuture, publicFuture]);
      return {
        'messages': <Map<String,dynamic>>[],
        'users': List<Map<String,dynamic>>.from(results[0] as List),
        'chats': <Map<String,dynamic>>[],
        'public_chats': List<Map<String,dynamic>>.from(results[1] as List),
      };
    }
    final chatsFuture = supabase.from('conversations').select('id,type,title,avatar_url,created_at').inFilter('id', ids.toList()).or('title.ilike.%$q%,username.ilike.%$q%').limit(30).then((value) => value);
    final messagesFuture = supabase.from('messages')
        .select('id,conversation_id,body,message_type,created_at,sender_id')
        .inFilter('conversation_id', ids.toList())
        .isFilter('deleted_at', null)
        .ilike('body', '%$q%')
        .order('created_at', ascending: false)
        .limit(50)
        .then((value) => value);
    final results = await Future.wait<dynamic>([usersFuture, chatsFuture, messagesFuture, publicFuture]);
    final publicChats = List<Map<String,dynamic>>.from(results[3] as List)
        .where((c) => !ids.contains(c['id'].toString())).toList();

    // Search must follow the same deletion rules as the chat timeline. Without
    // this filter, messages removed "for me" could still appear in global search.
    var searchMessages = List<Map<String,dynamic>>.from(results[2] as List);
    final searchMessageIds = searchMessages.map((m) => '${m['id']}').toList();
    if (searchMessageIds.isNotEmpty) {
      final hiddenForUser = <String>{};
      try {
        final deletedRows = await supabase
            .from('message_user_deletions')
            .select('message_id')
            .eq('user_id', uid)
            .inFilter('message_id', searchMessageIds)
            .timeout(Duration(seconds: 4));
        hiddenForUser.addAll(List<Map<String,dynamic>>.from(deletedRows)
            .map((row) => '${row['message_id']}'));
      } catch (_) {
        // Keep search usable if deletion metadata is temporarily unavailable;
        // server-deleted messages are already excluded by deleted_at above.
      }
      try {
        final prefs = await SharedPreferences.getInstance();
        for (final message in searchMessages) {
          final conversationId = message['conversation_id']?.toString() ?? '';
          final hiddenIds = prefs.getStringList('arad_hidden_messages_v1_${uid}_${conversationId}') ?? const <String>[];
          if (hiddenIds.contains('${message['id']}')) {
            hiddenForUser.add('${message['id']}');
          }
        }
      } catch (_) {}
      searchMessages.removeWhere((message) => hiddenForUser.contains('${message['id']}'));
    }

    return {
      'users': List<Map<String,dynamic>>.from(results[0] as List),
      'chats': List<Map<String,dynamic>>.from(results[1] as List),
      'messages': searchMessages,
      'public_chats': publicChats,
    };
  }

  Future<void> _openPublicConversation(BuildContext context, Map<String,dynamic> row) async {
    final navigator = Navigator.of(context, rootNavigator: true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final rawId = await supabase.rpc('join_public_conversation', params: {'p_username': row['username']});
      final id = rawId.toString();
      final uid = supabase.auth.currentUser?.id;
      final membership = uid == null ? null : await supabase.from('conversation_members')
          .select('user_id').eq('conversation_id', id).eq('user_id', uid).maybeSingle();
      if (membership == null) {
        close(context, null);
        messenger.showSnackBar(SnackBar(content: Text(trUi('درخواست عضویت ثبت شد؛ پس از تأیید مدیر می‌توانید وارد شوید.'))));
        return;
      }
      final title = (row['title'] ?? row['username'] ?? 'گروه عمومی').toString();
      close(context, null);
      await navigator.push(MaterialPageRoute(builder: (_) => ChatPage(id: id, title: title)));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text(trUi('باز کردن گروه عمومی ناموفق بود: ${_friendlyError(e.toString())}'))));
    }
  }

  Widget _avatar(Map<String,dynamic> row) {
    final url = (row['avatar_url'] ?? '').toString().trim();
    return CircleAvatar(radius: 21, backgroundImage: url.isNotEmpty ? NetworkImage(url) : null, child: url.isEmpty ? Icon(Icons.person_rounded) : null);
  }

  Widget _results(BuildContext context) {
    final q = query.trim();
    if (q.isEmpty) return Center(child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(Icons.search_rounded, size: 54), SizedBox(height: 12), Text(trUi('جستجوی سراسری آراد'), style: TextStyle(fontSize: 18, fontWeight: FontWeight.w900)), SizedBox(height: 6), Text(trUi('کاربر، گفتگو و پیام را یکجا پیدا کنید.')) ]));
    return FutureBuilder<Map<String,dynamic>>(
      future: _search(q),
      builder: (context, snap) {
        if (snap.connectionState == ConnectionState.waiting) return Center(child: CircularProgressIndicator());
        if (snap.hasError) return Center(child: Text('جستجو ناموفق بود: ' + _friendlyError('${snap.error}')));
        final data = snap.data ?? {};
        final users = List<Map<String,dynamic>>.from(data['users'] ?? const []);
        final chats = List<Map<String,dynamic>>.from(data['chats'] ?? const []);
        final publicChats = List<Map<String,dynamic>>.from(data['public_chats'] ?? const []);
        final messages = List<Map<String,dynamic>>.from(data['messages'] ?? const []);
        if (users.isEmpty && chats.isEmpty && publicChats.isEmpty && messages.isEmpty) return Center(child: Text(trUi('نتیجه‌ای پیدا نشد.')));
        return ListView(padding: const EdgeInsets.fromLTRB(8, 8, 8, 24), children: [
          if (users.isNotEmpty) ...[
            const _SearchSectionHeader(title: 'کاربران', icon: Icons.people_alt_rounded),
            ...users.map((p) => ListTile(leading: _avatar(p), title: Row(children: [Flexible(child: Text((p['display_name'] ?? p['username'] ?? 'کاربر').toString(), maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(fontWeight: FontWeight.w800))), if (p['is_verified'] == true) Padding(padding: EdgeInsets.only(right: 5), child: Icon(Icons.verified_rounded, size: 16, color: Color(0xFF2F9BFF))) ]), subtitle: Text((p['username'] ?? '').toString().isEmpty ? (p['bio'] ?? '').toString() : '@' + p['username'].toString()), onTap: () => close(context, {...p, '_kind': 'user'}))),
          ],
          if (chats.isNotEmpty) ...[
            const _SearchSectionHeader(title: 'گفتگوها', icon: Icons.forum_rounded),
            ...chats.map((c) { final type = (c['type'] ?? 'direct').toString(); final icon = type == 'group' ? Icons.groups_rounded : type == 'channel' ? Icons.campaign_rounded : Icons.person_rounded; final url = (c['avatar_url'] ?? '').toString(); return ListTile(leading: CircleAvatar(backgroundImage: url.isNotEmpty ? NetworkImage(url) : null, child: url.isEmpty ? Icon(icon) : null), title: Text((c['title'] ?? c['username'] ?? (type == 'group' ? 'گروه' : type == 'channel' ? 'کانال' : 'گفتگو')).toString(), style: TextStyle(fontWeight: FontWeight.w800)), subtitle: Text(type == 'channel' ? 'کانال' : type == 'group' ? 'گروه' : 'گفتگوی خصوصی'), onTap: () => close(context, {...c, '_kind': 'chat'})); }),
          ],
          if (publicChats.isNotEmpty) ...[
            const _SearchSectionHeader(title: 'گروه‌ها و کانال‌های عمومی', icon: Icons.public_rounded),
            ...publicChats.map((c) { final type = (c['type'] ?? 'group').toString(); final url = (c['avatar_url'] ?? '').toString(); return ListTile(leading: CircleAvatar(backgroundImage: url.isNotEmpty ? NetworkImage(url) : null, child: url.isEmpty ? Icon(type == 'channel' ? Icons.campaign_rounded : Icons.groups_rounded) : null), title: Text((c['title'] ?? c['username'] ?? 'گروه عمومی').toString(), maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(fontWeight: FontWeight.w800)), subtitle: Text('@${c['username'] ?? ''} • ${type == 'channel' ? 'کانال عمومی' : 'گروه عمومی'}'), trailing: Icon(Icons.arrow_forward_rounded), onTap: () => _openPublicConversation(context, c)); }),
          ],
          if (messages.isNotEmpty) ...[
            const _SearchSectionHeader(title: 'پیام‌ها', icon: Icons.chat_bubble_outline_rounded),
            ...messages.map((m) => ListTile(leading: CircleAvatar(child: Icon(Icons.message_rounded)), title: Text((m['body'] ?? 'پیام').toString(), maxLines: 2, overflow: TextOverflow.ellipsis, style: TextStyle(fontWeight: FontWeight.w700)), subtitle: Text(_homeTime(m['created_at'])), onTap: () => close(context, {...m, '_kind': 'message'}))),
          ],
        ]);
      },
    );
  }
}

class _AmbientChatGlow extends StatefulWidget {
  final bool enabled;
  final Color primary;
  const _AmbientChatGlow({required this.enabled, required this.primary});

  @override
  State<_AmbientChatGlow> createState() => _AmbientChatGlowState();
}

class _AmbientChatGlowState extends State<_AmbientChatGlow> with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(seconds: 12),
    );
    if (widget.enabled) _controller.repeat(reverse: true);
  }

  @override
  void didUpdateWidget(covariant _AmbientChatGlow oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.enabled && !_controller.isAnimating) {
      _controller.repeat(reverse: true);
    } else if (!widget.enabled && _controller.isAnimating) {
      _controller.stop();
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.enabled) return const SizedBox.shrink();
    return Positioned.fill(
      child: IgnorePointer(
        child: RepaintBoundary(
          child: AnimatedBuilder(
            animation: _controller,
            builder: (context, _) {
              final t = Curves.easeInOutSine.transform(_controller.value);
              return Stack(children: [
                Positioned(
                  top: -92 + (t * 38),
                  right: -76 + (t * 28),
                  width: 285,
                  height: 285,
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      gradient: RadialGradient(colors: [
                        widget.primary.withValues(alpha: .17),
                        widget.primary.withValues(alpha: .055),
                        Colors.transparent,
                      ]),
                    ),
                  ),
                ),
                Positioned(
                  bottom: 54 + (t * 34),
                  left: -96 + (t * 22),
                  width: 300,
                  height: 300,
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      gradient: RadialGradient(colors: [
                        Color(0xFF36B8FF).withValues(alpha: .105),
                        Color(0xFF36B8FF).withValues(alpha: .025),
                        Colors.transparent,
                      ]),
                    ),
                  ),
                ),
              ]);
            },
          ),
        ),
      ),
    );
  }
}

class ChatPage extends StatefulWidget {
  final String id;
  final String title;
  final String? targetMessageId;

  ChatPage({super.key, required this.id, required this.title, this.targetMessageId});

  @override
  State<ChatPage> createState() => _ChatPageState();
}

class _ChatPageState extends State<ChatPage> {
  List<Map<String, dynamic>> get _displayTimelineItems {
    final output = <Map<String, dynamic>>[];
    DateTime? previousDay;
    for (final item in timelineItems) {
      final parsed = DateTime.tryParse('${item['created_at'] ?? ''}')?.toLocal();
      if (parsed != null) {
        final day = DateTime(parsed.year, parsed.month, parsed.day);
        if (previousDay == null || day != previousDay) {
          output.add({'__kind': 'date_separator', 'created_at': item['created_at'], 'label': _dateLabel(item['created_at'])});
          previousDay = day;
        }
      }
      output.add(item);
    }
    return output;
  }

  Widget _systemTimelineTile(Map<String, dynamic> item) {
    final scheme = Theme.of(context).colorScheme;
    final actorId = item['actor_id']?.toString() ?? '';
    final actor = profiles[actorId];
    final name = (actor?['display_name'] ?? actor?['username'] ?? 'کاربر').toString();
    final targetId = item['target_user_id']?.toString() ?? '';
    final target = profiles[targetId];
    final targetName = (target?['display_name'] ?? target?['username'] ?? 'کاربر').toString();
    final action = item['system_action'];
    final label = action == 'group_created'
        ? '$name این گروه را ایجاد کرد'
        : action == 'member_added'
            ? '$name، $targetName را به گروه اضافه کرد'
            : action == 'joined_by_link'
                ? '$targetName از طریق لینک به گروه پیوست'
                : action == 'join_requested_by_link'
                    ? '$targetName از طریق لینک درخواست عضویت فرستاد'
                    : action == 'joined_by_public_username'
                        ? '$targetName از طریق نام کاربری عمومی پیوست'
                        : action == 'join_requested_by_public_username'
                            ? '$targetName از نام کاربری عمومی درخواست عضویت فرستاد'
                            : action == 'joined_after_approval'
                                ? '$targetName پس از تأیید مدیر به گروه پیوست'
                                : 'رویداد گروه';
    return Center(
      child: Container(
        margin: const EdgeInsets.symmetric(vertical: 8),
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
        decoration: BoxDecoration(
          color: scheme.secondaryContainer.withValues(alpha: .68),
          borderRadius: BorderRadius.circular(16),
        ),
        child: Text(label, textAlign: TextAlign.center,
          style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: scheme.onSecondaryContainer)),
      ),
    );
  }

  Widget _dateSeparator(String label) {
    final scheme = Theme.of(context).colorScheme;
    return Center(
      child: Container(
        margin: const EdgeInsets.symmetric(vertical: 10),
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 6),
        decoration: BoxDecoration(
          color: scheme.surface.withValues(alpha: .88),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: scheme.outline.withValues(alpha: .14)),
        ),
        child: Text(label, style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.w800, color: scheme.onSurfaceVariant)),
      ),
    );
  }
  final text = TextEditingController();
  List<Map<String, dynamic>> messages = [];
  List<Map<String, dynamic>> callSessions = [];
  List<Map<String, dynamic>> timelineItems = [];
  Map<String, Map<String, dynamic>> profiles = {};
  Map<String, List<Map<String, dynamic>>> reactions = {};
  Map<String, List<Map<String, dynamic>>> readReceipts = {};
  Map<String, Map<String, dynamic>> attachments = {};
  RealtimeChannel? channel;
  final ScrollController _messagesScroll = ScrollController();
  final FocusNode _composerFocus = FocusNode();
  final GlobalKey _latestMessageKey = GlobalKey();
  final Map<String, GlobalKey> _messageKeys = <String, GlobalKey>{};
  bool _didJumpToTargetMessage = false;
  bool _chatLoadInProgress = false;
  bool _chatLoadQueued = false;
  bool loading = true;
  bool _isSyncing = true;
  bool sending = false;
  bool _chatNotificationsMuted = false;
  Map<String, dynamic>? replyMessage;
  final AudioRecorder _voiceRecorder = AudioRecorder();
  final AudioPlayer _voicePlayer = AudioPlayer();
  bool recordingVoice = false;
  bool _voiceStarting = false;
  bool _voiceFinishing = false;
  bool voiceLocked = false;
  bool voiceCancelArmed = false;
  String _chatType = 'direct';
  String? _localChatTitle;
  String _groupAvatarUrl = '';
  String _directPeerId = '';
  List<Map<String, dynamic>> _mentionSuggestions = [];
  int _mentionStart = -1;
  int _groupMemberCount = 0;
  int _groupOnlineCount = 0;
  DateTime? _voiceStartedAt;
  Timer? _voiceTimer;
  int voiceSeconds = 0;
  double voiceAmplitude = 0;
  List<double> voiceWaveform = [];
  StreamSubscription<Amplitude>? _voiceAmplitudeSub;
  Timer? _keyboardScrollTimer;
  double _lastKeyboardInset = 0;
  bool _showJumpToLatest = false;
  bool _keepLatestVisibleOnKeyboard = false;
  final Set<String> _locallyHiddenMessageIds = <String>{};
  bool _localHiddenIdsLoaded = false;

  void _onMessagesScroll() {
    if (!_messagesScroll.hasClients || !mounted) return;
    final distance = _messagesScroll.position.maxScrollExtent - _messagesScroll.position.pixels;
    final show = distance > 220;
    if (show != _showJumpToLatest) setState(() => _showJumpToLatest = show);
  }

  void _onComposerFocus() {
    // Preserve the current reading position when the keyboard opens.
  }

  void _scheduleKeyboardScroll() {
    if (!_keepLatestVisibleOnKeyboard) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_composerFocus.hasFocus || !_messagesScroll.hasClients) return;
      _messagesScroll.jumpTo(_messagesScroll.position.maxScrollExtent);
    });
  }

  void _jumpToLatest() {
    if (!_messagesScroll.hasClients) return;
    _messagesScroll.animateTo(_messagesScroll.position.maxScrollExtent,
      duration: Duration(milliseconds: 260), curve: Curves.easeOutCubic);
  }

  void _scrollToLatestForKeyboard() {
    if (!mounted || !_messagesScroll.hasClients) return;
    final position = _messagesScroll.position;
    if (!position.hasContentDimensions) return;

    // First make the actual last bubble visible. This is more reliable than
    // relying only on maxScrollExtent while Android is animating the IME.
    final latestContext = _latestMessageKey.currentContext;
    if (_lastKeyboardInset > 0 && latestContext != null) {
      Scrollable.ensureVisible(
        latestContext,
        alignment: 1.0,
        duration: Duration(milliseconds: 120),
        curve: Curves.easeOutCubic,
        alignmentPolicy: ScrollPositionAlignmentPolicy.keepVisibleAtEnd,
      );
    }

    final target = position.maxScrollExtent;
    if ((position.pixels - target).abs() < 2) return;
    // After the keyboard resize settles, force the list to its real bottom.
    // The extra bottom padding keeps the final bubble above the composer/IME.
    if (_lastKeyboardInset > 0) {
      position.jumpTo(target);
    } else {
      position.animateTo(
        target,
        duration: Duration(milliseconds: 180),
        curve: Curves.easeOutCubic,
      );
    }
  }

  Future<String?> _attachmentUrl(String path) async {
    if (path.isEmpty) return null;
    try {
      return await supabase.storage.from('chat-media').createSignedUrl(path, 3600);
    } catch (_) {
      return null;
    }
  }

  Future<void> _playAttachment(String messageId) async {
    try {
      final a = attachments[messageId];
      final path = a?['storage_path']?.toString() ?? '';
      if (path.isEmpty) throw Exception('مسیر فایل صوتی خالی است');
      final bytes = await supabase.storage.from('chat-media').download(path);
      if (bytes.isEmpty) throw Exception('فایل صوتی خالی است');
      await _voicePlayer.stop();
      final mime = (a?['mime_type'] ?? 'audio/mp4').toString();
      await _voicePlayer.play(BytesSource(bytes, mimeType: mime));
    } catch (e) {
      if (mounted) showMsg(context, 'پخش فایل صوتی ناموفق بود: $e');
    }
  }

  Future<void> _openImage(Map<String, dynamic> m) async {
    final a = attachments['${m['id']}'];
    final path = a?['storage_path']?.toString() ?? '';
    if (path.isEmpty) { if (mounted) showMsg(context, 'تصویر پیدا نشد'); return; }
    final url = await _attachmentUrl(path);
    if (!mounted || url == null || url.isEmpty) { if (mounted) showMsg(context, 'باز کردن تصویر ناموفق بود'); return; }
    await showDialog<void>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: .88),
      builder: (dialogContext) => Dialog(
        backgroundColor: Colors.transparent,
        insetPadding: const EdgeInsets.all(12),
        child: GestureDetector(
          onTap: () => Navigator.pop(dialogContext),
          child: InteractiveViewer(minScale: .8, maxScale: 4, child: ClipRRect(borderRadius: BorderRadius.circular(18), child: Image.network(url, fit: BoxFit.contain))),
        ),
      ),
    );
  }

  Widget _voicePlayButton(String messageId) {
    final a = attachments[messageId];
    final durationMs = (a?['duration_ms'] as num?)?.toInt() ?? 0;
    final path = a?['storage_path']?.toString() ?? '';
    if (path.isEmpty) {
      return SizedBox(width: 250, child: Text(trUi('فایل صوتی در دسترس نیست.')));
    }
    return VoiceMessagePlayer(
      initialDurationMs: durationMs,
      mine: false,
      mimeType: (a?['mime_type'] ?? 'audio/mp4').toString(),
      loadAudio: () async {
        final bytes = await supabase.storage.from('chat-media').download(path);
        if (bytes.isEmpty) throw Exception('فایل صوتی خالی است');
        return bytes;
      },
    );
  }

  String _time(dynamic value) {
    final dt = DateTime.tryParse('$value')?.toLocal();
    if (dt == null) return '';
    return '${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}';
  }

  String _dateLabel(dynamic value) {
    final dt = DateTime.tryParse('$value')?.toLocal();
    if (dt == null) return '';
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final day = DateTime(dt.year, dt.month, dt.day);
    final diff = today.difference(day).inDays;
    if (diff == 0) return 'امروز';
    if (diff == 1) return 'دیروز';
    const months = ['ژانویه', 'فوریه', 'مارس', 'آوریل', 'مه', 'ژوئن', 'ژوئیه', 'اوت', 'سپتامبر', 'اکتبر', 'نوامبر', 'دسامبر'];
    return '${dt.day} ${months[dt.month - 1]} ${dt.year}';
  }

  String _senderName(Map<String, dynamic> m) {
    final p = profiles['${m['sender_id']}'];
    if (p == null) return m['sender_id'] == supabase.auth.currentUser?.id ? 'شما' : 'کاربر';
    return '${p['display_name'] ?? p['username'] ?? 'کاربر'}';
  }

