  Future<void> _showMessageInfo(Map<String, dynamic> message) async {
    final created = message['created_at']?.toString() ?? 'نامشخص';
    final edited = message['edited_at'] != null;
    final sentAt = DateTime.tryParse(created)?.toLocal();
    final readAt = DateTime.tryParse('${message['read_at'] ?? ''}')?.toLocal();
    String stamp(DateTime? value) => value == null ? 'نامشخص' : '${value.year}/${value.month.toString().padLeft(2, '0')}/${value.day.toString().padLeft(2, '0')} - ${value.hour.toString().padLeft(2, '0')}:${value.minute.toString().padLeft(2, '0')}:${value.second.toString().padLeft(2, '0')}';
    final pending = message['__pending'] == true;
    final receipts = readReceipts['${message['id']}'] ?? <Map<String, dynamic>>[];
    final readerIds = receipts.map((r) => r['reader_id']?.toString() ?? '').where((id) => id.isNotEmpty).toSet();
    final readerNames = readerIds.map((id) => (profiles[id]?['display_name'] ?? profiles[id]?['username'] ?? 'کاربر')).join('، ');
    final isMine = message['sender_id'] == supabase.auth.currentUser?.id;
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(trUi('جزئیات پیام')),
        content: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(trUi('فرستنده: ') + _senderName(message)),
              SizedBox(height: 8),
              Text(trUi('نوع پیام: ') + (message['message_type']?.toString() ?? 'text')),
              SizedBox(height: 8),
              Text(trUi('زمان ارسال: ') + stamp(sentAt)),
              SizedBox(height: 8),
              Text(
                trUi('وضعیت: ') +
                    (pending
                        ? trUi('در حال ارسال')
                        : ((readerIds.isNotEmpty || message['read_at'] != null)
                            ? '${trUi('خوانده شده توسط')} ${readerIds.isNotEmpty ? readerIds.length : trUi('حداقل یک نفر')} ${trUi('نفر')}'
                            : (isMine
                                ? trUi('ارسال شده؛ هنوز رسید خواندن ثبت نشده')
                                : trUi('دریافت شده')))),
              ),
              if (readerIds.isNotEmpty && isMine) ...[
                SizedBox(height: 8),
                Text(trUi('خوانده‌شده توسط:')),
                SizedBox(height: 4),
                Text(readerNames),
              ],
              if (readAt != null) ...[
                SizedBox(height: 8),
                Text(trUi('زمان خواندن: ') + stamp(readAt)),
              ],
              if (edited) ...[
                SizedBox(height: 8),
                Text(trUi('وضعیت: ویرایش شده')),
              ],
              SizedBox(height: 8),
              SelectableText(
                trUi('شناسه پیام: ') +
                    (message['id']?.toString() ?? trUi('نامشخص')),
                style: TextStyle(
                  fontSize: 11,
                  color: Theme.of(dialogContext).colorScheme.onSurfaceVariant,
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: Text(trUi('بستن')),
          ),
        ],
      ),
    );
  }
