                        color: voiceLocked ? scheme.primary : scheme.onSurfaceVariant,
                      ),
                      IconButton.filled(
                        tooltip: trUi('پایان ضبط و ارسال ویس'),
                        visualDensity: VisualDensity.compact,
                        onPressed: sending || _voiceFinishing ? null : () => _finishVoiceRecording(),
