                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                          colors: [
                            scheme.surface.withValues(alpha: dark ? .58 : .66),
                            scheme.primary.withValues(alpha: dark ? .13 : .08),
                            scheme.surface.withValues(alpha: dark ? .46 : .56),
                          ],
                        ),
                        borderRadius: BorderRadius.circular(22),
                        border: Border.all(
                          color: scheme.primary.withValues(alpha: dark ? .24 : .14),
                          width: 1.1,
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: scheme.primary.withValues(alpha: dark ? .12 : .07),
                            blurRadius: 14,
                            spreadRadius: -5,
                            offset: Offset(0, 3),
                          ),
                          BoxShadow(
                            color: Colors.white.withValues(alpha: dark ? .035 : .62),
                            blurRadius: 2,
                            offset: Offset(0, -1),
                          ),
                        ],
                      ),
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.end,
                        children: [
                          IconButton(
                            style: IconButton.styleFrom(
                              backgroundColor: Colors.transparent,
                              foregroundColor: scheme.onSurfaceVariant,
                              shape: CircleBorder(),
                              padding: const EdgeInsets.all(10),
                            ),
                            onPressed: _showChatEmojiPicker,
                            tooltip: trUi('اموجی'),
                            icon: Icon(Icons.emoji_emotions_rounded, color: scheme.primary),
                          ),
                          Expanded(
                            child: TextField(
                              controller: text,
                              focusNode: _composerFocus,
                              contextMenuBuilder: (context, editableTextState) {
                                final selection = text.selection;
                                final hasSelection = selection.isValid &&
                                    !selection.isCollapsed &&
                                    selection.start >= 0 &&
                                    selection.end <= text.text.length;
                                if (!hasSelection) {
                                  return AdaptiveTextSelectionToolbar.buttonItems(
                                    anchors: editableTextState.contextMenuAnchors,
                                    buttonItems: editableTextState.contextMenuButtonItems,
                                  );
                                }
                                String transform(String value, String action) {
                                  var result = value.trim().replaceAll(RegExp(r'\s+'), ' ');
                                  if (action == 'formal') {
                                    result = result
                                        .replaceAll('سلام', 'سلام و احترام')
                                        .replaceAll('مرسی', 'تشکر')
                                        .replaceAll('ممنون', 'سپاسگزارم')
                                        .replaceAll('hey ', 'Hello ')
                                        .replaceAll('thanks', 'Thank you');
                                  } else if (action == 'friendly') {
                                    if (result.isNotEmpty && !RegExp(r'[😊🙂😄❤️🙏👍]$').hasMatch(result)) {
                                      result = '$result 😊';
                                    }
                                  } else if (action == 'short') {
                                    final parts = result.split(RegExp(r'(?<=[.!?،؛])\s+|،\s+'));
                                    if (parts.length > 1) result = parts.first.trim();
                                  } else {
                                    result = result
                                        .replaceAll(RegExp(r'\s+([،؛:!?.,])'), r'$1')
                                        .replaceAll(RegExp(r'([،؛:!?.,])(?=\S)'), r'$1 ')
                                        .trim();
                                    if (aradLanguageController.locale.languageCode == 'en' && result.isNotEmpty) {
                                      result = result[0].toUpperCase() + result.substring(1);
                                    }
                                  }
                                  return result;
                                }
                                void applyEdit(String action) {
                                  final current = text.value;
                                  final start = current.selection.start;
                                  final end = current.selection.end;
                                  if (start < 0 || end <= start || end > current.text.length) return;
                                  final selected = current.text.substring(start, end);
                                  final replacement = transform(selected, action);
                                  text.value = current.copyWith(
                                    text: current.text.replaceRange(start, end, replacement),
                                    selection: TextSelection.collapsed(offset: start + replacement.length),
                                    composing: TextRange.empty,
                                  );
                                  _composerFocus.requestFocus();
                                  if (mounted) setState(() {});
                                }
                                final items = <ContextMenuButtonItem>[
                                  ...editableTextState.contextMenuButtonItems,
                                  ContextMenuButtonItem(
                                    label: trUi('بهبود نگارش'),
                                    onPressed: () {
                                      editableTextState.hideToolbar();
                                      applyEdit('improve');
                                    },
                                  ),
                                  ContextMenuButtonItem(
                                    label: trUi('رسمی‌تر'),
                                    onPressed: () {
                                      editableTextState.hideToolbar();
                                      applyEdit('formal');
                                    },
                                  ),
                                  ContextMenuButtonItem(
                                    label: trUi('صمیمی‌تر'),
                                    onPressed: () {
                                      editableTextState.hideToolbar();
                                      applyEdit('friendly');
                                    },
                                  ),
                                  ContextMenuButtonItem(
                                    label: trUi('کوتاه‌تر'),
                                    onPressed: () {
                                      editableTextState.hideToolbar();
                                      applyEdit('short');
                                    },
                                  ),
                                ];
                                return AdaptiveTextSelectionToolbar.buttonItems(
                                  anchors: editableTextState.contextMenuAnchors,
                                  buttonItems: items,
                                );
                              },
                              onChanged: (value) {
                                _updateMentionSuggestions(value);
                                // Rebuild the composer immediately so the right-hand
                                // action switches between microphone and send.
                                if (mounted) setState(() {});
                              },
                              // Send-button taps must not unfocus the composer or dismiss the keyboard.
                              onTapOutside: (_) {},
                              minLines: 1,
                              maxLines: 4,
                              textInputAction: TextInputAction.newline,
                              decoration: InputDecoration(
                                hintText: trUi('پیام خود را بنویسید…'),
                                filled: true,
                                fillColor: Colors.transparent,
                                hintStyle: TextStyle(
                                  color: scheme.onSurfaceVariant,
                                  fontWeight: FontWeight.w500,
                                ),
                                border: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(19),
                                  borderSide: BorderSide.none,
                                ),
                                contentPadding: const EdgeInsets.symmetric(horizontal: 11, vertical: 9),
                                isDense: true,
                              ),
                            ),
                          ),
                          SizedBox(width: 3),
                          IconButton(
                            style: IconButton.styleFrom(
                              backgroundColor: scheme.surface.withValues(alpha: dark ? .20 : .28),
                              foregroundColor: scheme.primary,
                              shape: CircleBorder(),
                              padding: const EdgeInsets.all(10),
                            ),
                            onPressed: _showAttachmentPanel,
                            tooltip: trUi('پیوست‌ها'),
                            icon: Icon(Icons.attach_file_rounded, color: scheme.primary, size: 27),
                          ),
                          // Telegram-style single action at the far right:
                          // send replaces the microphone as soon as text is entered.
                          if (text.text.trim().isNotEmpty)
                            IconButton(
                              tooltip: trUi('ارسال پیام'),
                              style: IconButton.styleFrom(
                                backgroundColor: scheme.primary,
                                foregroundColor: Colors.white,
                                shape: CircleBorder(),
                                minimumSize: Size(48, 48),
                                tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                                visualDensity: VisualDensity.compact,
                                padding: const EdgeInsets.all(11),
                              ),
                              onPressed: sending ? null : sendText,
                              icon: sending
                                  ? SizedBox(width: 19, height: 19, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                                  : Icon(Icons.send_rounded, size: 24),
                            )
                          else
                            IconButton(
                              style: IconButton.styleFrom(
                                backgroundColor: scheme.primary,
                                foregroundColor: Colors.white,
                                shape: CircleBorder(),
                                minimumSize: Size(48, 48),
                                tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                                visualDensity: VisualDensity.compact,
                                padding: const EdgeInsets.all(11),
                              ),
                              onPressed: _voiceStarting
                                  ? null
                                  : (recordingVoice
                                      ? (sending || _voiceFinishing || voiceLocked ? null : () => _finishVoiceRecording())
                                      : toggleVoiceRecording),
                              tooltip: _voiceStarting
                                  ? 'در حال آماده‌سازی میکروفون'
                                  : (recordingVoice
                                      ? (voiceLocked ? 'ضبط قفل است؛ از دکمه ارسال استفاده کنید' : 'پایان ضبط و ارسال ویس')
                                      : trUi('ضبط ویس')),
                              icon: _voiceStarting
                                  ? SizedBox(width: 19, height: 19, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                                  : Icon(recordingVoice ? Icons.send_rounded : Icons.mic_rounded, color: Colors.white, size: 27),
                            ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ],
            ),
          ],
        ),
        ),
      ),
    );
  }}
class _ChatVideoAttachment extends StatefulWidget {
  final String storagePath;
  const _ChatVideoAttachment({required this.storagePath});
  @override State<_ChatVideoAttachment> createState() => _ChatVideoAttachmentState();
}

class _ChatVideoAttachmentState extends State<_ChatVideoAttachment> {
  VideoPlayerController? _controller;
  String? _error;
  @override void initState() { super.initState(); _load(); }

  Future<void> _load() async {
    try {
      final url = await supabase.storage.from('chat-media').createSignedUrl(widget.storagePath, 3600);
      final c = VideoPlayerController.networkUrl(Uri.parse(url));
      await c.initialize();
      await c.setLooping(false);
      if (mounted) setState(() => _controller = c);
    } catch (e) {
      if (mounted) setState(() => _error = 'پخش ویدئو ناموفق بود');
    }
  }

  @override Widget build(BuildContext context) {
    final c = _controller;
    if (_error != null) return Row(mainAxisSize: MainAxisSize.min, children: [Icon(Icons.video_file_rounded), SizedBox(width: 8), Text(_error!)]);
    if (c == null || !c.value.isInitialized) return SizedBox(width: 250, height: 150, child: Center(child: CircularProgressIndicator()));
    return ClipRRect(
      borderRadius: BorderRadius.circular(14),
      child: SizedBox(
        width: 270,
        child: AspectRatio(
          aspectRatio: c.value.aspectRatio,
          child: Stack(
            alignment: Alignment.center,
            children: [
              VideoPlayer(c),
              IconButton.filledTonal(
                onPressed: () async {
                  if (c.value.isPlaying) { await c.pause(); } else { await c.play(); }
                  if (mounted) setState(() {});
                },
                icon: Icon(c.value.isPlaying ? Icons.pause_rounded : Icons.play_arrow_rounded),
              ),
              Positioned(
                left: 8, right: 8, bottom: 4,
                child: VideoProgressIndicator(c, allowScrubbing: true, padding: const EdgeInsets.symmetric(vertical: 5)),
              ),
            ],
          ),
        ),
      ),
    );
  }

  @override void dispose() { _controller?.dispose(); super.dispose(); }
}

class _SearchSectionHeader extends StatelessWidget {
